["actions"] = {
["start"] = {
},
["finish"] = {
},
["init"] = {
["custom"] = "\nlocal prevLineId = 0\nlocal result = nil\n\n-- Callbacks don't have access to aura_env, so need to set it as a global\n_G.WA_LOOT_MSG_FILTER_CONFIG = aura_env.config\n\nlocal Log = function(msg)\n    if (_G.WA_LOOT_MSG_FILTER_CONFIG.debugLogging == true) then\n        print(msg);\n    end\nend\n\nlocal FilterItems = function(_, event, msg, playerName, languageName, channelName, playerName2, specialFlags, zoneChannelID, channelIndex, channelBaseName, languageID, lineID, guid, bnSenderID, isMobile, isSubtitle, hideSenderInLetterbox, supressRaidIcons)\n    \n    -- Sometimes this invokes multiple times per loot line so skip if it's a duplicate\n    if (lineID == prevLineId) then\n        return result\n    end\n    \n    prevLineId, result = lineID, nil\n    Log(\"Found message: \" .. msg)\n    \n    local itemIds = _G.WA_LOOT_MSG_FILTER_CONFIG.itemBlocklist\n    \n    for itemId in gmatch(itemIds, \"%S+\") do\n        Log(\"Checking itemId:\" .. itemId)\n        if (msg:find(\"item:\" .. itemId)) then\n            Log(\"Found Item, filtering\")\n            result = true\n            return result\n        end\n    end\nend\n\nChatFrame_AddMessageEventFilter(\"CHAT_MSG_LOOT\", FilterItems)\n",
["do_custom"] = true,
},
},
