["customText"] = "function()\n    if aura_env.state then\n        local unit = aura_env.state.unit and UnitExists(aura_env.state.unit) and NSAPI:Shorten(aura_env.state.unit, 8) or \"\"\n        local healer = \"\"\n        local role = \"\"\n        if aura_env.state.healer and UnitExists(aura_env.state.healer) then\n            healer, role = NSAPI:Shorten(aura_env.state.healer, 8, true)\n        end\n        role = role or \"\"\n        return unit, role..healer\n    end\nend",
["cooldownSwipe"] = true,
["sparkRotationMode"] = "AUTO",
["cooldownEdge"] = false,
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["debuffType"] = "HELPFUL",
["event"] = "Combat Log",
["unit"] = "player",
["spellIds"] = {
},
["events"] = "NS_SWARM_LIST NS_SWARM_LIST_READY CLEU:SPELL_AURA_REMOVED",
["custom"] = "function(s, e, ...)\n    if e == \"OPTIONS\" then\n        for i=1, 3 do\n            \n            s[i] = {\n                show = true,\n                progressType = \"static\",\n                unit = \"player\",\n                healer = \"player\",\n                value = 100,\n                red = i == 3,\n                total = 100,\n                index = i,\n                pos = i,\n                ready = i == 1,\n                changed = true,\n                autoHide = false,\n            }\n        end\n        return true\n        \n    elseif e == \"NS_SWARM_LIST\" and ... then\n        local pos, unit, healer = ...\n        local G = UnitGUID(unit)\n        s[G] = {\n            show = true,\n            progressType = \"static\",\n            unit = unit,\n            healer = healer,\n            red = (WA_GetUnitAura(unit, aura_env.markred, aura_env.filter) and true) or false,\n            value = 100,\n            total = 100,\n            index = pos,\n            pos = pos,\n            ready = false,\n            changed = true,\n            autoHide = false,\n        }\n        return true\n    elseif e == \"NS_SWARM_LIST_READY\" and ... then\n        local G = ...\n        if s[G] then\n            s[G].ready = true\n            s[G].changed = true\n            return true\n        end\n    else\n        local timestamp, subevent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID = ... -- full CLEU\n        \n        if spellID == aura_env.debuff and subevent == \"SPELL_AURA_REMOVED\" and s[destGUID] then\n            s[destGUID].show = false\n            s[destGUID].changed = true\n            return true\n        end\n    end\nend\n\n\n\n",
