["actions"] = {
["start"] = {
["custom"] = "if aura_env.config.CombatRingClassColor then\n    local c = RAID_CLASS_COLORS[select(2,UnitClass(\"player\"))]\n    aura_env.region:Color(c.r, c.g, c.b,1)\nelse\n    local color = aura_env.config.CombatRingColor\n    aura_env.region:Color(color[1], color[2], color[3], color[4])\nend\n\n\n\n\n\n\n\n\n",
["do_custom"] = true,
},
["finish"] = {
},
["init"] = {
