["cooldownSwipe"] = false,
["sparkRotationMode"] = "AUTO",
["cooldownEdge"] = false,
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["customVariables"] = "{\n    unitType = {\n        display = \"Unit Type\",\n        type = \"select\",\n        values = {\n            nameplate = \"Nameplates\", \n            unitframe = \"Unit Frame\", \n        }\n    }\n    \n}",
["event"] = "Health",
["unit"] = "player",
["subeventSuffix"] = "_CAST_START",
["subeventPrefix"] = "SPELL",
["custom"] = "function (allstates, event, ...)\n    if aura_env.Note == nil then\n        return false\n    end\n    if aura_env.config.disableSharedNote and aura_env.config.disablePersonalNote then\n        return false\n    end\n    if not (aura_env.config.enableWNoteDisabled or aura_env.Note.enabled) then\n        return false\n    end\n    if event == \"MRT_NOTE_NEW\" or event == \"MRT_NOTE_GLOW_DELAY\" then\n        local expirationTime, line, stage, noteType, eventData, encounterStart = ...\n        \n        if type(eventData) ~= \"table\" then\n            return\n        end\n        if not line:lower():match(\"glow\") then\n            return \n        end\n        \n        local delayed = event == \"MRT_NOTE_GLOW_DELAY\"\n        if delayed then\n            -- check if timer is for this encounter and stage\n            if encounterStart ~= aura_env.encounterStart\n            or (stage and stage ~= aura_env.stage)\n            then\n                return\n            end\n        end\n        if (aura_env.config.disableSharedNote and noteType == \"shared\")\n        or (aura_env.config.disablePersonalNote and noteType == \"personal\")\n        or expirationTime == nil\n        then\n            return\n        end\n        \n        -- skip these checks if they were already done\n        if not delayed and aura_env.isFiltered(line, noteType) then\n            return\n        end\n        \n        local duration = expirationTime - GetTime()\n        if duration <= aura_env.config.warn then\n            local unit, unitType = aura_env.getUnit(eventData.target, eventData.flags)\n            if unit then\n                table.insert(\n                    allstates,\n                    {\n                        show = true,\n                        changed = true,\n                        progressType = \"timed\",\n                        autoHide = true,\n                        duration = duration,\n                        expirationTime = expirationTime,\n                        stage = stage,\n                        type = \"timed\",\n                        unit = unit,\n                        unitType = unitType\n                    }\n                )\n                DebugPrint(\"glow\", unit, unitType, line)\n                return true\n            end\n            \n        else\n            local start = duration - aura_env.config.warn\n            local encounterStart = aura_env.encounterStart\n            C_Timer.After(\n                start,\n                function()\n                    WeakAuras.ScanEvents(\"MRT_NOTE_GLOW_DELAY\", expirationTime, line, stage, noteType, eventData, encounterStart)\n                end\n            )\n            DebugPrint(\"Setup delayed timer\", GetTime() - aura_env.encounterStart, start, line)\n        end\n    elseif event == \"MRT_NOTE_STAGE\" and ... then\n        local _, stage = ...\n        aura_env.stage = stage\n        for _, state in pairs(allstates) do\n            if state.stage -- state.stage is nil only for timers started from CLEU events\n            and state.stage ~= stage\n            then\n                state.show = false\n                state.changed = true\n            end\n        end\n        return true\n    elseif event == \"ENCOUNTER_START\" then\n        aura_env.stage = 1\n        aura_env.encounterStart = GetTime()\n        aura_env.keyword[\"group:\" .. aura_env.MyGroup()] = true\n        aura_env.keyword[\"class:\" .. select(2, UnitClass(\"player\"))] = true\n        local spec = GetSpecialization and GetSpecialization()\n        local role, _\n        if spec then\n            _, spec, _, _, role, _ = GetSpecializationInfo(spec)\n            aura_env.keyword[\"role:\" .. role] = true\n            aura_env.keyword[\"spec:\" .. spec] = true\n        end\n        aura_env.makeGuidToUnit()\n    end\nend",
