},
["customName"] = "",
["custom"] = "function(s, e, ...)\n    if e == \"NSAPI_ENCOUNTER_START\" or e == \"ENCOUNTER_START\" then\n        aura_env.time = 0\n    elseif e == \"TRIGGER\" then\n        local _, states = ...\n        local state = states and states[\"\"] -- boss mod state\n        if state and state.duration and state.expirationTime then\n            local newstate = {\n                progressType = \"timed\",\n                duration = state.duration,\n                expirationTime = state.expirationTime,\n                eligible = false,\n                autoHide = true,\n            }\n            if GetTime() >= aura_env.time then -- this makes the player an available target\n                newstate.eligible = true\n            end\n            s:Update(\"\", newstate)\n        end\n    else        \n        local timestamp, subevent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID = ... -- full CLEU\n        if spellID == 1216509 and UnitIsUnit(\"player\", destName) then\n            aura_env.time = GetTime()+90\n        end\n    end\nend\n\n\n\n\n\n\n\n\n",
["events"] = "CLEU:SPELL_AURA_APPLIED NSAPI_ENCOUNTER_START TRIGGER:2 ENCOUNTER_START",
