["Unstable Web Dispel Assigns"] = {
["outline"] = "OUTLINE",
["displayText_format_text_format"] = "none",
["wagoID"] = "foNlg79Ol",
["color"] = {
1,
1,
1,
1,
},
["displayText"] = "",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["automaticWidth"] = "Auto",
["actions"] = {
["start"] = {
["glow_lines"] = 10,
["glow_thickness"] = 4,
["glow_action"] = "show",
["glow_frame_type"] = "UNITFRAME",
["glow_frequency"] = 0.4,
["custom"] = "\n\n",
["glow_border"] = false,
["use_glow_color"] = true,
["glow_color"] = {
0,
1,
1,
1,
},
["glow_type"] = "Pixel",
["do_custom"] = false,
["do_glow"] = false,
},
["init"] = {
["custom"] = "aura_env.debug = false\naura_env.debuff = aura_env.debug and 774 or 446349\naura_env.delay = aura_env.debug and 4 or 0.1\naura_env.filter = aura_env.debug and \"HELPFUL\" or \"HARMFUL\"\n\naura_env.MRT = function()\n    aura_env.list = {}\n    aura_env.found = false\n    if C_AddOns.IsAddOnLoaded(\"MRT\") and VMRT.Note.Text1 then\n        local text = _G.VMRT.Note.Text1\n        local list = false\n        text = text:gsub(\"||r\", \"\") -- clean colorcode\n        text = text:gsub(\"||c%x%x%x%x%x%x%x%x\", \"\") -- clean colorcode\n        aura_env.list = {}\n        for line in text:gmatch('[^\\r\\n]+') do\n            line = strtrim(line) --trim whitespace\n            --check for start/end of the name list\n            if strlower(line) == \"nsdispelstart\" then\n                aura_env.found = true\n                list = true\n            elseif strlower(line) == \"nsdispelend\" then\n                list = false\n            end\n            \n            if list then \n                line = line:gsub(\"{.-}\", \"\") -- cleaning markers from line\n                for name in line:gmatch(\"%S+\") do -- finding all remaining strings\n                    if NSAPI then\n                        --  name = NSAPI:GetChar(name)\n                    end\n                    if UnitInRaid(name) then\n                        name = \"raid\"..UnitInRaid(name)\n                        table.insert(aura_env.list, name)\n                    else -- checking for nickname if string didn't match player\n                        for unit in WA_IterateGroupMembers() do\n                            local uname = UnitName(unit)\n                            if uname:match(name) then\n                                uname = \"raid\"..UnitInRaid(uname)\n                                table.insert(aura_env.list, uname)\n                                break\n                            end\n                        end\n                    end\n                end\n            end\n        end\n    end\n    if not aura_env.found then -- auto assign if no note was provided\n        for unit in WA_IterateGroupMembers() do\n            if UnitGroupRolesAssigned(unit) == \"HEALER\" then\n                table.insert(aura_env.list, unit)\n            end\n        end\n    end  \nend\n\naura_env.blocked = {\n    [102] = true, -- Balance \n    [103] = true, -- Feral\n    [269] = true, -- Windwalker\n    [270] = true, -- Mistweaver\n    [253] = true, -- BM Hunter\n    [254] = true, -- MM Hunter\n    [262] = true, -- Ele Shaman\n    -- not adding Enh shaman here as it's way too cringe to get out of melee for them if they have to spec into that talent\n    [264] = true, -- Resto Shaman\n    [105] = true, -- Resto Druid\n    [256] = true, -- Disc Priest\n    [257] = true, -- Holy Priest\n    [258] = true, -- Shadow Priest\n}\n\n\n",
["do_custom"] = true,
},
["finish"] = {
["hide_all_glows"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["customVariables"] = "{\n    glow = \"bool\",\n    assigned = \"bool\",\n}",
["event"] = "Health",
["unit"] = "player",
["custom_type"] = "stateupdate",
["subeventPrefix"] = "SPELL",
["custom"] = "function(s, e, ...) \n    if e == \"OPTIONS\" then\n        s[\"\"] = {\n            show = true,\n            unit = \"player\",\n            index = 1,\n            progressType = \"static\",\n            changed = true\n            \n        }\n        return true\n        \n    elseif e == \"NSAPI_ENCOUNTER_START\" and ... then\n        aura_env.specs = NSAPI:GetSpecs()\n        aura_env.MRT()\n        aura_env.dwarf = aura_env.dwarf or {}\n    elseif e == \"NS_DWARF_STATUS\" and ... then\n        aura_env.dwarf = ...\n        \n    elseif e == \"NS_ASSIGN_EVENT\" and ... and aura_env.id == ... then\n        table.sort(aura_env.affected, \n            function(a, b)\n                return a[3] < b[3]\n                \n        end) -- a < b low first, a > b high first\n        local tbl = {}\n        local ignore = {}\n        \n        for i, v in ipairs(aura_env.list) do\n            if not (UnitIsDead(v)) then\n                table.insert(tbl, v)\n            end     \n        end\n        \n        if #tbl >= 1 then\n            while #tbl < 4 do\n                for i, v in ipairs(aura_env.list) do\n                    if not (UnitIsDead(v)) then\n                        table.insert(tbl, v)\n                    end     \n                end\n            end\n        end\n        \n        for i, v in ipairs(aura_env.affected) do -- self assign healers\n            if UnitGroupRolesAssigned(v[1]) == \"HEALER\" then   \n                s[v[2]] = {\n                    show = true,\n                    progressType = \"static\",\n                    unit = v[1],\n                    assigned = UnitIsUnit(\"player\", v[1]),\n                    glow = false,\n                    autoHide = true,\n                    changed = true,\n                }\n                ignore[i] = true\n                for num = #tbl, 1, -1 do -- remove healer from their table\n                    if UnitIsUnit(tbl[num], v[1]) then\n                        table.remove(tbl, num)\n                        break\n                    end\n                end\n            end\n        end\n        for i, v in ipairs(tbl) do\n            for num, list in ipairs(aura_env.affected) do\n                if UnitIsUnit(\"player\", list[1]) then                    \n                    WeakAuras.ScanEvents(\"NS_MACRO_PRESS_PERSONAL\", 2) -- display text to remind for macro press\n                end\n                if not ignore[num] then\n                    ignore[num] = true\n                    s[list[2]] = {\n                        show = true,\n                        progressType = \"static\",\n                        unit = list[1],\n                        assigned = UnitIsUnit(\"player\", v),\n                        glow = false,\n                        autoHide = true,\n                        changed = true,\n                    }  \n                    break\n                end\n            end\n        end\n        return true\n    elseif e == \"NS_PA_DISPEL\" and ... then\n        local unit = ...\n        local G = UnitGUID(unit)\n        if s[G] then\n            s[G].glow = true\n            s[G].changed = true\n            return true \n        end\n    elseif e == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local timestamp, subevent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID = ... -- full CLEU\n        \n        \n        if spellID == aura_env.debuff then\n            if subevent == \"SPELL_AURA_APPLIED\" then\n                local now = GetTime()\n                if not aura_env.last or aura_env.last < now - 8 then\n                    aura_env.last = now\n                    aura_env.affected = {}\n                    local aura_env = aura_env\n                    C_Timer.After(aura_env.delay, function()\n                            WeakAuras.ScanEvents(\"NS_ASSIGN_EVENT\", aura_env.id)\n                    end)\n                end\n                local i = UnitInRaid(destName)\n                local unit = i and \"raid\"..i\n                \n                local dwarf = aura_env.dwarf[unit] and (aura_env.dwarf[unit] == 0 or now > aura_env.dwarf[unit])\n                local spec = (aura_env.specs and aura_env.specs[unit]) or (NSAPI and NSAPI:GetSpecs(unit)) or WeakAuras.SpecForUnit(unit)\n                if unit and UnitExists(unit) and (not dwarf)and not aura_env.blocked[spec] then -- aura_env.blocked prevents assigning those that can always break themselves, we're also not assigng anyone who has dwarf ready\n                    table.insert(aura_env.affected, {unit, destGUID, i})\n                end\n            elseif subevent == \"SPELL_AURA_REMOVED\" and s[destGUID] then\n                if UnitIsUnit(\"player\", destName) then\n                    WeakAuras.ScanEvents(\"NS_MACRO_PRESS_PERSONAL\", 3) -- hide macro display\n                end\n                s[destGUID].show = false\n                s[destGUID].changed = true\n                return true\n            end\n        elseif (spellID == 65116 or spellID == 265221) and subevent == \"SPELL_AURA_APPLIED\" then\n            local i = UnitInRaid(destName)\n            local unit = i and \"raid\"..i\n            aura_env.dwarf = aura_env.dwarf or {} -- could technically error otherwise if someone presses dwarf in first few seconds of encounter}\n            if unit and UnitExists(unit) then       \n                aura_env.dwarf[unit] = GetTime()+120  \n            end\n        end\n    elseif (e == \"NS_PA_MACRO\" or e == \"LIQUID_PRIVATE_AURA_MACRO\") and ... then\n        if not aura_env.last3 or aura_env.last3 < GetTime() - 4 then -- macro throttle\n            aura_env.last3 = GetTime()\n            if WA_GetUnitAura(\"player\", aura_env.debuff, aura_env.filter) then\n                NSAPI:Broadcast(\"NS_PA_DISPEL\", \"RAID\", \"nilcheck\") -- skip target if Raid\n                if UnitGroupRolesAssigned(\"player\") ~= \"HEALER\" then\n                    WeakAuras.ScanEvents(\"NS_MACRO_PRESS_PERSONAL\", 1) -- display text indicating that macro has been pressed\n                end\n            end\n        end        \n    end  \nend     \n\n\n\n\n",
