["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["debuffType"] = "HELPFUL",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["names"] = {
},
["spellIds"] = {
},
["custom"] = "function(states, event, ...)\n    if event == \"TRIGGER\" and ... then\n        local watchedNumber, watchedStates = ...\n        \n        --Let the WeakAuras framework do the heavy lifting to build our data tables\n        if watchedNumber == 2 then\n            aura_env.healthStates = watchedStates\n        elseif watchedNumber == 3 then\n            aura_env.debuffStates = watchedStates\n        end\n        if not aura_env.healthStates or not aura_env.debuffStates then return end\n        \n        for debuffClone, debuffState in pairs(aura_env.debuffStates) do\n            if debuffState.active == true \n            and debuffState.unitCaster == \"player\"\n            and aura_env.healthStates[debuffClone] \n            and aura_env.healthStates[debuffClone].percenthealth >= 80 \n            then\n                local state = states[\"\"]\n                if not state then\n                    states[\"\"] = {\n                        show = false,\n                        changed = true\n                    }\n                elseif state.show == true then\n                    state.show = false\n                    state.changed = true\n                end\n                return true\n            end\n        end\n        \n        local highestHealth = 0\n        local highestHealthUnit = \"\"\n        local highestGUID = \"\"\n        for healthClone, healthState in pairs(aura_env.healthStates) do\n            if not aura_env.blacklist[healthState.npcId]\n            and aura_env.debuffStates[healthClone] \n            and aura_env.debuffStates[healthClone].active == false \n            then\n                if healthState.percenthealth > 80 then\n                    if healthState.health > highestHealth\n                    or healthState.health == highestHealth and UnitGUID(healthState.unit) > highestGUID then\n                        highestHealth = healthState.health\n                        highestHealthUnit = healthState.unit\n                        highestGUID = UnitGUID(healthState.unit)\n                    end\n                end\n            end\n        end\n        local state = states[\"\"]\n        if not state then\n            states[\"\"] = {\n                show = true,\n                changed = true,\n                unit = highestHealthUnit,\n                GUID = highestGUID,\n            }\n        elseif state.unit ~= highestHealthUnit then\n            state.unit = highestHealthUnit\n            state.GUID = highestGUID\n            state.changed = true\n        end\n        return true\n    end\nend",
["events"] = "TRIGGER:2:3",
["check"] = "event",
["unit"] = "player",
["customVariables"] = "\n\n",
["custom_hide"] = "timed",
},
