["custom"] = "function(s, e, num, dur, unit, count)\n    if e == \"OPTIONS\" then        \n        local num = math.random(1, 4)\n        local count = math.random(1, 9)\n        local unit = \"player\"\n        local dur = 20\n        local mark = aura_env.num[num][count]\n        local state = {\n            show = true,\n            progressType = \"timed\",\n            mark = \"{rt\"..mark..\"}\",\n            duration = dur,\n            expirationTime = dur+GetTime(),\n            autoHide = true,\n        }\n        \n        s:Update(unit, state)\n    else\n        if num and count then\n            local mark = aura_env.num[num][count]\n            local state = {\n                show = true,\n                progressType = \"timed\",\n                mark = \"{rt\"..mark..\"}\",\n                duration = dur,\n                expirationTime = dur+GetTime(),\n                autoHide = true,\n            }\n            \n            s:Update(unit, state)\n        end\n    end\nend\n\n\n\n\n\n",
