["subeventSuffix"] = "_CAST_SUCCESS",
["custom"] = "function(allstates, event, ...)\n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID, _,_, auraType = ...\n        if subEvent == \"SPELL_CAST_SUCCESS\" and spellID == 274991 then\n            aura_env.timestamp = GetTime()\n            local targetIsMe = UnitIsUnit(\"boss1target\", \"player\")\n            allstates[WeakAuras.myGUID] = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                duration = 2.5,\n                expirationTime = 2.5 + GetTime(),\n                targetIsMe = targetIsMe,\n                autoHide = true,\n            }\n            return true\n        elseif subEvent == \"SPELL_AURA_APPLIED\" and spellID == 275014 and destGUID == WeakAuras.myGUID then\n            local state = allstates[destGUID]\n            if state then\n                state.show = false\n                state.changed = true\n                return true\n            end\n        end\n    elseif event == \"UNIT_TARGET\" and aura_env.timestamp and ((GetTime() - aura_env.timestamp) == 0) then\n        local unit = ...\n        --sadly it's only possible to warn one of the two targeted players\n        if UnitIsUnit(unit..\"target\", \"player\") then\n            local state = allstates[WeakAuras.myGUID]\n            if state then\n                state.targetIsMe = true\n                state.changed = true\n                return true\n            end\n        end\n    elseif event == \"ENCOUNTER_START\" then\n        aura_env.timestamp = nil\n    end\nend",
