},
["check"] = "event",
["custom"] = "function(allstates, event, ...)\n    if not aura_env.OpenRaid then\n        return false \n    end\n    \n    if event == \"CHALLENGE_MODE_COMPLETED\" then\n        -- check if player can reroll\n        local _, completedLevel, _, completedOnTime, _, _, _, _, _, _, _, _, _ = C_ChallengeMode.GetCompletionInfo();\n        if not completedOnTime then\n            -- cannot reroll if the key was not timed\n            return false\n        end\n        \n        local playerKeystone = aura_env.OpenRaid.GetKeystoneInfo(\"player\")\n        if playerKeystone.level <= 0 or playerKeystone.level > completedLevel then\n            -- cannot reroll if player's current key is higher level\n            return false\n        end\n        \n        allstates[1] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = aura_env.config.duration,\n            autoHide = true,\n        }\n        \n        return true\n    elseif event == \"OPTIONS\" then\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = aura_env.config.duration,\n            autoHide = true,\n        }\n        \n        return true\n    end\n    \n    return false\nend",
