["subeventSuffix"] = "_CAST_START",
["events"] = "CLEU:SPELL_AURA_REMOVED_DOSE, CLEU:SPELL_AURA_APPLIED, CLEU:SPELL_AURA_APPLIED_DOSE, CLEU:SPELL_CAST_SUCCESS,CLEU:SPELL_AURA_REFRESH, CLEU:SPELL_DAMAGE, CLEU:SPELL_AURA_REMOVED\n",
["customName"] = "",
["custom_hide"] = "custom",
["realSpellName"] = 0,
["type"] = "custom",
["use_absorbHealMode"] = true,
["custom_type"] = "event",
