["use_absorbMode"] = true,
["event"] = "Cooldown Progress (Spell)",
["customStacks"] = "function()\n    if (ShowNeeded) then\n        return aura_env.reverser[aura_env.TStacks]\n    else\n        return aura_env.TStacks\n    end\nend",
["customDuration"] = "\n\n",
["use_spellName"] = true,
["custom"] = "function(event, timestamp, subevent, arg3, sourceGUID, arg5, arg6, arg7, arg8, arg9, arg10, arg11, spellId, arg13, arg14, arg15, amount)\n    if not aura_env.TStacks then\n        aura_env.TStacks = 0\n    end\n    if not aura_env.currentStacks then\n        aura_env.currentStacks = 0\n    end\n    if not aura_env.tempestTime then\n        aura_env.tempestTime = 0\n    end\n    if not aura_env.mswFadeTime then\n        aura_env.mswFadeTime = 0\n    end\n    if not aura_env.mswRemovedDoseTime then\n        aura_env.mswRemovedDoseTime = 0\n    end\n    if not aura_env.tempestFlag then\n        aura_env.tempestFlag = false\n    end\n    if not aura_env.lastCastTime then\n        aura_env.lastCastTime = 0\n    end\n    \n    -- Handle Tempest buff application and refresh\n    if (sourceGUID == aura_env.playerGUID) then\n        if ((subevent == \"SPELL_AURA_APPLIED\" or subevent == \"SPELL_AURA_REFRESH\") and spellId == 454015) then\n            local currentTime = GetTime()\n            aura_env.tempestTime = currentTime\n            aura_env.tempestFlag = true\n        end\n    end\n    \n    -- Handle MSW aura applied and dose events\n    if (sourceGUID == aura_env.playerGUID) then\n        -- Track successful spell casts\n        if (subevent == \"SPELL_CAST_SUCCESS\") then\n            aura_env.lastCastTime = GetTime()\n        end\n        \n        -- Track Maelstrom Weapon dose removals\n        if (subevent == \"SPELL_AURA_REMOVED_DOSE\" and spellId == 344179) then\n            if (GetTime() - aura_env.lastCastTime) <= 0.1 then\n                local consumed = math.min(5, aura_env.currentStacks)\n                aura_env.TStacks = aura_env.TStacks + consumed\n                aura_env.currentStacks = amount\n                aura_env.mswRemovedDoseTime = GetTime()\n                \n                -- Check if Tempest buff was recently applied or refreshed\n                if aura_env.tempestFlag then\n                    aura_env.tempestFlag = false\n                    local timeDiff = aura_env.tempestTime - aura_env.mswRemovedDoseTime\n                    local timeDiffFade = aura_env.tempestTime - aura_env.mswFadeTime\n                    if (math.abs(timeDiff) < 0.1) then\n                        if aura_env.TStacks > 40 then\n                            aura_env.TStacks = aura_env.TStacks - 40\n                        else \n                            aura_env.TStacks = 0\n                        end\n                    end\n                end\n            end\n        end\n        \n        -- Track Maelstrom Weapon fade when all stacks are consumed\n        if (subevent == \"SPELL_AURA_REMOVED\" and spellId == 344179) then\n            if (GetTime() - aura_env.lastCastTime) <= 0.1 then\n                local consumed = aura_env.currentStacks\n                aura_env.TStacks = aura_env.TStacks + consumed\n                aura_env.currentStacks = 0\n                aura_env.mswFadeTime = GetTime()\n                \n                -- Check if Tempest buff was recently applied or refreshed\n                if aura_env.tempestFlag then\n                    aura_env.tempestFlag = false\n                    local timeDiff = aura_env.tempestTime - aura_env.mswRemovedDoseTime\n                    local timeDiffFade = aura_env.tempestTime - aura_env.mswFadeTime\n                    if (math.abs(timeDiffFade) < 0.1) then\n                        if aura_env.TStacks > 40 then\n                            aura_env.TStacks = aura_env.TStacks - 40\n                        else \n                            aura_env.TStacks = 0    \n                        end\n                    end\n                end\n            end\n        end\n        \n        -- Track Maelstrom Weapon applications and doses\n        if (subevent == \"SPELL_AURA_APPLIED\" and spellId == 344179) then\n            aura_env.currentStacks = 1\n        elseif (subevent == \"SPELL_AURA_APPLIED_DOSE\" and spellId == 344179) then\n            aura_env.currentStacks = amount\n        end\n        \n        -- Fail-safe to reset stacks if they exceed 49\n        if aura_env.TStacks > 49 then\n            aura_env.TStacks = 0\n        end\n    end\n    return true\nend",
