["spellIds"] = {
},
["unit"] = "group",
["custom"] = "function(allstates, event, ...)\n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID, _,_, auraType = ...\n        if (subEvent == \"SPELL_AURA_APPLIED\" or subEvent == \"SPELL_AURA_REFRESH\") and spellID == 424889 then\n            local unit = UnitTokenFromGUID(destGUID)\n            if unit then\n                local duration = select(5, WA_GetUnitDebuff(unit, spellID))\n                local smashTimer = aura_env.counter % 2 == 0 and 28 or 20\n                if duration and (duration > smashTimer - 1) then -- i hate DKs\n                    allstates[destGUID] = {\n                        show = true,\n                        changed = true,\n                        progressType = \"timed\",\n                        duration = smashTimer,\n                        expirationTime = smashTimer + GetTime(),\n                        unit = unit,\n                        autoHide = true,\n                        \n                    }\n                    return true\n                end\n            end\n            \n        elseif subEvent == \"SPELL_CAST_START\" and spellID == 424888 then\n            aura_env.counter = aura_env.counter + 1\n            \n        elseif subEvent == \"SPELL_AURA_REMOVED\" and spellID == 424889 then\n            local state = allstates[destGUID]\n            if state then\n                state.show = false\n                state.changed = true\n                return true\n            end\n        end\n        \n    elseif event == \"ENCOUNTER_START\" then\n        aura_env.counter = 0\n    end\nend",
