},
["custom"] = "function(s, e, ...)    \n    if e == \"OPTIONS\" then\n        local texts = {\"LEFT\", \"RIGHT\", \"MIDDLE\", \"FAR LEFT\", \"MIDDLE LEFT\", \"MIDDLE RIGHT\", \"FAR RIGHT\"}\n        local i = math.random(1, 7)\n        local text = texts[i]\n        local state = {\n            progressType = \"timed\",\n            text = text,\n            duration = 8-GetTime(),\n            expirationTime = 8,\n            autoHide = true,\n        }\n        s:Update(\"\", state)\n        return true    \n    elseif e == \"NS_GAOL_TARGET\" or e == \"NS_GAOL_SOAK\" then\n        local _, _, text, expires = ...\n        local state = {\n            progressType = \"timed\",\n            text = text,\n            duration = expires-GetTime(),\n            expirationTime = expires,\n            autoHide = true,\n        }\n        s:Update(\"\", state)\n        if aura_env.config.tts then\n            NSAPI:TTS(text)\n        end\n        if e == \"NS_GAOL_TARGET\" then\n            SendChatMessage(text, \"SAY\")\n            C_Timer.After(3, function()\n                    SendChatMessage(text, \"SAY\")        \n            end)     \n        end   \n    end\nend\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n",
