["events"] = "UNIT_SPELLCAST_SUCCEEDED:boss1 RELOE_ETERNAL_NIGHT ENCOUNTER_START",
["custom"] = "function(s, e, ...)\n    if e == \"ENCOUNTER_START\" then\n        aura_env.count = 0\n    elseif e == \"RELOE_ETERNAL_NIGHT\" and ... then\n        local count, amount, dur = ...\n        count = count+1\n        s[\"\"] =\n        {\n            show = true,\n            changed = true,\n            duration = dur, \n            progressType = \"timed\",\n            text = count..\"/\"..amount,\n            expirationTime = GetTime()+dur,\n            autoHide = true\n        }\n        \n        if count < amount then\n            C_Timer.After(dur, function()\n                    WeakAuras.ScanEvents(\"RELOE_ETERNAL_NIGHT\", count, amount, dur)\n            end)\n        end\n        return true\n    else\n        local u, cast, spellID = ... -- Unit event\n        if spellID == 435405 then\n            aura_env.count = aura_env.count and aura_env.count+1 or 1\n            local dur = 3\n            local amount = 8\n            s[\"\"] =\n            {\n                show = true,\n                changed = true,\n                text = \"1/\"..amount,\n                duration = 3, \n                progressType = \"timed\",\n                expirationTime = GetTime()+3,\n                autoHide = true\n            }\n            C_Timer.After(3, function()\n                    WeakAuras.ScanEvents(\"RELOE_ETERNAL_NIGHT\", 1, amount, dur)\n            end)\n            return true\n        end\n    end\nend\n\n\n",
