["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["unit"] = "player",
["names"] = {
},
["spellIds"] = {
},
["custom"] = "function (allstates, event, ...)\n    if aura_env.Note == nil then\n        return false\n    end\n    if aura_env.config.disableSharedNote and aura_env.config.disablePersonalNote then\n        return false\n    end\n    if not (aura_env.config.enableWNoteDisabled or aura_env.Note.enabled) then\n        return false\n    end\n    if event == \"MRT_NOTE_NEW\" or event == \"MRT_NOTE_ICON_DELAY\" then\n        local expirationTime, line, stage, noteType, encounterStart = ...\n        \n        local delayed = event == \"MRT_NOTE_ICON_DELAY\"\n        if delayed then\n            -- check if timer is for this encounter and stage\n            if encounterStart ~= aura_env.encounterStart\n            or (stage and stage ~= aura_env.stage)\n            then\n                return\n            end\n        end\n        if (aura_env.config.disableSharedNote and noteType == \"shared\")\n        or (aura_env.config.disablePersonalNote and noteType == \"personal\")\n        or expirationTime == nil\n        then\n            return\n        end\n        \n        local lineLower = line:lower()\n        \n        -- check line full\n        --if not delayed and aura_env.isFiltered(line, noteType) then\n        --    return\n        --end\n        \n        local duration = expirationTime - GetTime()\n        if duration <= aura_env.config.warn then\n            local changed = false\n            \n            for str in string.gmatch(lineLower .. \"  \", \"[^ \\n-][^\\n-]-  +\") do\n                if not aura_env.isFiltered(str, noteType) then\n                    for spellId in str:gmatch(\"{spell:(%d+)\") do\n                        local spellName, _, icon = GetSpellInfo(spellId)\n                        if icon then\n                            table.insert(\n                                allstates,\n                                {\n                                    show = true,\n                                    changed = true,\n                                    progressType = \"timed\",\n                                    autoHide = true,\n                                    duration = duration,\n                                    expirationTime = expirationTime,\n                                    name = spellName,\n                                    icon = icon,\n                                    stage = stage,\n                                    type = \"timed\"\n                                }\n                            )\n                            \n                            changed = true\n                            --DebugPrint(\"Show new timer\", GetTime() - aura_env.encounterStart, line, event, encounterStart, aura_env.encounterStart)\n                        end\n                    end\n                end\n            end\n            \n            return changed\n        else\n            local start = duration - aura_env.config.warn\n            local encounterStart = aura_env.encounterStart\n            C_Timer.After(\n                start,\n                function()\n                    WeakAuras.ScanEvents(\"MRT_NOTE_ICON_DELAY\", expirationTime, line, stage, noteType, encounterStart)\n                end\n            )\n            --DebugPrint(\"Setup delayed timer\", GetTime() - encounterStart or 0, start, line)\n        end\n    elseif event == \"MRT_NOTE_STAGE\" and ... then\n        local _, stage = ...\n        aura_env.stage = stage\n        for _, state in pairs(allstates) do\n            if state.stage -- state.stage is nil only for timers started from CLEU events\n            and state.stage ~= stage\n            then\n                state.show = false\n                state.changed = true\n            end\n        end\n        return true\n    elseif event == \"ENCOUNTER_START\" then\n        aura_env.stage = 1\n        aura_env.encounterStart = GetTime()\n        aura_env.keyword[\"group:\" .. aura_env.MyGroup()] = true\n        aura_env.keyword[\"class:\" .. select(2, UnitClass(\"player\"))] = true\n        local spec = GetSpecialization and GetSpecialization()\n        local role, _\n        if spec then\n            _, spec, _, _, role, _ = GetSpecializationInfo(spec)\n            aura_env.keyword[\"role:\" .. role] = true\n            aura_env.keyword[\"spec:\" .. spec] = true\n        end\n    end\nend",
