{
["trigger"] = {
["type"] = "custom",
["custom"] = "function(event,button)\n    \n    if aura_env.config.HideOnRightClick then\n        if event == \"GLOBAL_MOUSE_UP\" then\n            if button == \"RightButton\" then\n                return true\n            end\n        end\n        \n     elseif aura_env.config.KeyOption > 1 then\n        \n        if aura_env.config.KeyOption == 2 and IsLeftAltKeyDown() then\n            return true \n        elseif aura_env.config.KeyOption == 4 and IsLeftControlKeyDown() then\n            return true\n        elseif aura_env.config.KeyOption == 3 and IsLeftShiftKeyDown() then\n            return true\n        end\n        \n    else\n        return true\n    end \n    \nend\n\n\n\n",
["custom_type"] = "event",
["debuffType"] = "HELPFUL",
["events"] = "GLOBAL_MOUSE_DOWN,GLOBAL_MOUSE_UP, MODIFIER_STATE_CHANGED,PLAYER_LOGIN,PLAYER_ENTERING_WORLD",
["unit"] = "player",
["custom_hide"] = "custom",
},
["untrigger"] = {
["custom"] = "function(event,button)\n    \n    if aura_env.config.HideOnRightClick then\n        if event == \"GLOBAL_MOUSE_DOWN\" then\n            if button == \"RightButton\" then\n                return true\n            end\n        end\n        \n    elseif aura_env.config.KeyOption > 1 then\n        \n        if aura_env.config.KeyOption == 2 and not IsLeftAltKeyDown() then\n            return true \n        elseif aura_env.config.KeyOption == 4 and not IsLeftControlKeyDown() then\n            return true\n        elseif aura_env.config.KeyOption == 3 and not IsLeftShiftKeyDown() then\n            return true\n        end\n        \n    else\n        return true\n    end \n    \nend\n\n\n\n",
},
