["NS Version Check Nerub-ar Palace"] = {
["outline"] = "OUTLINE",
["displayText_format_text_format"] = "none",
["displayText_format_url_format"] = "none",
["wagoID"] = "foNlg79Ol",
["xOffset"] = -7.999755859375,
["displayText_format_p_time_dynamic_threshold"] = 60,
["yOffset"] = 358.00018310547,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://wago.io/NSNerubarPalace/54",
["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "aura_env.minversion = 7 -- NS Function Aura - Manual Version Number\naura_env.version = 12 -- Manual Version Number to mark important updates\naura_env.texts = {\n    \"Required WA out of date/missing:\",\n    \"Someone in your Raid has a newer version of this WA installed:\",    \n}",
["do_custom"] = true,
},
["finish"] = {
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["custom_hide"] = "timed",
["duration"] = "10",
["event"] = "Health",
["unit"] = "player",
["subeventSuffix"] = "_CAST_START",
["subeventPrefix"] = "SPELL",
["custom"] = "function(s, e, ...)\n    if e == \"OPTIONS\" then\n        s[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            text = \"Text that tells you something is out of date\",\n            url = \"url here\",\n            duration = 5,\n            expirationTime = 5+GetTime(),\n            autoHide = true,\n        }\n        return true\n    elseif e == \"READY_CHECK\" and ... then\n        if not NSAPI or not NSAPI.Version or NSAPI:Version() < aura_env.minversion then\n            s[\"\"] = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                text = aura_env.texts[1],\n                url = \"https://wago.io/NorthernSky\",\n                duration = 8,\n                expirationTime = 8+GetTime(),\n                autoHide = true,\n            }\n            return true\n        end\n        local waData = WeakAuras.GetData(aura_env.region:GetParent().id)      \n        local version = waData.url:match(\"%d+$\")\n        version = version and tonumber(version) or 0\n        if version ~= 0 then -- prevent doing anything if no version info is found (which should only be possible if its the author or someone manually edited it?\n            local url = waData.url:match(\".*%D\")\n            NSAPI:Broadcast(\"VERSION_NUM\", \"RAID\", version, aura_env.version, url)\n        end\n    elseif e == \"VERSION_NUM\" and ... then\n        local unit, vers, vers2, url = ...\n        url = url or \"\"\n        url = \"https:\"..url\n        local waData = WeakAuras.GetData(aura_env.region:GetParent().id)  \n        local version = waData.url:match(\"%d+$\")\n        version = version and tonumber(version) or 0\n        if version ~= 0 then\n            local link = waData.url:match(\".*%D\")\n            if link == url then -- only check if both users are using the same url, otherwise it makes no sense to compare versions. Also future proofs someone blindly copy pasting this WA into a different group\n                if aura_env.version < vers2  then -- manual set version in on init is lower, indicating missing an important update\n                    s[\"\"] = {\n                        show = true,\n                        changed = true,\n                        progressType = \"timed\",\n                        text = aura_env.texts[2],\n                        url = url,\n                        duration = 8,\n                        expirationTime = 8+GetTime(),\n                        autoHide = true,\n                    }\n                elseif version < vers and aura_env.config.check then -- internal url version is lower, only display if the user wants this\n                    s[\"\"] = {\n                        show = true,\n                        changed = true,\n                        progressType = \"timed\",\n                        text = aura_env.texts[2],\n                        url = url,\n                        duration = 8,\n                        expirationTime = 8+GetTime(),\n                        autoHide = true,\n                    }\n                end\n                return true\n            end\n        end\n    end\nend\n\n\n",
["events"] = "READY_CHECK VERSION_NUM OPTIONS",
