["customTriggerLogic"] = "function(t)\n    if t[4] then -- If in Rested Area\n        return false\n    end\n    \n    local behavior = aura_env.config.maintenance.hunters_mark.behavior\n    \n    if behavior == 1 then -- Show if Applied\n        return t[1] or t[2]\n    elseif behavior == 2 then -- Show if Missing\n        return  t[1] or t[3]\n    else -- Always Show\n        return t[1] or t[2] or t[3]\n    end\nend",
