["custom_type"] = "stateupdate",
["check"] = "event",
["debuffType"] = "HELPFUL",
["custom"] = "function(s, e, ...)    \n    if e == \"UNIT_SPELLCAST_START\" then\n        local u, cast, spellID = ... -- Unit event\n        if spellID == 1217231 then\n            s[\"\"] = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                duration = 19.3,\n                expirationTime =19.3+GetTime(),\n                count = 4, -- check for other difficulties / show positive & negatives in Mythic\n                autoHide = true,\n            }\n            return true\n        end\n        \n    elseif e == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local timestamp, subevent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID = ... -- full CLEU\n        if spellID == 1218342 and s[\"\"] then\n            aura_env.last = GetTime()\n            s[\"\"].count = s[\"\"].count-1\n            if s[\"\"].count <= 0 then s[\"\"].show = false end\n            s[\"\"].changed = true\n            return true\n        end\n    end\n    \nend\n\n\n",
["unit"] = "player",
},
