["Acolyte's Essence Assign Handler"] = {
["outline"] = "OUTLINE",
["wagoID"] = "foNlg79Ol",
["color"] = {
1,
1,
1,
1,
},
["preferToUpdate"] = true,
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["automaticWidth"] = "Auto",
["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "aura_env.debug = false\naura_env.filter = aura_env.debug and \"HELPFUL\" or \"HARMFUL\"\naura_env.debuff = aura_env.debug and 774 or 446012\naura_env.cast = aura_env.debug and 8936 or 445422\naura_env.delay = aura_env.debug and 4 or 0.2\n\naura_env.MRT = function()\n    aura_env.list = {}\n    aura_env.found = false\n    aura_env.me = 0\n    aura_env.count = 0\n    if C_AddOns.IsAddOnLoaded(\"MRT\") and VMRT.Note.Text1 then\n        local text = _G.VMRT.Note.Text1\n        local list = false\n        text = text:gsub(\"||r\", \"\") -- clean colorcode\n        text = text:gsub(\"||c%x%x%x%x%x%x%x%x\", \"\") -- clean colorcode\n        for line in text:gmatch('[^\\r\\n]+') do\n            line = strtrim(line) --trim whitespace\n            --check for start/end of the name list\n            if strlower(line) == \"nsessencestart\" then\n                list = true\n            elseif strlower(line) == \"nsessenceend\" then\n                list = false\n                aura_env.found = true\n            end\n            \n            if list then \n                aura_env.list[aura_env.count] = {}\n                line = line:gsub(\"{.-}\", \"\") -- cleaning markers from line\n                for name in line:gmatch(\"%S+\") do -- finding all remaining strings\n                    if NSAPI then\n                        name = NSAPI:GetChar(name)\n                    end\n                    if UnitInRaid(name) then\n                        if UnitIsUnit(\"player\", name) then\n                            aura_env.me = aura_env.count\n                        end\n                        table.insert(aura_env.list[aura_env.count], name)\n                    else -- checking for nickname if string didn't match player\n                        for unit in WA_IterateGroupMembers() do\n                            local uname = UnitName(unit)\n                            if uname:match(name) then\n                                table.insert(aura_env.list[aura_env.count], uname)  \n                                break\n                            end\n                        end\n                    end\n                end\n            end\n            aura_env.count = aura_env.count+1\n        end\n    end\nend",
["do_custom"] = true,
},
["finish"] = {
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["custom_hide"] = "timed",
["event"] = "Health",
["unit"] = "player",
["custom_type"] = "status",
["subeventPrefix"] = "SPELL",
["custom"] = "function(e, ...)\n    if e == \"NSAPI_ENCOUNTER_START\" and ... then\n        aura_env.casts = 0\n        aura_env.specs = NSAPI:GetSpecs()\n        aura_env.enabled = true\n        aura_env.MRT()\n    elseif e == \"UNIT_SPELLCAST_SUCCEEDED\" then\n        \n        local u, cast, spellID = ... -- Unit event\n        if spellID == aura_env.cast then\n            aura_env.enabled = false            \n        elseif spellID == 444829 then\n            aura_env.casts = aura_env.casts and aura_env.casts+1 or 1\n            aura_env.enabled = true\n        end\n    elseif e == \"NS_ASSIGN_EVENT\" and ... and aura_env.id == ... then\n        local diff = select(3, GetInstanceInfo()) or 0\n        local amount = (aura_env.casts == 1 and 3) or (aura_env.casts == 2 and 7) or (aura_env.casts == 3 and 12) or 12 \n        local assigned = 0\n        for i, v in ipairs(aura_env.list[aura_env.casts]) do\n            if UnitExists(v) and not (UnitIsDead(v)) and not (WA_GetUnitBuff(v, 27827)) then\n                assigned = assigned+1\n                if UnitIsUnit(\"player\", v) then\n                    WeakAuras.ScanEvents(\"NS_ESSENCE_YOU\", assigned)     \n                end\n                if assigned >= amount then\n                    return true\n                end\n            end\n        end\n        -- if it goes through to here then not enough players were found\n        WeakAuras.ScanEvents(\"NS_ESSENCE_ALERT\", amount-assigned)\n    elseif aura_env.found and aura_env.enabled then\n        local timestamp, subevent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID = ... -- full CLEU\n        local npcid = select(6, strsplit(\"-\", destGUID))\n        if npcid and npcid == \"221863\" then\n            aura_env.enabled = false\n            WeakAuras.ScanEvents(\"NS_ASSIGN_EVENT\", aura_env.id)\n        end\n    end\nend\n\n\n\n\n\n\n\n\n",
