["custom"] = "aura_env.allowList = {\n    [201226] = true, --Blood Bolt (DHT)\n    [193633] = true, --Shoot (BRH)\n    [373392] = true, --Shoot (Nokhud)\n    [369781] = true, --Dagger Throw (Uldaman)\n    [387974] = true, --Arcane Missiles (Algethar)\n    [373932] = true, --Illusionary Bolt (Azure Vault)\n}\n\naura_env.blockList = {\n    \n}\n\n\naura_env.getCastInfo = function(unit)\n    local startC, endC, icon, notInterruptible, spellID, duration, expirationTime, _\n    if UnitCastingInfo(unit) then\n        _, _, icon, startC, endC, _, _, notInterruptible, spellID = UnitCastingInfo(unit)\n    elseif UnitChannelInfo(unit) then\n        _, _, icon, startC, endC, _, notInterruptible, spellID = UnitChannelInfo(unit)\n    end\n    if startC and endC then\n        duration = (endC - startC) / 1000\n        expirationTime = endC / 1000\n    end\n    return duration, expirationTime, icon, notInterruptible, spellID\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["spellIds"] = {
},
["events"] = "UNIT_SPELLCAST_START:nameplate:boss:target, UNIT_SPELLCAST_STOP:nameplate:boss:target, UNIT_SPELLCAST_CHANNEL_START:nameplate:boss:target,UNIT_SPELLCAST_CHANNEL_STOP:nameplate:boss:target,NAME_PLATE_UNIT_ADDED, NAME_PLATE_UNIT_REMOVED, UNIT_TARGET:nameplate:boss:target, CAUSESE_CAST_MATCH, DELAYED_UNIT_SPELLCAST_START, DELAYED_UNIT_SPELLCAST_CHANNEL_START",
["custom"] = "function(allstates, event, ...)\n    if (\n        event == \"DELAYED_UNIT_SPELLCAST_START\"\n        or event == \"DELAYED_UNIT_SPELLCAST_CHANNEL_START\"\n        or event == \"UNIT_TARGET\"\n        or event == \"NAME_PLATE_UNIT_ADDED\"\n    ) then\n        local unit = ...\n        if UnitExists(unit) then\n            local guid = UnitGUID(unit)\n            local duration, expirationTime, icon, notInterruptible, spellID = aura_env.getCastInfo(unit)\n            if spellID\n            and not aura_env.blockList[spellID]\n            and not UnitInParty(unit)\n            and UnitIsUnit(unit..\"target\", \"player\")\n            and (aura_env.config.interruptible and not notInterruptible or not aura_env.config.interruptible) then\n                if aura_env.allowList[spellID] then\n                    WeakAuras.ScanEvents(\"CAUSESE_CAST_MATCH\", unit, guid, icon, spellID, duration, expirationTime, _)\n                else\n                    local aura_env = aura_env\n                    local spell = Spell:CreateFromSpellID(spellID)\n                    if spell and not spell:IsSpellEmpty() then\n                        spell:ContinueOnSpellLoad(function()\n                                local desc\n                                if GetSpellDescription then\n                                    desc = GetSpellDescription(spell.spellID):lower()\n                                else\n                                    desc = C_Spell.GetSpellDescription(spell.spellID):lower()\n                                end\n                                local damage = desc:match(aura_env.config.pattern1) or desc:match(aura_env.config.pattern2) or desc:match(aura_env.config.pattern3)\n                                if damage then\n                                    local amountDamage = damage:gsub(\",\", \"\")\n                                    WeakAuras.ScanEvents(\"CAUSESE_CAST_MATCH\", unit, guid, icon, spellID, duration, expirationTime, amountDamage)\n                                end\n                            end\n                        )\n                    end\n                end\n            end\n        end\n        \n    elseif event == \"UNIT_SPELLCAST_START\" then\n        local unit = ...\n        C_Timer.After(aura_env.config.delay, function() WeakAuras.ScanEvents(\"DELAYED_UNIT_SPELLCAST_START\", unit) end)\n        \n    elseif event == \"UNIT_SPELLCAST_CHANNEL_START\" and aura_env.config.allowChannel then\n        local unit = ...\n        C_Timer.After(aura_env.config.delay, function() WeakAuras.ScanEvents(\"DELAYED_UNIT_SPELLCAST_CHANNEL_START\", unit) end)\n        \n    elseif event == \"CAUSESE_CAST_MATCH\" and ... then\n        local unit, guid, icon, spellID, duration, expirationTime, amountDamage = ...\n        allstates[guid] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = duration,\n            expirationTime = expirationTime,\n            damage = amountDamage and tonumber(amountDamage),\n            spellID = spellID,\n            icon = icon,\n            autoHide = true,\n        }\n        return true\n        \n    elseif (event == \"NAME_PLATE_UNIT_REMOVED\" or event == \"UNIT_SPELLCAST_STOP\" or event == \"UNIT_SPELLCAST_CHANNEL_STOP\") then\n        local unit = ...\n        local state = allstates[UnitGUID(unit)]\n        if state then\n            state.show = false\n            state.changed = true\n            return true\n        end\n    end\nend",
