["custom"] = "function(allstates, event, ...)\n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID, _,_, auraType = ...\n        if subEvent == \"SPELL_AURA_APPLIED\" and spellID == 450095 then\n            local unit = UnitTokenFromGUID(destGUID)\n            if unit and WA_GetUnitDebuff(unit, 82850) then\n                allstates[destGUID] = {\n                    show = true,\n                    changed = true,\n                    unit = unit,\n                }\n                return true\n            end\n        elseif subEvent == \"SPELL_AURA_REMOVED\" and spellID == 450095 then\n            local state = allstates[destGUID]\n            if state then\n                state.show = false\n                state.changed = true\n                return true\n            end\n        end\n    end\nend",
