["name"] = "Overwrite Cooldown Number",
["multiline"] = false,
["key"] = "offsetnum",
["length"] = 10,
["desc"] = "Specify the cooldown for the specified npcID. If you're using multiple npcID's, seperate the individual cooldown by a space",
["useLength"] = false,
},
