["init"] = {
["custom"] = "--if you have a better list and are a high key pusher + healer then feel free to contact me (causese on twitch)\n\n--lower number = higher dispel prio\n\naura_env.specPrio = {\n    [257] =  1,  -- Holy Priest\n    [65] =   1,  -- Holy Paladin\n    [256] =  1,  -- Discipline Priest\n    [105] =  1,  -- Restoration Druid\n    [264] =  1,  -- Restoration Shaman\n    [1468] = 1,  -- Preservation\n    [270] =  1,  -- Mistweaver\n    [102] =  2,  -- Balance\n    [103] =  3,  -- Feral\n    [263] =  4,  -- Enhancement\n    [262] =  5,  -- Elemental\n    [258] =  6,  -- Shadow \n    [1467] = 7,  -- Devastation\n    [1473] = 8,  -- Augmentation\n    [254] =  9,  -- Marksmanship\n    [253] =  10, -- Beast Mastery\n    [255] =  11, -- Survival\n    [577] =  12, -- Havoc\n    [269] =  13, -- Windwalker\n    [70] =   14, -- Retribution Paladin\n    [266] =  15, -- Demonology\n    [64] =   16, -- Frost\n    [63] =   17, -- Fire\n    [62] =   18, -- Arcane\n    [267] =  19, -- Destruction\n    [265] =  20, -- Affliction\n    [259] =  21, -- Assassination\n    [261] =  22, -- Subtlety\n    [260] =  23, -- Outlaw\n    [71] =   24, -- Arms\n    [72] =   25, -- Fury\n    [252] =  26, -- Unholy\n    [251] =  27, -- Frost\n    [73] =   99, -- Protection Warrior\n    [104] =  99, -- Guardian\n    [581] =  99, -- Vengeance\n    [268] =  99, -- Brewmaster\n    [66] =   99, -- Protection Paladin\n    [250] =  99, -- Blood dk\n}",
["do_custom"] = true,
},
["finish"] = {
["do_glow"] = false,
