["custom"] = "function(allstates, event, ...)\n    --custom coding it cause nameplate is in africa\n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID, _,_, auraType = ...\n        if subEvent == \"SPELL_CAST_START\"\n        and (spellID == 434252 or spellID == 465012) then\n            allstates[sourceGUID] = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                duration = 3.2,\n                expirationTime = 3.2 + GetTime(),\n                autoHide = true,\n            }\n            return true\n        elseif subEvent == \"UNIT_DIED\" then\n            local state = allstates[destGUID]\n            if state then\n                state.show = false\n                state.changed = true\n                return true\n            end\n        end\n    end\nend",
