["init"] = {
["custom"] = "aura_env.deaths = {}\n\naura_env.formattime = function(time, MS, dec)\n    if time then\n        local timeMin = math.floor(time / 60)\n        local timeSec = math.floor(time - (timeMin*60))\n        if timeMin < 10 then\n            timeMin = (\"0%d\"):format(timeMin)\n        end\n        if timeSec < 10 then\n            timeSec = (\"0%d\"):format(timeSec)\n        end        \n        return (\"%s:%s\"):format(timeMin, timeSec)\n    end\nend\n\naura_env.tooltip = function(deaths, timelost)\n    timelost = aura_env.formattime(timelost)\n    local text = \"Deaths: \"..deaths..\"\\nTime lost: \"..timelost..\"\\n\"\n    local list = {}\n    for u, num in pairs(aura_env.deaths) do\n        local name = NSAPI and NSAPI:Shorten(u, 8) or WA_ClassColorName(u)\n        table.insert(list, {name, num})\n    end\n    table.sort(list, \n        function(a, b)\n            if a[2] == b[2] then -- sort by name if deathcount is equal\n                return a[1] > b[1]\n            else -- otherwise sort by death count\n                return a[2] > b[2] \n            end\n            \n    end)\n    for _, v in ipairs(list) do\n        text = text..v[1]..\" \"..v[2]..\"\\n\"\n    end\n    return text\nend\n\n\naura_env.maptoID = { -- MapChallengeMode = JournalInstance\n    -- Cata\n    [438] = {68, \"Vortex Pinnacle\"},\n    [456] = {65, \"Throne\"},\n    [507] = {71, \"Grim Batol\"},\n    -- MoP\n    [2] = {313, \"Jade Serpent\"},\n    [56] = {302, \"Stromsout\"},\n    [57] = {303, \"Setting Sun\"},\n    [58] = {312, \"Shadow-Pan\"},\n    [59] = {324, \"Niuzao\"},\n    [60] = {321, \"Mogu'shan\"},\n    [76] = {246, \"Scholomance\"},\n    [77] = {311, \"Scarlet Halls\"},\n    [78] = {316, \"Monastery\"},\n    \n    -- WoD\n    [161] = {476, \"Skyreach\"},\n    [163] = {385, \"Slag Mines\"},\n    [164] = {547, \"Auchindoun\"},\n    [165] = {537, \"Shadowmoon\"},\n    [166] = {536, \"Grimrail\"},\n    [167] = {559, \"UBRS\"},\n    [168] = {556, \"Everbloom\"},\n    [169] = {558, \"Iron Docks\"},\n    \n    -- Legion\n    [197] = {716, \"Eye of Azshara\"},\n    [198] = {762, \"Darkheart\"},\n    [199] = {740, \"BRH\"},\n    [200] = {721, \"Halls of Valor\"},\n    [206] = {767, \"Neltharion's Lair\"},\n    [207] = {707, \"Vault\"},\n    [208] = {727, \"Maw of Souls\"},\n    [209] = {726, \"Arcway\"},\n    [210] = {800, \"Court of Stars\"},\n    [227] = {860, \"Kara: Lower\"},\n    [233] = {900, \"Cathedral\"},\n    [234] = {860, \"Kara: Upper\"},\n    [239] = {945, \"Seat\"},\n    \n    -- BfA\n    [244] = {968, \"Atal'Dazar\"},\n    [245] = {1001, \"Freehold\"},\n    [246] = {1002, \"Tol Dagor\"},\n    [247] = {1012, \"Motherlode\"},\n    [248] = {1021, \"Waycrest\"},\n    [249] = {1041, \"King's Rest\"},\n    [250] = {1030, \"Sethraliss\"},\n    [251] = {1022, \"Underrot\"},\n    [252] = {1036, \"Shrine\"},\n    [353] = {1023, \"Boralus\"},\n    [369] = {1178, \"Junkyard\"},\n    [370] = {1178, \"Workshop\"},\n    \n    -- Shadowlands\n    [375] = {1184, \"Mists\"},\n    [376] = {1182, \"Necrotic Wake\"},\n    [377] = {1188, \"Other Side\"},\n    [378] = {1185, \"Halls\"},\n    [379] = {1183, \"Plaguefall\"},\n    [380] = {1189, \"Sanguine\"},\n    [381] = {1186, \"Spires\"},\n    [382] = {1187, \"Theater\"},\n    [391] = {1194, \"Streets\"},\n    [392] = {1194, \"Gambit\"},\n    \n    -- Dragonflight\n    \n    \n    [399] = {1202, \"Ruby Pools\"},\n    [400] = {1198, \"Nokhud\"},\n    [401] = {1203, \"Azure Vault\"},\n    [402] = {1201, \"Academy\"},\n    [403] = {1197, \"Uldaman\"},\n    [404] = {1199, \"Neltharus\"},\n    [405] = {1196, \"Brackenhide\"},\n    [406] = {1204, \"Halls\"},\n    [463] = {1209, \"DotI: Lower\"},\n    [464] = {1209, \"DotI: Upper\"},\n    \n    -- The War Within\n    \n    [499] = {1267, \"Sacred Flame\"},\n    [500] = {1268, \"The Rookery\"},\n    [501] = {1269, \"Stonevault\"},\n    [502] = {1274, \"City of Threads\"},\n    [503] = {1271, \"Ara-Kara\"},\n    [504] = {1210, \"Darkflame Cleft\"},\n    [505] = {1270, \"Dawnbreaker\"},\n    [506] = {1272, \"Cinderbrew Maedery\"},\n    \n    \n}\n\n\n\n--[[\nhttps://wago.tools/db2/JournalInstance?page=1\nfor i = 500, 600 do \n    if C_ChallengeMode.GetMapUIInfo(i) then\n        print(C_ChallengeMode.GetMapUIInfo(i))\n    end\nend]]",
