["init"] = {
["custom"] = "aura_env.minversion = 13 -- NS Function Aura - Manual Version Number\naura_env.version = 2 -- Manual Version Number to mark important updates\naura_env.texts = {\n    \"Required WA out of date and not compatible:\",\n    \"Required WA missing:\",\n    \"Someone in your Raid has a newer version of this WA installed:\",    \n    \"MRT Note Mismatch detected, please send the Note again\",\n    \"MRT Note Mismatch detected, please send the Note again\\nSomeone in your Raid has a newer version of this WA installed:\",\n}",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["debuffType"] = "HELPFUL",
["duration"] = "10",
["event"] = "Health",
["unit"] = "player",
["names"] = {
},
["spellIds"] = {
},
["custom"] = "function(s, e, ...)\n    if e == \"OPTIONS\" then\n        s[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            text = \"Text that tells you something is out of date\",\n            url = \"url here\",\n            duration = 5,\n            expirationTime = 5+GetTime(),\n            autoHide = true,\n        }\n        return true\n    elseif e == \"READY_CHECK\" and ... then\n        if not NSAPI or not NSAPI.Version or NSAPI:Version() < aura_env.minversion then\n            local text = NSAPI and aura_env.texts[1] or aura_env.texts[2]\n            s[\"\"] = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                text = text,\n                url = \"https://wago.io/NorthernSky\",\n                duration = 8,\n                expirationTime = 8+GetTime(),\n                autoHide = true,\n            }\n            return true\n        end\n        local hashed = C_AddOns.IsAddOnLoaded(\"MRT\") and NSAPI:GetHash(NSAPI:GetNote()) or \"\" -- always sending this, just checking on receive if users wants to compare it\n        aura_env.hashed = hashed\n        aura_env.last = GetTime()\n        local waData = WeakAuras.GetData(aura_env.region:GetParent().id)      \n        local version = waData.url:match(\"%d+$\")\n        version = version and tonumber(version) or 0\n        if version ~= 0 then -- prevent doing anything if no version info is found (which should only be possible if its the author or someone manually edited it?\n            local url = waData.url:match(\".*%D\")\n            NSAPI:Broadcast(\"VERSION_NUM\", \"RAID\", version, aura_env.version, url, hashed)\n        end\n    elseif e == \"VERSION_NUM\" and ... then\n        local unit, vers, vers2, url, MRT = ...\n        url = url or \"\"\n        url = \"https:\"..url\n        local waData = aura_env.data or WeakAuras.GetData(aura_env.region:GetParent().id)  \n        aura_env.data = waData\n        local version = aura_env.data.url:match(\"%d+$\")\n        version = version and tonumber(version) or 0\n        if aura_env.config.MRTNote then\n            local hashed = \"\"\n            if aura_env.hashed and aura_env.last and aura_env.last > GetTime()-1 then\n                hashed = aura_env.hashed\n            else\n                hashed = C_AddOns.IsAddOnLoaded(\"MRT\") and NSAPI:GetHash(NSAPI:GetNote()) or \"\" \n                aura_env.last = GetTime()         \n            end\n            \n            local notecheck = MRT == \"\" or hashed == \"\" or hashed == MRT or not MRT -- don't compare if one user doesn't have MRT, they'll get their own error on relevant Auras\n            if not notecheck then\n                DebugPrint(\"diff note from \"..NSAPI:Shorten(unit, 8))\n                s[\"\"] = {\n                    show = true,\n                    changed = true,\n                    progressType = \"timed\",\n                    text = aura_env.texts[4],\n                    url = \"\",\n                    duration = 8,\n                    expirationTime = 8+GetTime(),\n                    autoHide = true,\n                }\n            end\n        end\n        local link = version ~= 0 and aura_env.data.url:match(\".*%D\") or \"\"        \n        if link ~= \"\" and link == url then -- only check if both users are using the same url, otherwise it makes no sense to compare versions. Also future proofs someone blindly copy pasting this WA into a different group\n            if aura_env.version < vers2 or (version < vers and aura_env.config.check) then -- manual set version in on init is lower, indicating missing an important update\n                if s[\"\"] then\n                    s[\"\"].text = aura_env.texts[5]\n                    s[\"\"].changed = true\n                else\n                    s[\"\"] = {\n                        show = true,\n                        changed = true,\n                        progressType = \"timed\",\n                        text = aura_env.texts[3],\n                        url = url,\n                        duration = 8,\n                        expirationTime = 8+GetTime(),\n                        autoHide = true,\n                    }\n                end\n            end\n        end\n        return true\n    end\nend\n\n\n",
["events"] = "READY_CHECK VERSION_NUM OPTIONS",
