["iconSource"] = -1,
["wagoID"] = "n7l5uN3YM",
["xOffset"] = 0,
["preferToUpdate"] = true,
["adjustedMin"] = "",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["cooldownSwipe"] = true,
["url"] = "https://wago.io/n7l5uN3YM/62",
["icon"] = true,
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "event",
["custom_hide"] = "timed",
["event"] = "Health",
["unit"] = "player",
["subeventSuffix"] = "_CAST_START",
["subeventPrefix"] = "SPELL",
["spellIds"] = {
},
["names"] = {
},
["check"] = "event",
["events"] = "CLEU:SPELL_CAST_SUCCESS:SPELL_CAST_START:SPELL_AURA_APPLIED:SPELL_AURA_REMOVED,KAZE_MRT_CUSTOM_EVENT,KAZE_MRT_PHASE_EVENT,KAZE_MRT_EVENT_NEW,ENCOUNTER_START,ENCOUNTER_END,MRT_NOTE_UPDATE,PLAYER_SPECIALIZATION_CHANGED,PARTY_MEMBERS_CHANGED,GROUP_ROSTER_UPDATE",
["custom"] = "function (event, ...)\n    local KT = aura_env\n    \n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" and KT.isCombat then\n        \n        local _, opt, _, _, caster, _, _, _, target, _, _, spellID = ...\n        \n        if (not KT.CLEU[opt]) then\n            return false\n        end\n        \n        local eventTable = {\n            SPELL_CAST_SUCCESS = \"SCC\",\n            SPELL_CAST_START = \"SCS\",\n            SPELL_AURA_APPLIED = \"SAA\",\n            SPELL_AURA_REMOVED = \"SAR\"\n        }\n        local thisEvent = eventTable[opt]\n        local condition = thisEvent .. spellID\n        local option_w_counter = nil\n        local option_wo_counter = nil\n        if KT.checks[condition] then\n            \n            KT.checks[condition] = KT.checks[condition] + 1\n            option_w_counter = thisEvent .. \":\" .. spellID .. \":\" .. KT.checks[condition]\n            option_wo_counter = thisEvent .. \":\" .. spellID .. \":\" .. 0\n        else\n            return false\n        end\n        local ct = KT.timers.conditionTimers\n        \n        if (ct[option_w_counter]) then\n            \n            for _, timer in pairs(ct[option_w_counter]) do\n                for _, input in pairs(timer.inputs) do\n                    if (input.show) then\n                        local start = input.time - input.warn\n                        local inputcopy = {} -- To allow duplicates\n                        for key, value in pairs(input) do\n                            inputcopy[key] = value\n                        end\n                        inputcopy.caster = caster\n                        inputcopy.target = target\n                        KT.runningTimers[#KT.runningTimers + 1] =\n                        C_Timer.NewTimer(start < 0 and 0.1 or start, function()\n                                KT.newTimer(start, inputcopy)\n                        end)\n                    end\n                end\n            end\n        end\n        \n        if (ct[option_wo_counter]) then\n            \n            for _, timer in pairs(ct[option_wo_counter]) do\n                for _, input in pairs(timer.inputs) do\n                    if (input.show) then\n                        local start = input.time - input.warn\n                        local inputcopy = {} -- To allow duplicates\n                        for key, value in pairs(input) do\n                            inputcopy[key] = value\n                        end\n                        inputcopy.caster = caster\n                        inputcopy.target = target\n                        KT.runningTimers[#KT.runningTimers + 1] =\n                        C_Timer.NewTimer(start < 0 and 0.1 or start, function()\n                                KT.newTimer(start, inputcopy)\n                        end)\n                    end\n                end\n            end\n        end   \n    elseif event == \"KAZE_MRT_CUSTOM_EVENT\" and KT.isCombat and ... then\n        \n        local ct = KT.timers.conditionTimers\n        local name, _ =...\n        if (not ct[name]) then\n            return false\n        end\n        for _, timer in pairs(ct[name]) do\n            for _, input in pairs(timer.inputs) do\n                if (input.show) then\n                    local start = input.time - input.warn\n                    local inputcopy = {} -- To allow duplicates\n                    for key, value in pairs(input) do\n                        inputcopy[key] = value\n                    end\n                    KT.runningTimers[#KT.runningTimers + 1] =\n                    C_Timer.NewTimer(start < 0 and 0.1 or start, function()\n                            KT.newTimer(start, inputcopy)\n                    end)\n                end\n            end\n        end\n        \n        \n        \n        \n        \n        \n        \n    elseif event == \"KAZE_MRT_PHASE_EVENT\" and KT.isCombat and ... then\n        local opt, opt2 = ...\n        local opts = opt .. opt2\n        if (not KT.checks[opts] or opt2 == KT.phase) then\n            return false\n        end\n        KT.checks[opts] = KT.checks[opts] + 1\n        KT.phase = opt2\n        KT.phaseStarted = GetTime()\n        local ct = KT.timers.conditionTimers\n        for _, timer in pairs(ct[opts]) do\n            for _, input in pairs(timer.inputs) do\n                if (input.show) then\n                    local start = input.time - input.warn\n                    local inputcopy = {} -- To allow duplicates\n                    for key, value in pairs(input) do\n                        inputcopy[key] = value\n                    end\n                    KT.runningTimers[#KT.runningTimers + 1] =\n                    C_Timer.NewTimer(start < 0 and 0.1 or start, function()\n                            KT.newTimer(start, inputcopy)\n                    end)\n                end\n            end\n        end\n    elseif event == \"MRT_NOTE_UPDATE\" then\n        \n        if KT.lastNoteUpdate then\n            KT.lastNoteUpdate:Cancel()\n        end\n        KT.lastNoteUpdate = C_Timer.NewTimer(0.1, function()\n                KT.readNote()\n                KT.lastNoteUpdate = nil\n        end)\n        \n    elseif event == \"PLAYER_SPECIALIZATION_CHANGED\" or event == \"GROUP_ROSTER_UPDATE\" then\n        \n        if (not KT.NoteLoaded) then\n            KT.readNote()\n        end\n        \n        KT.updateTimers()\n        if KT.isCombat then\n            KT.resetTimers()\n        end\n        \n    elseif event == \"ENCOUNTER_START\" and ... then\n        if (not C_AddOns.IsAddOnLoaded(\"MRT\")) then\n            DebugPrint(\"MRT not loaded\")\n            return\n        end\n        if (not (not (aura_env.config.disableWhen == 2 and _G.VMRT.Note.enabled == false) and\n                not (aura_env.config.disableWhen == 1 and GMRT.A.Note.frame:IsVisible() == false))) then\n            DebugPrint(\"Not loading because of disable conditions\")\n            return\n        end\n        local encid , encname,_,_ = ...\n        aura_env.eid[tostring(encid)]=true\n        aura_env.eid[encname]=true\n\n        aura_env.lasteid=aura_env.lasteid or encid\n\n        \n        local notesEqual = ((not KT.config.disableShared and _G.VMRT.Note.Text1 or \"\") == KT.notes[1]) and\n        ((not KT.config.disablePersonal and _G.VMRT.Note.SelfText or \"\") == KT.notes[2])\n        \n        if (not KT.NoteLoaded or not notesEqual or KT.noteEncounters[tostring(encid)] or KT.noteEncounters[encname] or (aura_env.lasteid ~= encid)) then\n            KT.readNote()\n        end\n        aura_env.lasteid = enncid\n        \n        KT.isCombat = true\n        KT.encounterStarted = GetTime()\n        KT.phaseStarted = KT.encounterStarted\n        KT.phase = 1\n        KT.updateTimers()\n        KT.checks = {}\n        for key, value in pairs(KT.timers.checks) do\n            KT.checks[key] = value\n        end\n        \n        for _, timer in pairs(KT.timers.regularTimers) do\n            for _, input in pairs(timer.inputs) do\n                if (input.show) then\n                    local start = input.time - input.warn\n                    KT.runningTimers[#KT.runningTimers + 1] =\n                    C_Timer.NewTimer(start < 0 and 0.1 or start, function()\n                            KT.newTimer(start, input)\n                    end)\n                end\n                \n            end\n        end\n        if (KT.timers.conditionTimers.p1) then\n            for _, timer in pairs(KT.timers.conditionTimers.p1) do\n                for _, input in pairs(timer.inputs) do\n                    if (input.show) then\n                        local start = input.time - input.warn\n                        local inputcopy = {} -- To allow duplicates\n                        for key, value in pairs(input) do\n                            inputcopy[key] = value\n                        end\n                        KT.runningTimers[#KT.runningTimers + 1] =\n                        C_Timer.NewTimer(start < 0 and 0.1 or start, function()\n                                KT.newTimer(start, inputcopy)\n                        end)\n                        \n                    end\n                end\n            end\n        end\n    elseif event == \"ENCOUNTER_END\" then\n        \n        KT.isCombat = false\n        KT.resetRunningTimers()\n        wipe(KT.eid)\n    end\nend\n\n",
