["events"] = "NS_FOOT_SHOW NS_FOOT_HIDE",
["custom"] = "function(s, e, ...)\n    if e == \"OPTIONS\" then\n        local pos = math.random(1, 4)\n        local unit = \"player\"\n        local color = math.random(1, 2)\n        local state = {\n            progressType = \"timed\",\n            duration = 20,\n            expirationTime = 20+GetTime(),\n            pos = pos,\n            unit = unit,\n            color = color,\n            autoHide = true,\n        }\n        s:Update(\"\", state)    \n        \n    elseif e == \"NS_FOOT_SHOW\" and ... then\n        local _, _, pos, unit, color = ...\n        local state = {\n            progressType = \"timed\",\n            duration = 20,\n            expirationTime = 20+GetTime(),\n            pos = pos,\n            unit = unit,\n            color = color,\n            autoHide = true,\n        }\n        s:Update(unit, state)        \n    elseif e == \"NS_FOOT_HIDE\" and ... then\n        local _, unit = ...\n        if s[unit] then\n            s:Remove(unit)\n        end\n    end\nend\n\n\n\n\n\n",
