["authorOptions"] = {
},
["displayText"] = "%c%",
["customText"] = "function() \n    function round(n)\n        return n % 1 >= 0.5 and math.ceil(n) or math.floor(n)\n    end\n    \n    local total_durability, current_durability, max_durability, fLoop, item_slots;\n    total_durability=0.00; -- will get NIL errors if we don't do this\n    item_slots=18;\n    \n    for fLoop=1, 18 do\n        current_durability,max_durability=GetInventoryItemDurability(fLoop);\n        \n        --ignore anything that doesn't have a durability\n        if (current_durability ~= NIL and max_durability ~= NIL) then\n            total_durability=(total_durability+(current_durability/max_durability*100));\n        else\n            item_slots=(item_slots-1);\n        end\n    end\n    \n    if (item_slots>0) then\n        total_durability=(total_durability/item_slots);\n        total_durability=round(total_durability);\n    else \n        total_durability=0.00\n    end\n    \n    return (total_durability)\nend;",
