["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["debuffType"] = "HELPFUL",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["names"] = {
},
["spellIds"] = {
},
["custom"] = "function(states, event, ...)\n    if event == \"STATUS\" or event == \"OPTIONS\" then\n        for _, profession in pairs(aura_env.GetProfessions()) do\n            -- Profession Cell\n            states[profession.id] = profession:FillState(states[profession.id])\n            -- Item cells\n            for _, item in pairs(profession:GetAvailableItems()) do\n                states[item.id] = item:FillState(states[item.id])\n            end\n        end\n        WeakAuras.ScanEvents(\"MKPT_UPDATE_DESCRIPTION\", nil)\n    elseif event == \"UNIT_SPELLCAST_SUCCEEDED\" then\n        local _, _, spellId = ...\n        \n        local item = aura_env.FindItemBySpellId(spellId)\n        if not item then\n            return false\n        end\n        \n        if item:IsHighlighted() then\n            item:ToggleHighlighted()\n            item:Untrack()\n        end\n        \n        -- Wow api does not reflect that the questId was completed at this point in time\n        C_Timer.After(0.5, function() WeakAuras.ScanEvents(\"MKPT_DELAYED_ITEM_UPDATE\", item) end)\n        return false\n    elseif event == \"ENCOUNTER_LOOT_RECEIVED\" then\n        local _, itemId, _ = ...\n        \n        local item = aura_env.FindItemByItemId(itemId)\n        if not item then\n            return false\n        end\n        \n        states[item.profession.id] = item.profession:FillState(states[item.profession.id])\n        states[itemId] = item:FillState(states[itemId])\n        \n        if item:IsHighlighted() then\n            item:ToggleHighlighted()\n            item:Untrack()\n        end\n        \n    elseif event == \"MKPT_CELL_CLICKED\" then\n        local stateId, _ = ...\n        local state = states[stateId]\n        \n        -- Collapse/Expand if it's a quest cell\n        if state and state.type == 0 then\n            local profession = aura_env.FindProfessionById(stateId)\n            profession.expanded = not profession.expanded\n            for _, item in pairs(profession:GetAvailableItems()) do\n                states[item.id] = item:FillState(states[item.id])\n            end\n            return true\n        end\n        \n        local oldHighlightedItemId = aura_env.highlightedItemId\n        local newHighlightedItemId = stateId\n        \n        local oldItem = aura_env.FindItemByItemId(oldHighlightedItemId)\n        if oldItem then\n            oldItem:ToggleHighlighted()\n            oldItem:Untrack()\n            states[oldItem.id] = oldItem:FillState(states[oldItem.id])\n        end\n        \n        local item = aura_env.FindItemByItemId(newHighlightedItemId)\n        if item and oldHighlightedItemId ~= newHighlightedItemId then\n            item:ToggleHighlighted()\n            item:Track()\n            states[item.id] = item:FillState(states[item.id])\n        end\n    elseif event ==\"SKILL_LINE_SPECS_RANKS_CHANGED\" or event== \"SKILL_LINE_SPECS_UNLOCKED\" then\n        for _, profession in pairs(aura_env.GetProfessions()) do\n            profession:RefreshSkillLevel()\n            states[profession.id] = profession:FillState(states[profession.id])\n        end\n        \n    elseif event == \"SKILL_LINES_CHANGED\" then\n        local missingProfession = aura_env.RemoveMissingProfession()\n        if not missingProfession then \n            return false\n        end\n        states[missingProfession.id] = { changed=true, show = false }\n        for _, item in pairs(missingProfession:GetAvailableItems()) do\n            states[item.id] = { changed=true, show = false }\n        end\n        WeakAuras.ScanEvents(\"MKPT_UPDATE_DESCRIPTION\", nil)\n        \n    elseif event == \"LEARNED_SPELL_IN_SKILL_LINE\" then\n        local spellId, professionSlotId, _ = ...\n        local professionSkillLineId = aura_env.FindKhazAlgarProfessionSkillLineBySpellId(spellId)\n        \n        if not professionSlotId or not professionSkillLineId then \n            return false\n        end\n        aura_env.professions = nil\n        for _, profession in pairs(aura_env.GetProfessions()) do\n            states[profession.id] = profession:FillState(states[profession.id])\n            for _, item in pairs(profession:GetAvailableItems()) do\n                states[item.id] = item:FillState(states[item.id])\n            end\n        end\n        WeakAuras.ScanEvents(\"MKPT_UPDATE_DESCRIPTION\", nil)\n        \n    elseif event == \"GET_ITEM_INFO_RECEIVED\" then\n        local itemId, success, _ = ...\n        if not success then return false end\n        \n        local item = aura_env.FindItemByItemId(itemId)\n        if not item then\n            return false\n        end\n        \n        item:RefreshItemInfo()\n        if not states[itemId] then\n            return false \n        end\n        states[item.id] = item:FillState(states[item.id])\n    elseif event == \"MKPT_DELAYED_ITEM_UPDATE\" then\n        local item = ...\n        if not item then return false end\n        \n        states[item.profession.id] = item.profession:FillState(states[item.profession.id])\n        \n        if states[item.id] then\n            states[item.id] = item:FillState(states[item.id])\n        end\n        \n        WeakAuras.ScanEvents(\"MKPT_UPDATE_DESCRIPTION\", nil)\n    elseif event == \"BAG_UPDATE_DELAYED\" then\n        return aura_env.RefreshItemRequirementsInfo(states)\n    elseif event == \"QUEST_DATA_LOAD_RESULT\" then\n        local questId, success = ...\n        if not success then return false end\n        \n        local entry = aura_env.FindEntryByQuestId(questId)\n        if not entry then return false end\n        \n        entry:RefreshItemInfo()\n        \n        if states[entry.id] then\n            states[entry.id] = entry:FillState(states[entry.id])\n        end\n        return true\n        \n    elseif event == \"QUEST_TURNED_IN\" then\n        local questId, _ = ...\n        \n        local entry = aura_env.FindEntryByQuestId(questId)\n        if not entry then return false end\n        \n        states[entry.profession.id] = entry.profession:FillState(states[entry.profession.id])\n        \n        if states[entry.id] then\n            states[entry.id] = entry:FillState(states[entry.id])\n        end\n        \n        if entry:IsHighlighted() then\n            WeakAuras.ScanEvents(\"MKPT_UPDATE_DESCRIPTION\", nil)\n        end\n    end\n    \n    return true\n    \nend",
["events"] = "MKPT_CELL_CLICKED    ENCOUNTER_LOOT_RECEIVED SKILL_LINE_SPECS_RANKS_CHANGED SKILL_LINE_SPECS_UNLOCKED LEARNED_SPELL_IN_SKILL_LINE GET_ITEM_INFO_RECEIVED SKILL_LINES_CHANGED UNIT_SPELLCAST_SUCCEEDED:player MKPT_DELAYED_ITEM_UPDATE BAG_UPDATE_DELAYED QUEST_TURNED_IN",
