["sparkHidden"] = "NEVER",
["actions"] = {
["start"] = {
["custom"] = "local state = aura_env.state\nlocal region = aura_env.region\n\nif not state.mkptbutton then\n    local pool = MKPTFramePool\n    local button, _ = pool:Acquire()\n    DebugPrint(\"Acquired button from pool:\",  pool:GetNumActive(), region.cloneId) \n    button:SetAllPoints(region)\n    button:RegisterForClicks(\"LeftButtonDown\")\n    button:SetScript(\"OnClick\", function(self, mouseButton, down) \n            if down then\n                DebugPrint(\"CellClicked:\", region.cloneId, self:GetID())\n                WeakAuras.ScanEvents(\"MKPT_CELL_CLICKED\", region.cloneId)            \n            end\n    end)\n    button:Show()\n    state.mkptbutton = button\nend",
["do_custom"] = true,
},
["finish"] = {
["custom"] = "local state = aura_env.state\nlocal region = aura_env.region\n\nif state and state.mkptbutton then\n    local pool = MKPTFramePool\n    pool:Release(state.mkptbutton)\n    state.mkptbutton = nil\n    \n    DebugPrint(\"Releasing button to pool:\", pool:GetNumActive(), region.cloneId, state.name)\nend\n\n\n\n\n",
["do_custom"] = true,
},
["init"] = {
["custom"] = "if not MKPTFramePool then\n    DebugPrint(\"Initializing frame pool\")\n    local resetterFunc = function (pool, frameToReset)\n        frameToReset:ClearAllPoints()\n        frameToReset:SetID(0)\n        frameToReset:UnregisterAllEvents()\n        frameToReset:Hide()\n    end\n    MKPTFramePool = CreateFramePool(\"Button\", nil, nil, resetterFunc)\nend\n\n\nlocal db = {\n    -- Alchemy\n    [2871]={\n        {type=1, questId={83840}, item=226265, waypoint={map=2339, x=0.3245, y=0.6034}, kp=3},  -- \"Earthen Iron Powder\"\n        {type=1, questId={83841}, item=226266, waypoint={map=2248, x=0.5770, y=0.6177}, kp=3},  -- \"Metal Dornogal Frame\"\n        {type=1, questId={83842}, item=226267, waypoint={map=2214, x=0.4218, y=0.2415}, kp=3},  -- \"Reinforced Beaker\"\n        {type=1, questId={83843}, item=226268, waypoint={map=2214, x=0.6496, y=0.6174}, kp=3},  -- \"Engraved Stirring Rod\"\n        {type=1, questId={83844}, item=226269, waypoint={map=2215, x=0.4265, y=0.5510}, kp=3},  -- \"Chemist's Purified Water\"\n        {type=1, questId={83845}, item=226270, waypoint={map=2215, x=0.4166, y=0.5583}, kp=3},  -- \"Sanctified Mortar and Pestle\"\n        {type=1, questId={83846}, item=226271, waypoint={map=2213, x=0.4537, y=0.1322}, kp=3},  -- \"Nerubian Mixing Salts\"\n        {type=1, questId={83847}, item=226272, waypoint={map=2255, x=0.4288, y=0.5724}, kp=3},  -- \"Dark Apothecary's Vial\"\n        {type=1, questId={81146}, item=227409, waypoint={map=2339, x=0.5983, y=0.5643}, kp=10, spell=459885}, -- Lyrendal. 200 - Faded Alchemist's Research \n        {type=1, questId={81147}, item=227420, waypoint={map=2339, x=0.5983, y=0.5643}, kp=10, spell=459886}, -- Lyrendal. 300 - Exceptional Alchemist's Research \n        {type=1, questId={81148}, item=227431, waypoint={map=2339, x=0.5983, y=0.5643}, kp=10, spell=459887}, -- Lyrendal. 400 - Pristine Alchemist's Research \n        {type=1, questId={83058}, item=224645, waypoint={map=2339, x=0.3908, y=0.2414