ailoring Notes\n        {type=1, questId={82634}, item=224036, waypoint={map=2213, x=0.5063, y=0.1680}, kp=10, spell=450840, text=\"Buy for 565 Kej\"}, -- And That's A Web-Wrap!\n        {type=2, questId={83735}, item=222547, waypoint={map=2339, x=0.5804, y=0.5645}, kp=1, spell=457719, text=\"Inscription work order\"}, -- Algari Treatise on Tailoring (Requires skill 25)\n        {type=2, questId={84132}, item=228779, waypoint={map=2339, x=0.5971, y=0.5627}, kp=2, text=\"Quest: Tailoring Services Requested\"}, -- Algari Tailor's Notebook\n        {type=2, questId={83269}, item=225221, kp=1}, -- \"Spool of Webweave\"\n        {type=2, questId={83270}, item=225220, kp=1}, -- \"Machine Speaker's\" \n        {type=3, questId={29520}, quest=29520, waypoint={map=407, x=0.5555, y=0.5500}, itemRequirements={{id=2320, quantity=1}, {id=2604, quantity=1}, {id=6260, quantity=1}}, kp=3}, -- Banners, Banners Everywhere!\n}}\n\nlocal skillLineIds = {\n    [164]=2872,\n    [171]=2871,\n    [202]=2875,\n    [393]=2882,\n    [197]=2883,\n    [333]=2874,\n    [165]=2880,\n    [755]=2879,\n    [186]=2881,\n    [182]=2877,\n    [773]=2878,\n}\n\nlocal khazAlgarMainProfessionSpellIds = {\n    [423322]=2871,\n    [423344]=2872,\n    [423346]=2874,\n    [423347]=2875,\n    [423349]=2877,\n    [423350]=2878,\n    [423351]=2879,\n    [423353]=2881,\n    [423354]=2882,\n    \n    [423321]=2871, \n    [423332]=2872, \n    [423334]=2874, \n    [423335]=2875, \n    [423338]=2878,\n    [423339]=2879,\n    [423340]=2880,\n    [423341]=2881, \n    [423342]=2882, \n    [423343]=2883,\n    [441327]=2877,\n}\n\n\nlocal MKPT_Item = {}\nMKPT_Item.__index = MKPT_Item\n\nfunction MKPT_Item:New(profession, itemInfo, index)\n    local item = {}\n    setmetatable(item, MKPT_Item)\n    item.id = itemInfo.item or itemInfo.quest\n    item.type = itemInfo.type\n    item.questIds = itemInfo.questId\n    item.waypoint = itemInfo.waypoint\n    item.kp = itemInfo.kp\n    item.unique = itemInfo.unique\n    item.profession = profession\n    item:RefreshItemInfo()\n    item.text = itemInfo.text\n    item.renown = itemInfo.renown\n    item.itemRequirements = itemInfo.itemRequirements\n    item.spellId = itemInfo.spell\n    item.index = index\n    return item\nend\n\nfunction MKPT_Item:RefreshItemInfo()    \n    if self.type == 3 then\n        local questTitle = C_QuestLog.GetTitleForQuestID(self.id)\n        if questTitle then\n            self.name = questTitle\n            -- Darkmoon Eye\n            self.icon = 1100023\n        end\n    else\n        local itemName, _, _, _, _, _, _, _, _, itemTexture, _ = C_Item.GetItemInfo(self.id)\n        if itemName then\n            self.name = itemName\n            self.icon = itemTexture\n        end\n    end\nend\n\n\nfunction MKPT_Item:GetRemainingKnowledgePoints()\n    local questCount = #self.questIds\n    \n    for _, questId in ipairs(self.questIds) do\n        if C_QuestLog.IsQuestFlaggedCompleted(questId) then\n            questCount = questCount - 1\n        end\n    end\n    \n    if self.unique then\n        return (questCount == #self.questIds and self.kp) or 0\n    else\n        return questCount * self.kp\n    end\nend\n\nfunction MKPT_Item:MeetRenownRequirements()\n    if self.renown then\n        local renownLevel = C_MajorFactions.GetCurrentRenownLevel(self.renown.majorFactionId) or 0\n        return renownLevel >= self.renown.levelRequired\n    end\n    return true\nend\n\nfunction MKPT_Item:MeetItemRequirements()\n    if self.itemRequirements then \n        for _, v in pairs(self.itemRequirements) do\n            local itemCount = C_Item.GetItemCount(v.id)\n            if v.quantity > itemCount then return false end\n        end\n    end\n    \n    return true\nend\n\nfunction MKPT_Item:MeetRequirements()\n    return self:MeetRenownRequirements() and self:MeetItemRequirements()\nend\n\nfunction MKPT_Item:Track()\n    WeakAuras.ScanEvents(\"MKPT_UPDATE_DESCRIPTION\", self:GetDescription())\n    local wp = self.waypoint\n    if not wp then return end\n    local mapPoint = UiMapPoint.CreateFromCoordinates(wp.map, wp.x, wp.y)\n    C_Map.SetUserWaypoint(mapPoint)\n    C_SuperTrack.SetSuperTrackedUserWaypoint(true)\n    local _, isTomTomLoaded = C_AddOns.IsAddOnLoaded(\"TomTom\")\n    if isTomTomLoaded and TomTom then\n        local itemName = self.name or \"Item not cached\"\n        local uid = TomTom:AddWaypoint(wp.map, wp.x, wp.y, {title=itemName, persistent=false, source=\"MKT_WA\"})\n        self.tomtomUid = uid\n    end\n    \nend\n\nfunction MKPT_Item:Untrack()\n    C_SuperTrack.SetSuperTrackedUserWaypoint(false)\n    C_Map.ClearUserWaypoint()\n    if TomTom and self.tomtomUid then\n        TomTom:RemoveWaypoint(self.tomtomUid)\n    end\n    WeakAuras.ScanEvents(\"MKPT_UPDATE_DESCRIPTION\", nil)\nend\n\nfunction MKPT_Item:IsHighlighted()\n    return aura_env.highlightedItemId == self.id\nend\n\nfunction MKPT_Item:ToggleHighlighted()\n    if self:IsHighlighted() then\n        aura_env.highlightedItemId = nil\n    else\n        aura_env.highlightedItemId = self.id\n    end\nend\n\nfunction MKPT_Item:GetDescription()\n    if not self.waypoint then\n        return self.text or \"Found on treasures around Khaz Algar\"\n    end\n    local renownText = \"\"\n    if not self:MeetRenownRequirements() then \n        local renownInfo = C_MajorFactions.GetMajorFactionData(self.renown.majorFactionId)\n        if renownInfo then\n            renownText = renownInfo.name..\": \\124cffFF0000\"..tostring(renownInfo.renownLevel)..\"\\124r/\"..tostring(self.renown.levelRequired)..\"\\n\"\n        end\n    end\n    local itemRequirements = \"\"\n    if self.itemRequirements then\n        for _,v in pairs(self.itemRequirements) do\n            local itemName = C_Item.GetItemNameByID(v.id) or \"item not loaded\"\n            local itemCount = C_Item.GetItemCount(v.id)\n            local meetsRequirements = itemCount >= v.quantity \n            if meetsRequirements then\n                itemRequirements = itemRequirements..tostring(itemCount)..\"/\"..tostring(v.quantity)..\" \"..itemName..\"\\n\"\n            else \n                itemRequirements = itemRequirements..WrapTextInColorCode(tostring(itemCount), \"ffff0000\")..\"/\"..tostring(v.quantity)..\" \"..itemName..\"\\n\"\n            end\n        end\n    end\n    local name = self.text or self.name or \"Not loaded yet\"\n    local mapInfo = C_Map.GetMapInfo(self.waypoint.map)\n    return string.format(\"%s%s\\n%s - x:%.2f y:%.2f\", renownText..itemRequirements, name, mapInfo.name, self.waypoint.x * 100, self.waypoint.y * 100)\nend\n\nfunction MKPT_Item:FillState(state)\n    state = state or {}\n    local remainingKnowledgePoints = self:GetRemainingKnowledgePoints()\n    state.changed = true\n    state.show = self.profession.expanded and remainingKnowledgePoints > 0 and (self.type ~= 1 or not aura_env.config.weekly) and (self.type ~= 3 or aura_env.IsDmfUp())\n    state.name = self.name\n    state.icon = self.icon\n    if self.type == 3 then\n        state.itemId = nil\n        state.tooltip= nil\n    else\n        state.itemId = self.id\n        state.tooltip= nil\n    end\n    state.glow = self:IsHighlighted()\n    state.rightText = \"+\"..tostring(remainingKnowledgePoints)\n    state.meetRequirements = self:MeetRequirements()\n    state.type = self.type\n    state.index = self.index\n    return state\nend\n\nlocal MKPT_Profession = {}\nMKPT_Profession.__index = MKPT_Profession\n\nfunction MKPT_Profession:New(professionId, name, icon, skillLevel, maxSkillLevel, skillLine, index)\n    local profession = {}\n    setmetatable(profession, MKPT_Profession)\n    profession.id = professionId\n    profession.expanded = not aura_env.config.minimized\n    profession.name = name\n    profession.icon=icon\n    profession.skillLevel = skillLevel\n    profession.maxSkillLevel = maxSkillLevel\n    profession.skillLine = skillLine\n    profession.availableItems = {}\n    profession.index = index\n    for itemIndex, itemInfo in ipairs(db[professionId]) do\n        local item = MKPT_Item:New(profession, itemInfo, profession.index + itemIndex)\n        table.insert(profession.availableItems, item)\n    end\n    return profession\nend\n\nfunction MKPT_Profession:CalculateRemainingKps()\n    local weekly = 0\n    local unique = 0\n    for _, item in pairs(self.availableItems) do\n        local remaining = item:GetRemainingKnowledgePoints()\n        if item.type == 1 then\n            unique = unique + remaining\n        else\n            weekly = weekly + remaining\n        end\n    end\n    return { weekly=weekly, unique=unique }\nend\n\nfunction MKPT_Profession:GetAvailableItems()\n    return self.availableItems\nend\n\nfunction MKPT_Profession:FillState(state)\n    state = state or {}\n    \n    local remaining = self:CalculateRemainingKps()\n    state.changed = true\n    state.show = true\n    state.name = self.name..\" \"..tostring(self.skillLevel)..\"/\"..tostring(self.maxSkillLevel)\n    state.icon = self.icon\n    state.index = self.index\n    state.glow = false\n    state.type = 0\n    state.rightText = \"U: \"..tostring(remaining.unique)\n    state.leftText = \"W: \"..tostring(remaining.weekly)\n    \n    return state\nend\n\nfunction MKPT_Profession:RefreshSkillLevel()\n    local prof1, prof2, _ = GetProfessions()\n    if prof1 then      \n        local _,_,skillLevel,maxSkillLevel,_,_,skillLine, _ = GetProfessionInfo(prof1)\n        if self.skillLine == skillLine then\n            self.skillLevel = skillLevel\n            self.maxSkillLevel = maxSkillLevel\n        end\n    end\n    if prof2 then      \n        local _,_,skillLevel,maxSkillLevel,_,_,skillLine, _ = GetProfessionInfo(prof2)\n        if self.skillLine == skillLine then\n            self.skillLevel = skillLevel\n            self.maxSkillLevel = maxSkillLevel\n        end  \n    end\nend\n\nfunction MKPT_Profession:IsLearned()\n    local prof1, prof2, _ = GetProfessions()\n    local currentProfessions = {}\n    if prof1 then      \n        local _,_,_,_,_,_,skillLine, _ = GetProfessionInfo(prof1)\n        currentProfessions[skillLine] = true\n    end\n    if prof2 then      \n        local _,_,_,_,_,_,skillLine, _ = GetProfessionInfo(prof2)\n        currentProfessions[skillLine] = true    \n    end\n    return currentProfessions[self.skillLine]\nend\n\naura_env.FindItemByItemId = function (itemId)\n    if not itemId then\n        return nil\n    end\n    for _, profession in pairs(aura_env.GetProfessions()) do\n        for _, item in pairs(profession:GetAvailableItems()) do\n            if item.id == itemId then\n                return item\n            end\n        end\n    end\n    return nil\nend\n\naura_env.FindEntryByQuestId = function (questId)\n    if not questId then\n        return nil\n    end\n    for _, profession in pairs(aura_env.GetProfessions()) do\n        for _, item in pairs(profession:GetAvailableItems()) do\n            if item.type == 3 and item.id == questId then\n                return item\n            end\n        end\n    end\n    return nil\nend\n\n\naura_env.FindItemBySpellId = function (spellId)\n    if not spellId then\n        return nil\n    end\n    for _, profession in pairs(aura_env.GetProfessions()) do\n        for _, item in pairs(profession:GetAvailableItems()) do\n            if item.spellId == spellId then\n                return item\n            end\n        end\n    end\n    return nil\nend\n\naura_env.FindProfessionById = function (professionId)\n    return aura_env.GetProfessions()[professionId]\nend\n\naura_env.FindKhazAlgarProfessionSkillLineBySpellId = function (spellId)\n    return khazAlgarMainProfessionSpellIds[spellId]\nend\n\naura_env.GetProfessions = function ()\n    if aura_env.config.showAllProfessions then\n        return aura_env.GetAllProfessions()\n    else \n        return aura_env.GetLearnedProfessions()     \n    end\nend\n\naura_env.GetLearnedProfessions = function ()\n    if aura_env.professions then \n        return aura_env.professions \n    end\n    local professions = {}\n    local prof1, prof2 ,_ = GetProfessions()\n    \n    for _, professionSlot in ipairs{prof1, prof2} do\n        local name,icon,skillLevel,maxSkillLevel,_,_,skillLine, _ = GetProfessionInfo(professionSlot)\n        local khazAlgarSkillLine = skillLineIds[skillLine]\n        professions[khazAlgarSkillLine]= MKPT_Profession:New(khazAlgarSkillLine, name, icon, skillLevel, maxSkillLevel, skillLine, professionSlot * 1000)\n    end\n    \n    aura_env.professions = professions\n    \n    return professions\nend\n\naura_env.GetAllProfessions = function ()\n    if aura_env.professions then \n        return aura_env.professions \n    end\n    local professions = {}\n    local index = 0\n    for khazAlgarSkillLine, _ in pairs(db) do\n        index = index + 1\n        local info = C_TradeSkillUI.GetProfessionInfoBySkillLineID(khazAlgarSkillLine)\n        local icon = C_TradeSkillUI.GetTradeSkillTexture(khazAlgarSkillLine)\n        professions[khazAlgarSkillLine]= MKPT_Profession:New(khazAlgarSkillLine, info.professionName, icon, info.skillLevel, info.maxSkillLevel, info.parentProfessionID, index * 1000)\n    end\n    \n    aura_env.professions = professions\n    \n    return professions\nend\n\naura_env.RemoveMissingProfession = function ()\n    local professions = aura_env.GetProfessions()\n    for _, profession in pairs(professions) do\n        if not profession:IsLearned() then\n            professions[profession.id] = nil\n            return profession\n        end       \n    end\nend\n\naura_env.IsDmfUp = function()\n    local dayOfWeek = tonumber(date(\"%w\"))\n    local dayOfMonth = tonumber(date(\"%e\"))\n    \n    local firstSundayOfMonth = ((dayOfMonth - (dayOfWeek + 1)) % 7) + 1\n    local daysSinceFirstSunday = dayOfMonth - firstSundayOfMonth\n    return daysSinceFirstSunday >= 0 and daysSinceFirstSunday <= 7\nend\n\naura_env.RefreshItemRequirementsInfo = function (states)\n    if not states then return false end\n\n    local changed = false\n    for _, profession in pairs(aura_env.GetProfessions()) do\n        for _, item in pairs(profession:GetAvailableItems()) do\n            if item.itemRequirements then\n                if states[item.id] then\n                    changed = true\n                    states[item.id] = item:FillState(states[item.id])\n                end\n                if item:IsHighlighted() then\n                    WeakAuras.ScanEvents(\"MKPT_UPDATE_DESCRIPTION\", item:GetDescription())\n                end\n            end\n        end\n    end\n    return changed\nend",
["do_custom"] = true,
},
},
