["Venom Nova Assign Handler"] = {
["outline"] = "OUTLINE",
["wagoID"] = "foNlg79Ol",
["color"] = {
1,
1,
1,
1,
},
["preferToUpdate"] = true,
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["automaticWidth"] = "Auto",
["actions"] = {
["start"] = {
["custom"] = "\n\n",
["do_custom"] = false,
},
["init"] = {
["custom"] = "aura_env.debug = false\naura_env.filter = aura_env.debug and \"HELPFUL\" or \"HARMFUL\"\naura_env.debuff = aura_env.debug and 774 or 464628\naura_env.cast = aura_env.debug and 8936 or 437417\naura_env.delay = aura_env.debug and 4 or 0.2\n\n\naura_env.MRT = function()\n    aura_env.list = {}\n    aura_env.me = {}\n    if C_AddOns.IsAddOnLoaded(\"MRT\") and VMRT.Note.Text1 then\n        local text = _G.VMRT.Note.Text1\n        local list = false\n        text = text:gsub(\"||r\", \"\") -- clean colorcode\n        text = text:gsub(\"||c%x%x%x%x%x%x%x%x\", \"\") -- clean colorcode\n        for line in text:gmatch('[^\\r\\n]+') do\n            line = strtrim(line) --trim whitespace\n            --check for start/end of the name list\n            if strlower(line) == \"nsnovastart\" then\n                list = true\n                aura_env.count = 0\n            elseif strlower(line) == \"nsnovaend\" then\n                list = false\n                aura_env.found = true\n            end\n            \n            if list and line and line ~= \"\" then \n                aura_env.list[aura_env.count] = {}\n                line = line:gsub(\"{.-}\", \"\") -- cleaning markers from line\n                for name in line:gmatch(\"%S+\") do -- finding all remaining strings\n                    if NSAPI then\n                        name = NSAPI:GetChar(name)\n                    end\n                    if UnitInRaid(name) then\n                        if UnitIsUnit(\"player\", name) then\n                            aura_env.me[aura_env.count] = true\n                        end\n                        table.insert(aura_env.list[aura_env.count], name)\n                    else -- checking for nickname if string didn't match player\n                        for unit in WA_IterateGroupMembers() do\n                            local uname = UnitName(unit)\n                            if uname:match(name) then\n                                if UnitIsUnit(\"player\", name) then\n                                    aura_env.me[aura_env.count] = true\n                                end\n                                table.insert(aura_env.list[aura_env.count], uname)  \n                                break\n                            end\n                        end\n                    end\n                end\n                aura_env.count = aura_env.count+1\n            end\n        end\n        -- note synch pointless in this aura because it has to save your own position\n    end  \nend\n\n\n\n\n\n",
["do_custom"] = true,
},
["finish"] = {
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["custom_hide"] = "timed",
["event"] = "Health",
["unit"] = "player",
["custom_type"] = "status",
["subeventPrefix"] = "SPELL",
["custom"] = "function(e, ...)\n    \n    if e == \"NSAPI_ENCOUNTER_START\" and ... then\n        aura_env.specs = NSAPI:GetSpecs()\n        aura_env.leader = \"raid1\"\n        aura_env.casts = 0\n        for unit in WA_IterateGroupMembers() do\n            if UnitIsVisible(unit) then\n                aura_env.leader = unit\n                break\n            end\n        end\n        aura_env.MRT()   \n        \n    elseif e == \"NS_ASSIGN_EVENT\" and ... and aura_env.id == ... then\n        local startnum = 0\n        local endnum = 0\n        if aura_env.casts == 1 then\n            startnum = 1\n            endnum = 2                \n        elseif aura_env.casts == 2 then\n            startnum = 3\n            endnum = 5\n        elseif aura_env.casts == 3 then\n            startnum = 6\n            endnum = 9\n        end\n        \n        for i = startnum, endnum, 1 do    \n            if aura_env.me[i] then       \n                local num = 0\n                for _, v in ipairs(aura_env.list[i]) do\n                    if UnitExists(v) and not (UnitIsDead(v)) and not (WA_GetUnitAura(v, aura_env.debuff, aura_env.filter)) and not (WA_GetUnitBuff(v, 27827)) then\n                        num = (aura_env.casts == 1 and i) or (aura_env.casts == 2 and i-2) or i-5 -- getting the \"marker number\" based on amount of casts\n                        if UnitIsUnit(\"player\", v) then\n                            -- you are assigned\n                            WeakAuras.ScanEvents(\"NS_VENOM_NOVA_YOU\", num)\n                        else\n                            -- someone else is assigned         \n                            WeakAuras.ScanEvents(\"NS_VENOM_NOVA\", num)           \n                        end\n                        return true\n                    end\n                end\n                -- this means no one is able to soak that color\n                NSAPI:Broadcast(\"NS_VENOM_NOVA_ALERT\", \"RAID\", num) -- skip target if Raid\n            end      \n        end      \n    elseif e == \"UNIT_SPELLCAST_START\" then\n        local u, cast, spellID = ... -- Unit event\n        if aura_env.found and spellID == aura_env.cast then\n            aura_env.casts = aura_env.casts and aura_env.casts + 1 or 1\n            WeakAuras.ScanEvents(\"NS_ASSIGN_EVENT\", aura_env.id)\n        end\n        -- print(\"no note/table found so not assigning anything\") -- prevents errors / could be useful to debug user issues\n    end\nend  \n\n\n\n\n\n\n",
