},
["custom"] = "function(s, e, ...)\n    if e == \"OPTIONS\" then\n        s[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 15,\n            expirationTime = GetTime() + 15,\n            autoHide = true\n        }\n        return true\n    elseif e == \"ENCOUNTER_START\" then\n        aura_env.affected = {}\n        \n    elseif e == \"NS_ORBCOUNT\" and ... then\n        local _, _, count = ...\n        \n        if count and count <= 0 and s[\"\"] then\n            s[\"\"].show = false\n            s[\"\"].changed = true\n            return true\n        end\n    else \n        local timestamp, subevent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID = ... -- full CLEU\n        \n        if subevent == \"SPELL_DAMAGE\" and aura_env.spells[spellID] and aura_env.affected[destGUID] then\n            s[\"\"] = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                duration = 15,\n                expirationTime = GetTime() + 15,\n                autoHide = true\n            }\n            \n            return true\n        elseif subevent == \"SPELL_AURA_APPLIED\" then\n            if spellID == 455850 then -- Mark of Rage 455850\n                aura_env.affected = aura_env.affected or {}\n                aura_env.affected[destGUID] = true\n            end\n        end\n    end\nend\n\n\n\n",
