["custom"] = "aura_env.region.configGroup = \"tempest_bar_ele\"\n\naura_env.lastTime = 0\naura_env.spenders = {\n    [8042] = true,   -- Earth Shock\n    [462620] = true, -- Earthquake\n    [117014] = true, -- Elemental Blast\n}\n\nlocal GetSpellPowerCost = C_Spell.GetSpellPowerCost\n\naura_env.GetMaelstromCost = function(spellId)\n    if spellId then\n        local costs = GetSpellPowerCost(spellId)\n        \n        if costs then\n            for _, info in pairs(costs) do\n                if 11 == info.type and info.cost > 0 then\n                    return info.cost\n                end\n            end\n        end\n    end\n    \n    return 0\nend",
