["custom"] = "function(allstates, event, ...)\n    local maelTotal = 300\n    \n    allstates[\"\"] = allstates[\"\"] or {\n        changed = false,\n        show = true,\n        progressType = \"static\",\n        value = 0,\n        total = maelTotal,\n        tempest = false,\n        cost = 0,\n    }\n    \n    local s = allstates[\"\"]\n    \n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local _, subevent, _, sourceGUID, _, _, _, _, _, _, _, spellId = ...\n        \n        if sourceGUID == WeakAuras.myGUID then\n            local now = GetTime()\n            \n            if spellId == 454015 then -- Tempest buff\n                if subevent == \"SPELL_AURA_APPLIED\" or subevent == \"SPELL_AURA_REFRESH\" then\n                    s.tempest = true\n                    \n                    if now - aura_env.lastTime <= 0.1 then\n                        s.value = max(0, s.value - maelTotal)\n                    end\n                    \n                    aura_env.lastTime = now\n                    \n                elseif subevent == \"SPELL_AURA_REMOVED\" then\n                    s.tempest = false\n                end\n                \n                s.changed = true\n                \n            elseif spellId then\n                if subevent == \"SPELL_CAST_START\" then\n                    if aura_env.spenders[spellId] then\n                        s.cost = aura_env.GetMaelstromCost(spellId)\n                    else\n                        s.cost = 0\n                    end\n                elseif subevent == \"SPELL_CAST_SUCCESS\" and aura_env.spenders[spellId] then\n                    if s.cost == 0 then\n                        s.cost = aura_env.GetMaelstromCost(spellId)\n                    end\n                    \n                    s.value = math.fmod(s.value + s.cost, maelTotal)\n                    \n                    aura_env.lastTime = now\n                    \n                    s.changed = true\n                end\n            end\n            \n            return s.changed\n        end\n    end\nend",
["events"] = "CLEU:SPELL_AURA_APPLIED:SPELL_AURA_REFRESH:SPELL_AURA_REMOVED:SPELL_CAST_SUCCESS:SPELL_CAST_START\n",
["check"] = "event",
["use_genericShowOn"] = true,
["use_track"] = true,
["customVariables"] = "{\n    value = true,\n    total = true,\n    tempest = {\n        display = \"Tempest Active\",\n        type = \"bool\"\n    }\n}",
},
