["anchorPoint"] = "TOPLEFT",
["displayText_format_p_time_format"] = 0,
["url"] = "https://wago.io/AT6ZmGDlK/2",
["actions"] = {
["start"] = {
["custom"] = "if aura_env.OpenRaid then\n    aura_env.OpenRaid.RegisterCallback(aura_env, \"KeystoneUpdate\", \"KeystoneUpdate\")\nend",
["do_custom"] = true,
},
["init"] = {
["custom"] = "aura_env.OpenRaid = LibStub:GetLibrary(\"LibOpenRaid-1.0\")\n\naura_env.rerollIcon = \" \\124T\" .. C_Spell.GetSpellInfo(398932).iconID .. \":0\\124t\"\n\nlocal keystoneItemId = 180653\nlocal affixLevels = {2,4,7,10}\nlocal keystoneItemName = nil\nlocal currentAffixes = nil\nfunction aura_env:CreateKeystoneLink(keystoneInfo)\n    if keystoneInfo == nil or keystoneInfo.level <= 0 then\n        return \"No Keystone\"\n    end\n    \n    if keystoneItemName == nil then\n        keystoneItemName = GetItemInfo(180653) -- mythic keystone item ID\n        keystoneItemName = string.gsub(keystoneItemName, \"^.* \", \"\")\n    end\n    \n    if currentAffixes == nil then\n        currentAffixes = {}\n        for i, affix in ipairs(C_MythicPlus.GetCurrentAffixes()) do\n            currentAffixes[i] = affix.id\n        end\n    end\n    \n    local keystoneLevel = keystoneInfo.level\n    \n    local mapChallengeModeID = keystoneInfo.mythicPlusMapID\n    if mapChallengeModeID == nil or mapChallengeModeID == 0 then\n        mapChallengeModeID = keystoneInfo.challengeMapID\n    end\n    \n    local mapChallengeModeName = C_ChallengeMode.GetMapUIInfo(mapChallengeModeID)\n    \n    local affixes = {}\n    for i, level in ipairs(affixLevels) do\n        local affix = 0\n        if level <= keystoneLevel then\n            affix = currentAffixes[i]\n        end\n        \n        affixes[i] = affix\n    end\n    \n    local affixLink = table.concat(affixes, \":\")\n    \n    return \"\\124cffa335ee\\124Hkeystone:\" .. keystoneItemId .. \":\" .. mapChallengeModeID .. \":\" .. keystoneLevel .. \":\" .. affixLink .. \"\\124h[\" .. keystoneItemName .. \": \" .. mapChallengeModeName .. \" (\" .. keystoneLevel .. \")]\\124h\\124r\"\nend\n\nfunction aura_env.KeystoneUpdate(unit, keystone, allKeystones)\n    WeakAuras.ScanEvents(\"DWA_PARTY_KEYSTONE_UPDATE\", unit, keystone)\nend",
["do_custom"] = true,
},
["finish"] = {
["custom"] = "if aura_env.OpenRaid then\n    aura_env.OpenRaid.UnregisterCallback(aura_env, \"KeystoneUpdate\", \"KeystoneUpdate\")\nend",
["do_custom"] = true,
},
},
