["customText"] = "function()\n    return aura_env.KeyAlertText\nend\n\n\n\n",
["shadowYOffset"] = 0,
["cooldownSwipe"] = true,
["customTextUpdate"] = "event",
["cooldownEdge"] = false,
["triggers"] = {
{
["trigger"] = {
["itemName"] = 0,
["duration"] = "5",
["genericShowOn"] = "showOnCooldown",
["names"] = {
},
["customIcon"] = "\n\n",
["debuffType"] = "HELPFUL",
["custom_hide"] = "timed",
["type"] = "custom",
["use_genericShowOn"] = true,
["subeventSuffix"] = "_CAST_START",
["unit"] = "player",
["use_itemName"] = true,
["event"] = "Cooldown Progress (Item)",
["customStacks"] = "",
["custom"] = "function(allstates, event, ...)\n    if not aura_env.OpenRaid then \n        print(aura_env.id .. \": Please Install LibOpenRaid. This comes preinstalled with ||||||||cFF8080FFDetails! Damage Meter||||||||r or ||||||||cFF8080FFEcho Raid Tools||||||||r.\")\n        return false \n    end\n    \n    if event == \"CHALLENGE_MODE_COMPLETED\" then\n        -- check if player can reroll\n        local _, completedLevel, _, completedOnTime, _, _, _, _, _, _, _, _, _ = C_ChallengeMode.GetCompletionInfo();\n        if not completedOnTime then\n            -- cannot reroll if the key was not timed\n            return false\n        end\n        \n        local playerKeystone = aura_env.OpenRaid.GetKeystoneInfo(\"player\")\n        if playerKeystone.level > completedLevel then\n            -- cannot reroll if player's current key is higher level\n            return false\n        end\n        \n        print(\"Completed Mythic Keystone +\"..completedLevel)\n        \n        -- get the names of party members\n        local playerName = UnitName(\"player\")\n        local partyMembers = {}\n        table.insert(partyMembers, playerName)\n        if IsInGroup() then\n            for i = 1, GetNumGroupMembers()-1 do\n                local unitName = GetUnitName(\"party\"..i, true)\n                if unitName ~= nil then\n                    if not UnitIsUnit(\"player\", unitName) then\n                        table.insert(partyMembers, unitName)\n                    end\n                end\n            end\n        end\n        \n        -- display the party keystones\n        for _, unitName in ipairs(partyMembers) do\n            local keystone = aura_env.OpenRaid.GetKeystoneInfo(unitName)\n            if keystone ~= nil and keystone.level > 0 then\n                allstates[UnitGUID(unitName)] = {\n                    show = true,\n                    changed = true,\n                    progressType = \"timed\",\n                    duration = aura_env.config.duration,\n                    autoHide = true,\n                    playerName = WA_ClassColorName(unitName),\n                    keystone = aura_env:CreateKeystoneLink(keystone),\n                    reroll = (keystone.level <= completedLevel) and aura_env.rerollIcon or \"\",\n                }\n            end\n        end\n        \n        return true\n    elseif event == \"DWA_PARTY_KEYSTONE_UPDATE\" then\n        -- someone rerolled their keystone\n        local unitName, keystone = ...\n        \n        -- check if we are currently displaying this player's keystone\n        local state = allstates[UnitGUID(unitName)]\n        if state == nil or not state.show then\n            return false\n        end\n        \n        -- update their keystone information\n        state.keystone = aura_env:CreateKeystoneLink(keystone)\n        state.reroll = \"\"\n        state.changed = true\n        \n        return true\n    elseif event == \"OPTIONS\" then\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            playerName = WA_ClassColorName(\"player\"),\n            keystone = aura_env:CreateKeystoneLink(aura_env.OpenRaid.GetKeystoneInfo(\"player\")),\n            reroll = aura_env.rerollIcon,\n        }\n        \n        return true\n    end\n    \n    return false\nend",
["customName"] = "function()\n    aura_env.KeyAlertText = (WA_ClassColorName(UnitName(\"player\")) .. \", is your +\"..aura_env.KeyLevel..\" the key?\")\n    return aura_env.KeyAlertText\nend\n\n\n\n\n",
