["customText"] = "function()\n    if NSAPI and aura_env.state and aura_env.state.unit and aura_env.state.partner then\n        local name, role = NSAPI:Shorten(aura_env.state.unit, 8)\n        local name2, role2 = NSAPI:Shorten(aura_env.state.partner, 8)\n        role = role or \"\"\n        role2 = role2 or \"\"\n        return role..name, name2..role2\n    end\nend",
["cooldownSwipe"] = true,
["sparkRotationMode"] = "AUTO",
["cooldownEdge"] = false,
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["customVariables"] = "{   \n    additionalProgress = 2,\n    left = \"number\",\n    right = \"number\",\n}\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n",
["event"] = "Combat Log",
["unit"] = "player",
["custom_type"] = "stateupdate",
["subeventPrefix"] = "SPELL",
["custom"] = "function(s, e, ...)\n    if e == \"OPTIONS\" then\n        for i=1, 10 do\n            local left = math.random(1, 2)\n            local right = math.random(1, 2)\n            s[i] = {\n                unit = \"player\",\n                partner = \"player\",\n                value = 0,\n                total = 100,\n                left = left,\n                right = right,\n                index = (left == right and (left == 1 and 1 or 2)) or (left == 1 and 3 or 4),\n                show = true,\n                autoHide = false,\n                progressType = \"static\",\n                changed = true,\n                additionalProgress ={\n                    { \n                        direction = \"forward\",\n                        width = 50,\n                        offset = 0,\n                    },\n                    { \n                        direction = \"forward\",\n                        width = 50,\n                        offset = 50,\n                    }\n                },\n                \n            }\n        end\n        return true\n    else\n        local timestamp, subevent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID = ... -- full CLEU\n        if spellID == aura_env.debuff then\n            if subevent == \"SPELL_AURA_APPLIED\" then\n                local partner = select(7, WA_GetUnitAura(destName, aura_env.debuff, aura_env.filter))\n                if UnitExists(partner) then\n                    local sGUID = UnitGUID(partner)\n                    if not (s[sGUID] or s[destGUID]) then\n                        local unit = \"raid\"..UnitInRaid(destName)\n                        partner = \"raid\"..UnitInRaid(partner)\n                        if aura_env.debug or not (UnitIsUnit(unit, partner)) then\n                            \n                            local left = (WA_GetUnitDebuff(unit, 455849) and 1) or (WA_GetUnitDebuff(unit, 455850) and 2) or 0\n                            local right = (WA_GetUnitDebuff(partner, 455849) and 1) or (WA_GetUnitDebuff(partner, 455850) and 2) or 0\n                            \n                            s[destGUID] = {\n                                unit = unit,\n                                partner = partner,\n                                value = 0,\n                                total = 100,\n                                left = left,\n                                right = right,\n                                index = (left == right and (left == 1 and 1 or 2)) or (left == 1 and 3 or 4),\n                                show = true,\n                                autoHide = false,\n                                progressType = \"static\",\n                                changed = true,\n                                additionalProgress ={\n                                    { \n                                        direction = \"forward\",\n                                        width = 50,\n                                        offset = 0,\n                                    },\n                                    { \n                                        direction = \"forward\",\n                                        width = 50,\n                                        offset = 50,\n                                    }\n                                },\n                            }                        \n                            \n                            return true\n                        end\n                    end\n                end\n                \n            elseif subevent == \"SPELL_AURA_REMOVED\" then\n                if s[sourceGUID] then\n                    s[sourceGUID].show = false\n                    s[sourceGUID].changed = true\n                    return true\n                elseif s[destGUID] then\n                    s[destGUID].show = false\n                    s[destGUID].changed = true\n                    return true\n                end\n            end\n        end\n    end\nend",
