["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["spellIds"] = {
},
["custom"] = "function(s, e, ...)\n    if e == \"OPTIONS\" then\n        s[\"\"] = {\n            show = true,\n            progressType = \"static\",\n            number = math.random(1, 4),\n            color = math.random(1, 2),\n            mark = \"{rt\"..aura_env.num..\"}\",\n            unit = \"player\",\n            autoHide = true,\n            changed = true,\n        }\n    elseif C_AddOns.IsAddOnLoaded(\"NorthernSkyMedia\") then\n        local num = ...\n        if num == aura_env.num  then -- check if the event is for this specific mine\n            if e == \"NS_FOOT_SHOW\" then \n                local _, duration, pos, unit = ...\n                s[\"\"] = {\n                    show = true,\n                    duration = duration,\n                    progressType = \"timed\",\n                    expirationTime = GetTime()+duration,\n                    mark = \"{rt\"..aura_env.num..\"}\",\n                    number = pos, -- trigger order\n                    unit = unit, \n                    autoHide = true,\n                    changed = true,\n                }\n                return true\n                \n            elseif e == \"NS_FOOT_HIDE\" then -- sent event from handler with correct num\n                if s[\"\"] then \n                    s[\"\"].show = false\n                    s[\"\"].changed = true\n                    return true\n                end\n            end\n        end\n    end\nend\n\n\n\n\n\n\n",
