},
["custom"] = "function(s, e, ...)\n    if e == \"OPTIONS\" then\n        for i=1, 4 do\n            local pos = i\n            local unit = \"player\"\n            local duration = 10\n            local num = math.random(1, 8)\n            s[i] = {\n                show = true,\n                duration = duration,\n                progressType = \"timed\",\n                expirationTime = GetTime()+duration,\n                index = pos, -- trigger order\n                unit = unit,\n                name = unit and NSAPI:Shorten(unit, 8),\n                mark = \"{rt\"..num..\"}\",\n                text = (pos == 1 and \"1st\") or (pos == 2 and \"2nd\") or (pos == 3 and \"3rd\") or (pos == 4 and \"4th\"),\n                autoHide = true,\n                changed = true,\n            }\n        end\n        return true\n    else\n        if e == \"NS_FOOT_SHOW\" then \n            local num, duration, pos, unit = ...\n            s[unit] = {\n                show = true,\n                duration = duration,\n                progressType = \"timed\",\n                expirationTime = GetTime()+duration,\n                index = pos, -- trigger order\n                unit = unit,\n                name = unit and NSAPI:Shorten(unit, 8),\n                rawname = unit and UnitName(unit),\n                mark = \"{rt\"..num..\"}\",\n                text = (pos == 1 and \"1st\") or (pos == 2 and \"2nd\") or (pos == 3 and \"3rd\") or (pos == 4 and \"4th\"),\n                autoHide = true,\n                changed = true,\n            }\n            return true\n        elseif e == \"NS_FOOT_HIDE\" then\n            local num, G = ...\n            if s[G] then\n                s[G].show = false\n                s[G].changed = true\n                return true\n            end\n        end\n    end\nend\n\n\n\n\n",
