["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["custom_hide"] = "timed",
["customVariables"] = "{\n    spellId=\"number\",\nspellName=\"string\",\n    expirationTime=true,\n    name=\"string\",\n    unit=\"string\",\nnotetype=\"string\",\nttsEnabled=\"bool\"\n    \n    \n}",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["unit"] = "player",
["custom"] = "\n\n--- ERT TIMERS ICONS FROM NOTES\n-- REMEMBER TO REMOVE DUMMY\nfunction (allstates, event, ...)\n    \n    \n    if event == \"KAZE_MRT_EVENT_NEW_TEXTS\" then\n        local timer=...\n        local statenr=#allstates+1\n        allstates[statenr] = timer\n        allstates[statenr].changed=true\n        \n        if timer.ttsEnabled then\n            local str=timer.ttsMessage\n            local start = timer.ttsRemainingTime > -1 and timer.expirationTime - GetTime() - timer.ttsRemainingTime or 0.1\n            C_Timer.After(start < 0 and 0.1 or start, function()\n                    C_VoiceChat.SpeakText(C_TTSSettings.GetVoiceOptionID(0), str, 1, C_TTSSettings and C_TTSSettings.GetSpeechRate() or 0,\n                        C_TTSSettings and C_TTSSettings.GetSpeechVolume() or 100)\n            end)\n        end\n        \n        \n        if(timer.delay>0) then\n            C_Timer.After(\n                timer.delay+timer.expirationTime - GetTime(),\n                function()\n                    WeakAuras.ScanEvents(\"KAZE_MRT_EVENT_NEW_TEXTS_REMOVE\",statenr)                                    \n                end\n            )\n        end\n        \n    elseif event == \"KAZE_MRT_EVENT_NEW_TEXTS_REMOVE\" then\n        local statenr=...\n        if allstates[statenr] then\n            allstates[statenr].show=false\n            allstates[statenr].changed=true \n            \n        end       \n        \n    end\n    return true\n    \nend",
["spellIds"] = {
},
["events"] = "KAZE_MRT_EVENT_NEW_TEXTS,KAZE_MRT_EVENT_NEW_TEXTS_REMOVE",
