["actions"] = {
["start"] = {
["do_message"] = false,
},
["finish"] = {
},
["init"] = {
["custom"] = "aura_env.region.configGroup = \"cast_bar\"\n\nlocal bar = aura_env.region.bar\n\nlocal ticks = {}\nfor i=1,4 do\n    local tickMark = bar:CreateTexture()\n    tickMark:SetColorTexture(1, 1, 1, 1)\n    tickMark:SetSize(3, bar:GetHeight())\n    tickMark:SetPoint(\"CENTER\", bar, \"LEFT\", 0, 0)\n    tickMark:SetDrawLayer(\"ARTWORK\", 7);\n    tickMark:Hide()\n    \n    ticks[i] = tickMark\nend\n\nlocal function GetTickInterval()\n    local base = 1\n    \n    -- azure celerity\n    if IsPlayerSpell(1219723) then\n        base = base * 0.8\n    end\n    \n    -- natural convergance\n    if IsPlayerSpell(369913) then\n        base = base * 0.8\n    end\n    \n    \n    local haste = 1 + UnitSpellHaste(\"player\") / 100\n    \n    return base / haste\nend\n\nlocal function GetTotalDuration()\n    local _, _, _, startTime, endTime = UnitChannelInfo(\"player\")\n    \n    return (endTime - startTime) / 1000\nend\n\nlocal function UpdateTickMarks()\n    local tickInterval = GetTickInterval()\n    local duration = GetTotalDuration()\n    \n    local offset = tickInterval / duration\n    \n    for i, tickMark in ipairs(ticks) do\n        tickMark:SetPoint(\"CENTER\", bar, \"LEFT\", i * offset * bar:GetWidth(), 0)\n        \n        if tickInterval * i < duration * 0.99 then\n            tickMark:SetSize(3, bar:GetHeight())\n            tickMark:Show()\n        else\n            tickMark:Hide()\n        end\n    end\nend\n\nlocal function HideTickMarks()\n    for _, tickMark in ipairs(ticks) do\n        tickMark:Hide()\n    end\nend\n\naura_env.trigger = UpdateTickMarks\naura_env.untrigger = HideTickMarks\n\n",
["do_custom"] = true,
},
},
