["custom"] = "function(s, e, ...)\n    if e == \"OPTIONS\" then\n        local duration = 6.8\n        s[\"\"] = {\n            duration = duration,\n            expirationTime = GetTime() + duration,\n            progressType = \"timed\",\n            autoHide = true,\n            changed = true,\n            show = true,\n        }\n        for i = 1, 6 do\n            s[i] = {\n                correct = i == 1,\n                duration = duration,\n                expirationTime = GetTime() + duration,\n                progressType = \"timed\",\n                autoHide = true,\n                changed = true,\n                show = true,\n                index = i,\n            }\n        end\n        local aura_env = aura_env\n        C_Timer.After(0.01, function()\n                aura_env.sortAndOffset()\n        end)\n        return true\n        --[[if e == \"OPTIONS\" then\n        s[\"\"] = {\n            show = true,\n            changed = true,\n            duration = 6,\n            expirationTime = GetTime()+6,\n            progressType = \"timed\",\n            autoHide = true,\n        }]]\n    elseif e == \"STATUS\" then\n        s[\"\"] = {\n            show = true,\n            changed = true,\n            hide = true,\n            duration = 0.1,\n            expirationTime = GetTime()+0.1,\n            progressType = \"timed\",\n            autoHide = true,\n        }\n    end\n    return true\nend",
