["main"] = {
["colorR"] = 1,
["scalex"] = 1,
["alphaType"] = "custom",
["colorB"] = 0,
["colorG"] = 0.23137256503105,
["alphaFunc"] = "function(progress, start, delta)\n    return start + (progress * delta)\nend\n",
["use_translate"] = false,
