["custom"] = "function(s, e, ...)\n    if e == \"OPTIONS\" then\n        s[\"\"] = {\n            show = true,\n            changed = true,\n            blue = \"|cFF0096FF\"..8,\n            red = \"|cFFEE4B2B\"..\"6|r\",\n            autoHide = false,\n        }        \n        return true\n    elseif e == \"NS_ORBCOUNT\" and ... then\n        local id, blue, red = ...\n        if id == aura_env.id then\n            \n            s[\"\"] = {\n                show = true,\n                changed = true,\n                blue = \"|cFF0096FF\"..blue,\n                red = \"|cFFEE4B2B\"..red..\"|r\",\n                autoHide = false,\n            }\n            \n            return true\n        end\n        \n    elseif e == \"ENCOUNTER_START\" then\n        \n        aura_env.countb = 0\n        aura_env.countr = 0   \n        aura_env.blue = {}\n        aura_env.red = {}\n        WeakAuras.ScanEvents(\"NS_ORBCOUNT\", aura_env.countb, aura_env.countr)\n        \n    else\n        local timestamp, subevent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID, _, _, miss = ... -- full CLEU\n        if spellID == 460359 and (subevent == \"SPELL_AURA_APPLIED\" or subevent == \"SPELL_AURA_APPLIED_DOSE\" or subevent == \"SPELL_AURA_REFRESH\") then -- Void Degeneration 460359\n            aura_env.countb = math.max(aura_env.countb-1, 0)   \n            WeakAuras.ScanEvents(\"NS_ORBCOUNT\", aura_env.id, aura_env.countb, aura_env.countr) -- could just state on all of these but need the scan event for other aura anyway so might aswell have it be a bit cleaner this way\n        elseif spellID == 460281 and (subevent == \"SPELL_AURA_APPLIED\" or subevent == \"SPELL_AURA_APPLIED_DOSE\" or subevent == \"SPELL_AURA_REFRESH\") then -- Burning Rage 460281\n            aura_env.countr = math.max(aura_env.countr-1, 0)  \n            WeakAuras.ScanEvents(\"NS_ORBCOUNT\", aura_env.id, aura_env.countb, aura_env.countr)\n            \n        elseif subevent == \"SPELL_AURA_APPLIED\" then\n            if spellID == 455849 then -- Mark of Paranoia 455849\n                aura_env.blue = aura_env.blue or {}\n                aura_env.blue[destGUID] = true\n            elseif spellID == 455850 then  -- Mark of Rage 455850\n                aura_env.red = aura_env.red or {}\n                aura_env.red[destGUID] = true\n            end\n            \n        elseif aura_env.spells[spellID] and (subevent == \"SPELL_DAMAGE\" or (subevent == \"SPELL_MISSED\" and miss == \"ABSORB\")) then --  got hit by any mechanic\n            if aura_env.blue[destGUID] then\n                aura_env.countb = aura_env.countb+1                \n                WeakAuras.ScanEvents(\"NS_ORBCOUNT\", aura_env.id, aura_env.countb, aura_env.countr)\n            elseif aura_env.red[destGUID] then\n                aura_env.countr = aura_env.countr+1                \n                WeakAuras.ScanEvents(\"NS_ORBCOUNT\", aura_env.id, aura_env.countb, aura_env.countr)\n            end\n        end\n    end\nend\n\n\n\n",
