["customText"] = "function()\n    local u = aura_env.state and aura_env.state.unit\n    if WeakAuras.IsOptionsOpen() then\n        u = \"player\"\n        if NSAPI then\n            local name, role = NSAPI:Shorten(u, 8, true)\n            return name, role\n        else\n            return WA_ClassColorName(u), \"\"\n        end\n    elseif u then\n        if NSAPI then\n            local name, role = NSAPI:Shorten(u, 8, true)\n            return name, role\n        else\n            return WA_ClassColorName(u), \"\"\n        end\n    end\nend\n\n\n\n\n\n\n\n\n",
