["names"] = {
},
["custom"] = "-- using throttle'd everyframe as there's not a great way to track this when people can break the fixate with things like feign death\nfunction(s, e, ...)\n    if not aura_env.last or aura_env.last < GetTime() - 0.5 then\n        aura_env.last = GetTime()        \n        for _, v in pairs(s) do\n            v.show = false\n            v.changed = true\n        end\n        for i=1, 40 do\n            local u = \"nameplate\"..i\n            if UnitExists(u) then\n                local id = select(6, strsplit(\"-\", UnitGUID(u)))\n                if id == \"231788\" then\n                    if UnitExists(u..\"target\") then\n                        -- possibly scan event to detect this person to have a fixate\n                        if UnitIsUnit(u..\"target\", \"player\") then\n                            s[u] = {\n                                show = true,\n                                changed = true, \n                                unit = u,\n                                progressType = \"static\",\n                                autoHide = true,\n                            }\n                        end\n                    end\n                end\n            end\n        end\n        return true\n    end\nend",
