["Breath Counter"] = {
["outline"] = "OUTLINE",
["wagoID"] = "efRZ4pfaV",
["authorOptions"] = {
},
["displayText"] = "%c",
["customText"] = "function()\n    local Uptime = GetTime()\n    local inRange = 0\n    \n    if aura_env.startTime and aura_env.startTime > 0 then\n        aura_env.duration = string.format(\"%.1f\", (GetTime() - aura_env.startTime))\n        \n        \n        if _G['breathCount'] == nil then\n            aura_env.targetCount = 0\n        else\n            aura_env.targetCount = _G['breathCount']\n        end\n        \n        --Get nearby targets ~ 8 yards\n        for i = 1, 40 do\n            local unit = \"nameplate\"..i\n            if UnitExists(unit) and not UnitIsFriend(\"player\", unit) and IsItemInRange(33278, \"nameplate\"..i) == true then\n                inRange = inRange + 1\n            end\n        end\n        \n        if(inRange < aura_env.targetCount) then\n            inRange = aura_env.targetCount\n        end\n        return aura_env.duration..(\"\\n\\n\\n\\n\\n\")..aura_env.targetCount..(\"/\")..inRange\n        \n        --return \"Breath Ended\\nDamage: |cFF00FF00\"..damageString..\"|r\\nDuration: |cFFFFFF00\"..string.format(\"%.2f\", aura_env.duration)..\"|r\"\n        \n    end\n    return \"\"\nend",
