["custom"] = "function (allstates, event, ...)\n    if aura_env.Note == nil then return end\n    \n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        if not aura_env.cleucheck then\n            return false\n        end\n        local _, subEvent, _, sourceGUID, _, sourceFlags, _, destGUID, _, destFlags, _, spellID, spellName = ...\n        \n        --if aura_env.eventTable[subEvent] then\n        --    print(subEvent, spellID, spellName) \n        --end\n        \n        local checks = aura_env.CLEU[subEvent] and aura_env.CLEU[subEvent][spellID]\n        if checks then\n            aura_env.CLEUcounters[subEvent][spellID] = aura_env.CLEUcounters[subEvent][spellID] + 1\n            local count = aura_env.CLEUcounters[subEvent][spellID]\n            --DebugPrint(\"CLEU\", subEvent, spellName, count)\n            local now = GetTime()\n            for _, note in ipairs(checks) do\n                if aura_env.testCounter(note.count, count) then\n                    local target = subEvent == \"SPELL_CAST_START\" and sourceGUID or destGUID\n                    local flags = subEvent == \"SPELL_CAST_START\" and sourceFlags or destFlags\n                    \n                    WeakAuras.ScanEvents(\n                        \"MRT_NOTE_NEW\",\n                        now + note.time,\n                        note.line,\n                        nil,\n                        note.noteType,\n                        { subEvent = subEvent, spellId = spellId, count = count, target = target, flags = flags }\n                    )\n                    \n                    --DebugPrint(\"New CLEU Timer\", subEvent, spellID, count, note.line, note.time)\n                end\n            end\n        end\n    elseif event == \"MRT_NOTE_PHASE\"\n    and (IsAddOnLoaded(\"ExRT\") or IsAddOnLoaded(\"MRT\"))\n    and ...\n    then\n        local _, stage = ...\n        if stage == aura_env.stage then\n            return false\n        end\n        DebugPrint(\"New Phase\", stage)\n        aura_env.stage = stage\n        local check = aura_env.STAGE[stage]\n        local now = GetTime()\n        if check then\n            for _, note in ipairs(conditionPhase) do\n                \n                WeakAuras.ScanEvents(\n                    \"MRT_NOTE_NEW\",\n                    now + note.time,\n                    note.line,\n                    stage,\n                    note.noteType\n                )\n                \n                --DebugPrint(\"New Phase Timer\", stage, note.line, note.time)\n            end\n        end\n    elseif event == \"ENCOUNTER_START\"\n    and (IsAddOnLoaded(\"ExRT\") or IsAddOnLoaded(\"MRT\"))\n    and ...\n    then\n        aura_env.stage = 1\n        aura_env.CLEU = {}\n        aura_env.STAGE = {}\n        aura_env.CLEUcounters = {}\n        aura_env.cleucheck = false\n        \n        local notes = {\n            aura_env.Note.Text1 or \"\",\n            aura_env.Note.SelfText or \"\",\n        }\n        \n        local spec = GetSpecialization and GetSpecialization()\n        local role, _\n        if spec then\n            _, spec, _, _, role, _ = GetSpecializationInfo(spec)\n        end\n        --DebugPrint(\"spec\", spec)\n        --DebugPrint(\"role\", role)\n        \n        local now = GetTime()\n        \n        for i = 1, 2 do\n            local text = notes[i]\n            \n            for line in text:gmatch(\"[^\\r\\n]+\") do\n                if spec then\n                    if role ~= \"HEALER\" then\n                        line = line:gsub(\"{[Hh]}.-{/[Hh]}\", \"\")\n                    end\n                    if role ~= \"TANK\" then\n                        line = line:gsub(\"{[Tt]}.-{/[Tt]}\", \"\")\n                    end\n                    if role ~= \"DAMAGER\" then\n                        line = line:gsub(\"{[Dd]}.-{/[Dd]}\", \"\")\n                    end\n                end\n                line = line:gsub(\"{(!?)[Gg](%d+)}(.-){/[Gg]}\", aura_env.GSUB_Group)\n                :gsub(\"{(!?)[Pp]:([^}]+)}(.-){/[Pp]}\", aura_env.GSUB_Player)\n                :gsub(\"{(!?)[Cc]:([^}]+)}(.-){/[Cc]}\", aura_env.GSUB_Class)\n                :gsub(\"{(!?)[Rr][Aa][Cc][Ee]:([^}]+)}(.-){/[Rr][Aa][Cc][Ee]}\", aura_env.GSUB_Race)\n                \n                local noteType = i == 1 and \"shared\" or \"personal\"\n                local minute, sec, options = line:match(\"{time:(%d+)[:%.]?(%d*),?([^{}]*)}\")\n                \n                if minute == nil and sec == nil then\n                    minute, sec = line:match(\"%((%d+)[:%.]?(%d*)%)\") -- support (mn:sec) or (sec)\n                end\n                \n                if sec == nil or sec == \"\" then\n                    sec = tonumber(minute)\n                    minute = 0\n                else\n                    minute = tonumber(minute)\n                    sec = tonumber(sec)\n                end\n                \n                if sec then\n                    local time = sec + (minute * 60)\n                    \n                    if options == nil or options == \"\" or options == \"p1\" then\n                        local stage = (options == \"p1\") and 1 or nil\n                        \n                        WeakAuras.ScanEvents(\n                            \"MRT_NOTE_NEW\",\n                            now + time,\n                            line,\n                            stage,\n                            noteType\n                        )\n                        \n                        --DebugPrint(\"Timer Sent\", time, stage, line)\n                    end\n                    if not (options == \"\") and options then\n                        local opt, spellID, count = strsplit(\":\", options)\n                        local stage = opt:match(\"^p([%d%.]+)$\")\n                        if stage then\n                            stage = tonumber(stage)\n                            aura_env.STAGE[stage] = aura_env.STAGE[stage] or {}\n                            table.insert(\n                                aura_env.STAGE[stage],\n                                {\n                                    time = time,\n                                    line = line,\n                                    noteType = noteType\n                                }\n                            )\n                            --DebugPrint(\"Timer programmed for stage\", stage, line, start)\n                        else\n                            spellID = tonumber(spellID)\n                            local subEvent = aura_env.shortEvent[opt]\n                            if subEvent and spellID then\n                                aura_env.cleucheck = true\n                                aura_env.CLEU[subEvent] = aura_env.CLEU[subEvent] or {}\n                                aura_env.CLEU[subEvent][spellID] = aura_env.CLEU[subEvent][spellID] or {}\n                                table.insert(\n                                    aura_env.CLEU[subEvent][spellID],\n                                    {\n                                        time = time,\n                                        line = line,\n                                        count = count,\n                                        noteType = noteType\n                                    }\n                                )\n                                aura_env.CLEUcounters[subEvent] = aura_env.CLEUcounters[subEvent] or {}\n                                aura_env.CLEUcounters[subEvent][spellID] = 0\n                                --DebugPrint(\"Timer programmed for CLEU\", subEvent, line, time, spellID, count)\n                            else\n                                --DebugPrint(\"Syntax not understood\", line)\n                            end\n                        end\n                    end\n                end\n            end\n        end\n    elseif event == \"ENCOUNTER_END\" then\n        aura_env.CLEU = {}\n        aura_env.STAGE = {}\n        aura_env.CLEUcounters = {}\n        aura_env.cleucheck = false\n    end\nend",
