["Stinging Swarm Dispel Assign & Glow"] = {
["outline"] = "OUTLINE",
["displayText_format_text_format"] = "none",
["wagoID"] = "foNlg79Ol",
["color"] = {
1,
1,
1,
1,
},
["displayText"] = "%pos",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["automaticWidth"] = "Auto",
["actions"] = {
["start"] = {
["glow_lines"] = 10,
["glow_thickness"] = 4,
["glow_action"] = "show",
["glow_frame_type"] = "UNITFRAME",
["glow_frequency"] = 0.4,
["custom"] = "\n\n",
["glow_border"] = false,
["use_glow_color"] = true,
["glow_color"] = {
0,
1,
1,
1,
},
["glow_type"] = "Pixel",
["do_custom"] = false,
["do_glow"] = false,
},
["init"] = {
["custom"] = "aura_env.debug = false\naura_env.debuff = aura_env.debug and 774 or 438708\naura_env.markred = aura_env.debug and 33763 or 455850\naura_env.markblue = aura_env.debug and 48438 or 455849\naura_env.cast = aura_env.debug and 8936 or 438677\naura_env.delay = aura_env.debug and 4 or 2 -- debuffs are actually very delayed after the cast so default delay is high\naura_env.filter = aura_env.debug and \"HELPFUL\" or \"HARMFUL\"\n\naura_env.MRT = function()\n    aura_env.list = {}\n    aura_env.found = false\n    if C_AddOns.IsAddOnLoaded(\"MRT\") and VMRT.Note.Text1 then\n        local text = _G.VMRT.Note.Text1\n        local list = false\n        text = text:gsub(\"||r\", \"\") -- clean colorcode\n        text = text:gsub(\"||c%x%x%x%x%x%x%x%x\", \"\") -- clean colorcode\n        aura_env.list = {}\n        for line in text:gmatch('[^\\r\\n]+') do\n            line = strtrim(line) --trim whitespace\n            --check for start/end of the name list\n            if strlower(line) == \"nsdispelstart\" then\n                aura_env.found = true\n                list = true\n            elseif strlower(line) == \"nsdispelend\" then\n                list = false\n            end\n            \n            if list then \n                line = line:gsub(\"{.-}\", \"\") -- cleaning markers from line\n                for name in line:gmatch(\"%S+\") do -- finding all remaining strings\n                    if NSAPI then\n                        --  name = NSAPI:GetChar(name)\n                    end\n                    if UnitInRaid(name) then\n                        table.insert(aura_env.list, name)\n                    else -- checking for nickname if string didn't match player\n                        for unit in WA_IterateGroupMembers() do\n                            local uname = UnitName(unit)\n                            if uname:match(name) then\n                                table.insert(aura_env.list, uname)\n                                break\n                            end\n                        end\n                    end\n                end\n            end\n        end\n    end\n    if not aura_env.found then -- auto assign if no note was provided\n        for unit in WA_IterateGroupMembers() do\n            if UnitGroupRolesAssigned(unit) == \"HEALER\" then\n                table.insert(aura_env.list, unit)\n            end\n        end\n    end  \nend\n\n\n\naura_env.spec = {\n    \n    -- Healers\n    [1468] = 1, -- Evoker: Preservation\n    [270]  = 2, -- Monk: Mistweaver\n    [105]  = 3, -- Druid: Restoration\n    [264]  = 4, -- Shaman: Restoration\n    [65]   = 5, -- Paladin: Holy\n    [256]  = 6, -- Priest: Discipline \n    [257]  = 7, -- Priest: Holy\n    \n    -- Tanks\n    [250]  =  8, -- Blood DK\n    [581]  =  9, -- Veng DH\n    [268]  =  10, -- Brewmaster\n    [66]   =  11, -- Prot Pally\n    [83]   =  12, -- Prot Warrior\n    [104]  =  13, -- Guardian Druid\n    \n    -- Melee\n    [577]  =  14, -- Demon Hunter: Havoc\n    [103]  =  15, -- Druid: Feral \n    [259]  =  16, -- Rogue: Assassination  \n    [260]  = 17, -- Rogue: Outlaw  \n    [261]  = 18, -- Rogue: Subtlety\n    [269]  = 19, -- Monk: Windwalker\n    [255]  = 20, -- Hunter: Survival\n    [70]   = 21, -- Paladin: Retribution\n    [71]   = 22, -- Warrior: Arms  \n    [72]   = 23, -- Warrior: Fury \n    [251]  = 24, -- Death Knight: Frost\n    [252]  = 25, -- Death Knight: Unholy\n    [263]  = 26, -- Shaman: Enhancement\n    \n    -- Ranged\n    [1467] = 27, -- Evoker: Devastation\n    [1473] = 28, -- Evoker: Augmentation\n    [253]  = 29, -- Hunter: Beast Mastery\n    [254]  = 30, -- Hunter: Marksmanship\n    [64]   = 31, -- Mage: Frost\n    [62]   = 32, -- Mage: Arcane\n    [63]   = 33, -- Mage: Fire\n    [102]  = 34, -- Druid: Balance\n    [262]  = 35, -- Shaman: Elemental \n    [258]  = 36, -- Priest: Shadow\n    [265]  = 37, -- Warlock: Affliction \n    [266]  = 38, -- Warlock: Demonology  \n    [267]  = 39, -- Warlock: Destruction\n    \n}",
["do_custom"] = true,
},
["finish"] = {
["hide_all_glows"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["customVariables"] = "{\n    glow = \"bool\",\n    ready = \"bool\",\n    unassigned = \"bool\",\n    pos = \"number\",\n}",
["event"] = "Health",
["unit"] = "player",
["custom_type"] = "stateupdate",
["subeventPrefix"] = "SPELL",
["custom"] = "function(s, e, ...) \n    if e == \"OPTIONS\" then\n        s[\"\"] = {\n            show = true,\n            unit = \"player\",\n            index = 1,\n            expirationTime = GetTime()+10,\n            duration = 10,\n            progressType = \"timed\",\n            changed = true\n            \n        }\n        return true\n        \n    elseif e == \"NSAPI_ENCOUNTER_START\" and ... then\n        aura_env.specs = NSAPI:GetSpecs()\n        aura_env.affected = {}\n        aura_env.assigned = false\n        aura_env.healers = {}\n        aura_env.MRT()\n        \n        \n    elseif e == \"NS_ASSIGN_EVENT\" and ... and aura_env.id == ... then\n        aura_env.assigned = true\n        \n        \n        aura_env.affected = {}\n        for unit in WA_IterateGroupMembers() do -- cover debuffs that are leftover from the past somehow\n            if WA_GetUnitAura(unit, aura_env.debuff, aura_env.filter) then\n                local G = UnitGUID(unit)\n                local spec = (aura_env.specs and aura_env.specs[unit]) or (NSAPI and NSAPI:GetSpecs(unit)) or WeakAuras.SpecForUnit(unit)\n                local prio = spec and aura_env.spec and aura_env.spec[spec] or 0\n                local mark = (WA_GetUnitAura(unit, aura_env.markred, aura_env.filter) and 1) or (WA_GetUnitAura(unit, aura_env.markblue, aura_env.filter) and 2) or 0\n                if prio == 0 then\n                    print(\"no spec information found for:\", WA_ClassColorName(destName), \"You should probably reload/relog, can also be caused by ignore list.\")\n                    table.insert(aura_env.affected, {unit, G, prio, mark})                    \n                else\n                    table.insert(aura_env.affected, {unit, G, prio, mark})\n                end\n            end\n        end\n        -- sort marks\n        \n        table.sort(aura_env.affected, \n            function(a, b)\n                if a[4] == b[4] then -- only sort within same color\n                    if a[3] == b[3] then -- sort by GUID if same spec\n                        return a[2] < b[2]\n                    else\n                        return a[3] < b[3]\n                    end\n                else\n                    return a[4] > b[4] -- always do blue first because of last dispel in p3\n                end\n                \n        end) -- a < b low first, a > b high first\n        aura_env.tbl = {}\n        \n        for i, v in ipairs(aura_env.list) do\n            if not (UnitIsDead(v)) then\n                table.insert(aura_env.tbl, {v, true}) -- unitid, \"available\"\n            end     \n        end\n        local ignore = {}\n        \n        \n        -- this used to be self assign for healers but had to be scrapped for mythic because of double assigns. It would cause difficult to solve issues to always have the same healer assigned to #1 and #5\n        --[[\n        for i, v in ipairs(aura_env.affected) do\n            if UnitGroupRolesAssigned(v[1]) == \"HEALER\" then  \n                local G = v[2]  \n                s[G] = {\n                    show = true,\n                    progressType = \"static\",\n                    unit = v[1],\n                    pos = i, \n                    unassigned = false,\n                    glow = UnitIsUnit(\"player\", v[1]),\n                    assigned = 0,\n                    ready = false,\n                    autoHide = false,\n                    changed = true,\n                }\n                WeakAuras.ScanEvents(\"NS_SWARM_LIST\", i, v[1], v[1])\n                ignore[i] = true -- instead of deleting from table we set it to ignore later, makes it easier to keep the number order right\n                if UnitIsUnit(v[1], \"player\") then\n                    WeakAuras.ScanEvents(\"NS_COURT_DISPEL_ME\", i) -- display dispel number\n                end\n                for num, tbl in ipairs(aura_env.tbl) do -- mark healer as assigned\n                    if UnitIsUnit(tbl[1], v[1]) then    \n                        aura_env.tbl[num][2] = false\n                        s[G].assigned = num  \n                        break\n                    end\n                end\n            end\n        end\n        ]]\n        \n        -- double assign healer if there are more debuffs than healers (should always be the case unless guilds 5heal it at some point)\n        if #aura_env.affected > #aura_env.tbl then \n            for i, v in ipairs(aura_env.tbl) do\n                table.insert(aura_env.tbl, {v[1], true})\n                if #aura_env.tbl >= #aura_env.affected then\n                    break\n                end\n            end\n        end\n        \n        for i, v in ipairs(aura_env.tbl) do\n            if v[2] then\n                for num, list in ipairs(aura_env.affected) do\n                    if not ignore[num] then\n                        ignore[num] = true \n                        aura_env.tbl[num][2] = false                     \n                        s[list[2]] = {\n                            show = true,\n                            progressType = \"static\",\n                            unit = list[1],\n                            pos = num, -- dispel order\n                            unassigned = false, -- if no specific healer is assigned\n                            glow = UnitIsUnit(\"player\", v[1]),\n                            assigned = i, -- position in healer table\n                            ready = false, -- ready to be dispelled, communicated through macro\n                            autoHide = false,\n                            changed = true,\n                        }\n                        WeakAuras.ScanEvents(\"NS_SWARM_LIST\", num, list[1], v[1])\n                        if UnitIsUnit(list[1], \"player\") then\n                            WeakAuras.ScanEvents(\"NS_COURT_DISPEL_ME\", num)\n                            WeakAuras.ScanEvents(\"NS_MACRO_PRESS_PERSONAL\", 2) -- display text to remind for macro press\n                        end\n                        break\n                    end\n                end\n            end\n        end\n        return true  \n        \n        \n    elseif (e == \"NS_PA_MACRO\" or e == \"LIQUID_PRIVATE_AURA_MACRO\") and ... then\n        if not aura_env.last3 or aura_env.last3 < GetTime() - 2 then -- macro throttle\n            aura_env.last3 = GetTime()\n            local G = UnitGUID(\"player\")\n            if s[G] and s[G].ready then return -- prevents from sending if state already exists for that player\n            else\n                NSAPI:Broadcast(\"NS_COURT_DISPEL\", \"RAID\", \"nilcheck\") \n                WeakAuras.ScanEvents(\"NS_MACRO_PRESS_PERSONAL\", 1) -- display text indicating that macro has been pressed\n                if aura_env.debug then WeakAuras.ScanEvents(\"NS_COURT_DISPEL\", \"player\") end\n            end\n        end       \n    elseif e == \"NS_COURT_DISPEL\" then\n        local unit = ...        \n        if UnitExists(unit) and UnitIsVisible(unit) then \n            WeakAuras.ScanEvents(\"NSAPI_MACRO_RECEIVE\", unit) -- sends information to NS aura to debug macro press\n            local G = UnitGUID(unit)\n            if s[G] then\n                s[G].ready = true\n                s[G].changed = true\n                WeakAuras.ScanEvents(\"NS_SWARM_LIST_READY\", G)\n                return true\n            else\n                if WA_GetUnitAura(unit, aura_env.debuff, aura_env.filter) then\n                    s[G] = {\n                        show = true,\n                        progressType = \"static\",\n                        unit = unit,\n                        pos = 0,\n                        glow = false,\n                        ready = true,\n                        assigned = 0,\n                        unassigned = true,\n                        autoHide = false,\n                        changed = true,\n                    }\n                    for i, v in ipairs(aura_env.tbl) do -- try to assign a healer that isn't currently assigned\n                        if v[2] then\n                            aura_env.tbl[i][2] = false\n                            if UnitIsUnit(\"player\", v[1]) then\n                                s[G].glow = true\n                            end\n                            s[G].unassigned = false\n                            s[G].assigned = i\n                            s[G].changed = true\n                            WeakAuras.ScanEvents(\"NS_SWARM_LIST\", 0, unit, v[1])\n                            WeakAuras.ScanEvents(\"NS_SWARM_LIST_READY\", G)\n                            break                            \n                        end\n                    end\n                end\n                return true\n            end\n            \n        end\n        \n    elseif e == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local timestamp, subevent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID = ... -- full CLEU\n        if spellID == aura_env.cast and subevent == \"SPELL_CAST_SUCCESS\" then\n            local now = GetTime()\n            if not aura_env.last or aura_env.last < now - 8 then\n                aura_env.assigned = false\n                aura_env.last = now\n                local aura_env = aura_env\n                WeakAuras.ScanEvents(\"NS_COURT_DISPEL_ME\", 0) -- fallback hide text if it somehow bugs out\n                WeakAuras.ScanEvents(\"NS_MACRO_PRESS_PERSONAL\", 3) -- fallback hide macro text\n                C_Timer.After(aura_env.delay, function()\n                        WeakAuras.ScanEvents(\"NS_ASSIGN_EVENT\", aura_env.id)\n                end)\n            end\n            \n        elseif spellID == aura_env.debuff then\n            if subevent == \"SPELL_AURA_APPLIED\" and aura_env.assigned then\n                local i = UnitInRaid(destName)\n                local unit = i and \"raid\"..i       \n                if unit and UnitExists(unit) then\n                    local G = destGUID or UnitGUID(unit)\n                    local spec = (aura_env.specs and aura_env.specs[unit]) or (NSAPI and NSAPI:GetSpecs(unit)) or WeakAuras.SpecForUnit(unit)\n                    local prio = spec and aura_env.spec and aura_env.spec[spec] or 0\n                    local mark = (WA_GetUnitAura(unit, aura_env.markred, aura_env.filter) and 1) or (WA_GetUnitAura(unit, aura_env.markblue, aura_env.filter) and 2) or 0\n                    if prio == 0 then\n                        print(\"no spec information found for:\", WA_ClassColorName(destName), \"You should probably reload/relog, can also be caused by ignore list.\")\n                        table.insert(aura_env.affected, {unit, G, prio, mark})                    \n                    else\n                        table.insert(aura_env.affected, {unit, G, prio, mark})\n                    end\n                    s[G] = {\n                        show = true,\n                        progressType = \"static\",\n                        unit = unit,\n                        pos = #aura_env.affected,\n                        glow = false,\n                        ready = false,\n                        unassigned = true,\n                        autoHide = false,\n                        changed = true,\n                    }\n                    WeakAuras.ScanEvents(\"NS_SWARM_LIST\", 0, unit, \"\")\n                    local macro = true\n                    --[[\n                        if UnitGroupRolesAssigned(unit) == \"HEALER\" then -- try to self assign a healer first before finding others\n                            for j, v in ipairs(aura_env.tbl) do \n                                if v[2] and UnitIsUnit(unit, v[1]) then\n                                    aura_env.tbl[j][2] = false                                \n                                    if UnitIsUnit(\"player\", v[1]) then\n                                        s[G].glow = true\n                                    end\n                                    macro = false\n                                    s[G].unassigned = false\n                                    s[G].assigned = j\n                                    s[G].changed = true\n                                    WeakAuras.ScanEvents(\"NS_SWARM_LIST\", 0, unit, v[1])\n                                    break\n                                end\n                            end                            \n                end]]\n                    if s[G].unassigned then\n                        local assigned = false\n                        local num = #aura_env.list >= 5 and 1 or 2 -- if there are 5 healers in the note, the guild is 5 healing (or they ignored wago instructions but then I don't care) which means we can start with the 1st healer. Otherwise we start with the 2nd healer because the first healer will also be doing the 5th dispel so they won't have it ready for any debuff that jumped to a new target\n                        for j= num, #aura_env.tbl do \n                            local v = aura_env.tbl[j]\n                            if v[2] then\n                                aura_env.tbl[j][2] = false                                \n                                if UnitIsUnit(\"player\", v[1]) then\n                                    s[G].glow = true\n                                end\n                                s[G].unassigned = false\n                                s[G].assigned = j\n                                s[G].changed = true\n                                WeakAuras.ScanEvents(\"NS_SWARM_LIST\", #aura_env.affected, unit, v[1])\n                                assigned = true\n                                break\n                            end\n                        end   \n                        if not assigned then -- if we still haven't found a valid healer, the best chance is to just select the 2nd healer from the list(or 1st if 5healing)\n                            local v = aura_env.tbl[num]                        \n                            if UnitIsUnit(\"player\", v[1]) then\n                                s[G].glow = true\n                            end\n                            s[G].unassigned = false\n                            s[G].assigned = num\n                            s[G].changed = true\n                            WeakAuras.ScanEvents(\"NS_SWARM_LIST\", #aura_env.affected, unit, v[1])                            \n                        end                         \n                    end\n                    \n                    if UnitIsUnit(unit, \"player\") then\n                        WeakAuras.ScanEvents(\"NS_COURT_DISPEL_ME\", #aura_env.affected)                            \n                        if UnitGroupRolesAssigned(\"player\") ~= \"HEALER\" or macro then\n                            WeakAuras.ScanEvents(\"NS_MACRO_PRESS_PERSONAL\", 2) -- display text to remind for macro press\n                        end\n                    end\n                    return true\n                end\n            elseif subevent == \"SPELL_AURA_REMOVED\" and s[destGUID] then\n                if UnitIsUnit(destName, \"player\") then\n                    WeakAuras.ScanEvents(\"NS_COURT_DISPEL_ME\", 0) -- hide text display player\n                    WeakAuras.ScanEvents(\"NS_MACRO_PRESS_PERSONAL\", 3) -- hide macro display\n                end\n                if aura_env.tbl[s[destGUID].assigned] then -- mark healer as available again when debuff was removed\n                    aura_env.tbl[s[destGUID].assigned][2] = true \n                end\n                s[destGUID].show = false\n                s[destGUID].changed = true\n                for i, v in ipairs(aura_env.affected) do -- delete unit from affected table\n                    if UnitIsUnit(v[1], destName) then\n                        table.remove(aura_env.affected, i)\n                        break\n                    end\n                end                \n                \n                \n                for i, v in ipairs(aura_env.affected) do -- if state exists for unit from affected table, assign updated position to them. This should allow handling situations where debuffs are dispelled outside the assigned order\n                    if s[v[2]] then\n                        s[v[2]].pos = i\n                        s[v[2]].changed = true\n                        if UnitIsUnit(v[1], \"player\") then\n                            WeakAuras.ScanEvents(\"NS_COURT_DISPEL_ME\", i)\n                        end\n                        WeakAuras.ScanEvents(\"NS_SWARM_LIST\", i, v[1], aura_env.tbl[s[v[2]].assigned][1])\n                    end\n                end              \n                return true\n            end\n        end\n    end\nend",
