["events"] = "ENCOUNTER_START CLEU:SPELL_AURA_APPLIED:SPELL_AURA_APPLIED_DOSE:SPELL_CAST_START:SPELL_CAST_SUCCESS",
["subeventSuffix"] = "",
["check"] = "event",
["subeventPrefix"] = "",
["custom"] = "function(s, e, ...)\n    if e == \"ENCOUNTER_START\" then\n        aura_env.count = 0\n    elseif e == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local timestamp, subevent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID = ... -- full CLEU\n        if (subevent == \"SPELL_AURA_APPLIED\" or subevent == \"SPELL_AURA_APPLIED_DOSE\") and spellID == aura_env.debuff then\n            aura_env.count = aura_env.count and aura_env.count+1 or 1\n        elseif subevent == \"SPELL_CAST_START\" and spellID == aura_env.cast then\n            s[\"\"] = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                duration = 5,\n                expirationTime = 5+GetTime(),\n                count = aura_env.count,\n                autoHide = true,\n            }\n            aura_env.count = 0\n            return true\n        elseif subevent == \"SPELL_CAST_SUCCESS\" and spellID == 459273 then\n            aura_env.count = aura_env.count-1\n            if aura_env.count < 0 then aura_env.count = 0 end\n        end\n    end\nend",
