["customGrow"] = "function(pos, reg)\n    aura_env.anchorData = aura_env.anchorData or WeakAuras.GetData(\"Tank Debuffs Anchor\")\n    \n    if aura_env.anchorData then\n        local anchorData = aura_env.anchorData\n        local grow = anchorData.grow\n        local xdirection = (grow == \"RIGHT\" and 1) or (grow == \"LEFT\" and -1) or 0\n        local ydirection = (grow == \"UP\" and 1) or (grow == \"DOWN\" and -1) or 0\n        local space = anchorData.space\n        local xoffset = 0\n        local yoffset = 0\n        local max = anchorData.limit\n        max = #reg <= max and #reg or max\n        for i =1, max do\n            pos[i] = {\n                xoffset,\n                yoffset,\n            }\n            xoffset = xoffset+((reg[i].region.width+space)*xdirection)\n            yoffset = yoffset+((reg[i].region.height+space)*ydirection)\n        end\n    else\n        local xoffset = 0    \n        for i =1, #reg do\n            pos[i] = {\n                xoffset,\n                0\n            }\n            xoffset = xoffset+reg[i].region.width-1\n        end\n    end\nend\n\n\n\n\n\n\n",
