["custom"] = "function(s, e, ...)\n    if e == \"OPTIONS\" then\n        s[\"\"] = {\n            show = true,\n            progressType = \"static\",\n            number = math.random(1, 4),\n            autoHide = true,\n            changed = true,\n        }\n    else\n        local num, type, duration, status, _, number = ...\n        if e == \"NS_OVINAX_EGG\" and num == aura_env.num  and status ~= 1 then\n            s[\"\"] = {\n                show = true,\n                duration = duration,\n                progressType = \"timed\",\n                expirationTime = GetTime()+duration,\n                number = number,\n                autoHide = true,\n                type = type,\n                status = status,\n                changed = true,\n            }\n            return true\n        elseif e == \"NS_OVINAX_HIDE\" and s[\"\"] then\n            s[\"\"].show = false\n            s[\"\"].changed = true\n            return true \n        elseif e == \"NS_OVINAX_EGGDUR\" and s[\"\"] then\n            local dur, expires = ...\n            if dur then\n                s[\"\"].duration = dur\n                s[\"\"].expirationTime = expires\n                s[\"\"].changed = true\n                return true\n            end\n        end\n    end\nend",
