["init"] = {
["custom"] = "aura_env.baseHealPercentage = GetSpecialization() == 1 and 0.25 or 0.4\naura_env.minimumHealPercentage = GetSpecialization() == 1 and 0.07 or 0.105\n\naura_env.excludedSpellIds = { 240443, -- Burst (Bursting)\n    240559, -- Grievous Wound (Grievous)\n    209858, -- Necrotic Wound (Necrotic)\n    240447, -- Quake (Quaking)\n    315161 -- Eye of Corruption\n}\n\naura_env.debugMode = false\naura_env.displayDebugMode = false\naura_env.debugString = ''\n\naura_env.trackingTime = 5\naura_env.damageEvents = {}\naura_env.totalDamage = 0\naura_env.healAmount = 0\naura_env.expectedHealRaw = 0\naura_env.expectedHealPercentage = 0\naura_env.outputColourEscape = 'FFFFFFFF'\naura_env.output = ''\n\nlocal function formatOutput(output)\n    if output >= 10^6 then\n        return string.format('%M', output / 10^6)\n    elseif output >= 10^3 then\n        return string.format('%K', output / 10^3)\n    else\n        return string.format('%d', output)\n    end    \nend\n\nlocal function convertRgbaToHexEscape(rgbaColourTable)\n    local r = rgbaColourTable[1] > 0 and string.format('%x', rgbaColourTable[1] * 255) or '00'\n    local g = rgbaColourTable[2] > 0 and string.format('%x', rgbaColourTable[2] * 255) or '00'\n    local b = rgbaColourTable[3] > 0 and string.format('%x', rgbaColourTable[3] * 255) or '00'\n    local a = 'ff'\n    return string.format('%s%s%s%s', a, r, g, b)\nend\n\nlocal function getTooltipValues(spellId)\n    local desc = GetSpellDescription(spellId)\n    local values = {}\n    \n    for t in desc:gmatch(\"(%d[%d%.,]*)\") do\n        if (LARGE_NUMBER_SEPERATOR == \",\") then\n            t = t:gsub(\",\", \"\")\n        else\n            t = t:gsub(\"%.\", \"\")\n            t = t:gsub(\",\", \".\")\n        end\n        \n        tinsert(values, tonumber(t))\n    end\n    \n    return #values > 0 and values or nil\nend\n\nfunction aura_env:updateOutput()\n    \n    aura_env.debugString = ''\n    local totalDamage = 0\n    \n    for _, event in ipairs(aura_env.damageEvents) do\n        totalDamage = totalDamage + event.damage\n    end\n    \n    local deathStrikeTooltipValues = getTooltipValues(49998)\n    local tooltipIndexBase = 2\n    local tooltipIndexMin = 4\n    local locale = GetLocale()\n    \n    if locale == \"koKR\" or locale == \"zhCN\" or locale == \"zhTW\" then\n        tooltipIndexBase = 3\n        tooltipIndexMin = 4\n    end\n    \n    if deathStrikeTooltipValues then\n        aura_env.baseHealPercentage = deathStrikeTooltipValues[tooltipIndexBase] / 100\n        -- The in-game minimum heal currently has rounding errors and is based on the nearest percent, rounded down.\n        aura_env.minimumHealPercentage = math.floor(deathStrikeTooltipValues[tooltipIndexMin]) / 100\n    end  \n    \n    \n    -- Insatiable Appetite and Voracious changes are calculated above directly from the tooltip information.\n    -- Keeping this here for future reference.\n    --[[\n\n    local insatiableAppetite = C_Soulbinds.IsConduitInstalledInSoulbind(C_Soulbinds.GetActiveSoulbindID(), 108)\n    local iaBonus = 0\n    if insatiableAppetite then\n        local iaRank = C_Soulbinds.GetConduitRank(108)\n        iaBonus = 0.01 + (((iaRank - 1) * 0.1) / 100)\n    end\n\n    local voracious = (GetSpecialization() == 1 and ({GetTalentInfoBySpecialization(GetSpecialization(), 6, 1)})[4] == true)\n    if voracious then\n        aura_env.debugString = aura_env.debugString .. 'voracious'\n        aura_env.baseHealPercentage = 0.3\n        if insatiableAppetite then\n            aura_env.minimumHealPercentage = (0.07 + iaBonus) * 1.5\n        else            \n            aura_env.minimumHealPercentage = 0.10\n        end\n    end \n  \n    --]]    \n    \n    local baseHeal = totalDamage * aura_env.baseHealPercentage\n    local minimumHeal = UnitHealthMax(\"player\") * aura_env.minimumHealPercentage\n    \n    local healAmount = math.max(baseHeal, minimumHeal)\n    \n    ---- Positive effects\n    \n    -- Vampiric Blood\n    \n    local vampiricBlood = WA_GetUnitBuff(\"player\", 55233)\n    local vampiricBloodBonus = UnitLevel('player') >= 56 and 0.35 or 0.3\n    if vampiricBlood then\n        healAmount = healAmount * (1 + vampiricBloodBonus)\n    end\n    \n    -- Guardian Spirit\n    \n    local guardianSpirit = WA_GetUnitBuff(\"player\", 47788)\n    local guardianSpiritBonus = 0.6\n    if guardianSpirit then\n        healAmount = healAmount * (1 + guardianSpiritBonus)\n    end\n    \n    -- Hemostasis\n    \n    local hemostasisStacks = select(3, WA_GetUnitBuff(\"player\", 273947))\n    local hemostasisBonus = 0.08\n    if hemostasisStacks then\n        healAmount = healAmount * (1 + (hemostasisStacks * hemostasisBonus))\n    end\n    \n    -- Versatility\n    \n    local versatilityPercent = GetCombatRatingBonus(29)\n    local versatilityBonus = versatilityPercent / 100\n    if versatilityPercent then\n        healAmount = healAmount * (1 + versatilityBonus)\n    end\n    \n    -- Hold Your Ground\n    \n    local holdYourGround = WA_GetUnitBuff(\"player\", 333089)\n    local holdYourGroundBonus = 0.04\n    if holdYourGround then\n        healAmount = healAmount * (1 + holdYourGroundBonus)\n    end\n    \n    -- Battlefield Presence\n    local battlefieldPresenceStacks = select(3, WA_GetUnitBuff(\"player\", 352858))\n    local battlefieldPresenceBonus = 0.01\n    if battlefieldPresenceStacks then\n        healAmount = healAmount * (1 + (battlefieldPresenceStacks * battlefieldPresenceBonus))\n    end\n    \n    -- Dark Succor\n    \n    local darkSuccor = WA_GetUnitBuff(\"player\", 101568)\n    if darkSuccor then\n        healAmount = healAmount + (UnitHealthMax(\"player\") * 0.10)        \n    end\n    \n    \n    ---- Negative effects\n    \n    --[[ Necrotic Wound\n    \n    local necroticWoundStacks = select(3, WA_GetUnitDebuff(\"player\", 209858))\n    local necroticWoundReduction = 0.02\n    if necroticWoundStacks then\n        healAmount = healAmount * (1 - (necroticWoundStacks * necroticWoundReduction))\n    end    \n\n    --]]\n    \n    healAmount = math.max(1, healAmount)\n    \n    aura_env.expectedHealRaw = healAmount\n    aura_env.expectedHealPercentage = (healAmount * 100) / UnitHealthMax(\"player\")\n    aura_env.totalDamage = totalDamage\n    \n    aura_env.output = string.format('%.0f%%', aura_env.expectedHealPercentage) \n    \n    \nend",
["do_custom"] = true,
},
},
