["debuffType"] = "HELPFUL",
["custom"] = "function(event, timestamp, subevent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, ...)\n    \n    if aura_env.debugMode and sourceGUID == UnitGUID(\"player\") then\n        if subevent == 'SPELL_HEAL' then\n            local spellName = select(2, ...)\n            if spellName == 'Death Strike' then\n                local amount = select(4, ...) or 0\n                local overhealing = select(5, ...) or 0\n                local absorbed = select(6, ...) or 0\n                print(string.format('\\nDeath Strike Tracker Debug:\\n- Expected Heal: %s\\n\\n- Actual Heal: %s\\n- Overhealing: %s\\n- Absorbed: %s\\n', aura_env.expectedHealRaw, amount, overhealing, absorbed))\n            end\n        end\n    end\n    \n    if destGUID == UnitGUID(\"player\") then\n        if not subevent:find(\"ENVIRONMENTAL\") and (subevent:find(\"DAMAGE\") or subevent:find(\"MISSED\")) then\n            local damageTime = GetTime()\n            local damageTaken = nil\n            if subevent:find(\"DAMAGE\") and not subevent:find(\"DURABILITY\") then\n                if not subevent:find(\"SWING\") then\n                    local spellId = select(1, ...)\n                    if not tContains(aura_env.excludedSpellIds, spellId) then\n                        damageTaken = select(4, ...)\n                        if select(9, ...) ~= nil then\n                            damageTaken = damageTaken + select(9, ...)\n                        end\n                    end\n                else\n                    damageTaken = select(1, ...)\n                    if select(6, ...) ~= nil then\n                        damageTaken = damageTaken + select(6, ...)\n                    end\n                end\n            elseif subevent:find(\"MISSED\") and select(4, ...) == 'ABSORB' then\n                if not subevent:find(\"SWING\") then\n                    local spellId = select(1, ...)\n                    if not tContains(aura_env.excludedSpellIds, spellId) then\n                        damageTaken = select(6, ...)\n                    end\n                else\n                    damageTaken = select(3, ...)\n                end\n            end\n            if damageTaken ~= nil then\n                tinsert(aura_env.damageEvents, {['time'] = damageTime, ['damage'] = damageTaken})\n                WeakAuras.ScanEvents(\"DEATH_STRIKE_TRACKER_DAMAGE_ENTERED\")\n                C_Timer.After(aura_env.trackingTime, function() WeakAuras.ScanEvents(\"DEATH_STRIKE_TRACKER_DAMAGE_EXPIRED\") end)\n            end\n        end\n    end\nend",
