    [\"{Shaman}\"] = \"|TInterface\\\\GLUES\\\\CHARACTERCREATE\\\\UI-CHARACTERCREATE-CLASSES:16:16:0:0:256:256:64:127:64:128|t\",\n    [\"{\" .. GetClassInfo(8) .. \"}\"] = \"|TInterface\\\\GLUES\\\\CHARACTERCREATE\\\\UI-CHARACTERCREATE-CLASSES:16:16:0:0:256:256:64:127:0:64|t\",\n    [\"{Mage}\"] = \"|TInterface\\\\GLUES\\\\CHARACTERCREATE\\\\UI-CHARACTERCREATE-CLASSES:16:16:0:0:256:256:64:127:0:64|t\",\n    [\"{\" .. GetClassInfo(9) .. \"}\"] = \"|TInterface\\\\GLUES\\\\CHARACTERCREATE\\\\UI-CHARACTERCREATE-CLASSES:16:16:0:0:256:256:190:253:64:128|t\",\n    [\"{Warlock}\"] = \"|TInterface\\\\GLUES\\\\CHARACTERCREATE\\\\UI-CHARACTERCREATE-CLASSES:16:16:0:0:256:256:190:253:64:128|t\",\n    [\"{Monk}\"] = \"|TInterface\\\\GLUES\\\\CHARACTERCREATE\\\\UI-CHARACTERCREATE-CLASSES:16:16:0:0:256:256:128:189:128:192|t\",\n    [\"{\" .. GetClassInfo(11) .. \"}\"] = \"|TInterface\\\\GLUES\\\\CHARACTERCREATE\\\\UI-CHARACTERCREATE-CLASSES:16:16:0:0:256:256:190:253:0:64|t\",\n    [\"{Druid}\"] = \"|TInterface\\\\GLUES\\\\CHARACTERCREATE\\\\UI-CHARACTERCREATE-CLASSES:16:16:0:0:256:256:190:253:0:64|t\",\n    [\"{Demon Hunter}\"] = \"|TInterface\\\\GLUES\\\\CHARACTERCREATE\\\\UI-CHARACTERCREATE-CLASSES:16:16:0:0:256:256:190:253:128:192|t\",\n}\n\nif WeakAuras.IsRetail() then\n    aura_env.localERTIcons[\"{\" .. GetClassInfo(10) .. \"}\"] = \"|TInterface\\\\GLUES\\\\CHARACTERCREATE\\\\UI-CHARACTERCREATE-CLASSES:16:16:0:0:256:256:128:189:128:192|t\"\n    aura_env.localERTIcons[\"{\" .. GetClassInfo(12) .. \"}\"] = \"|TInterface\\\\GLUES\\\\CHARACTERCREATE\\\\UI-CHARACTERCREATE-CLASSES:16:16:0:0:256:256:190:253:128:192|t\"\nend\n\nlocal function GSUB_Icons(txt)\n    local r = aura_env.localERTIcons[\"{\"..txt..\"}\"]\n    return r or txt\nend\n\naura_env.format = function(line)\n    local formated = line:gsub(\"||c\", \"|c\"):\n    gsub(\"||r\", \"|r\"):\n    gsub(\"{spell:(%d+)}\", aura_env.GSUB_Icon):\n    gsub(\"{time:([0-9:]+)}\", \"%1\"):\n    gsub(\"{time:([0-9:]+),p(%d+)}\", \"P%2 %1\"):\n    gsub(\"{time:([0-9:]+),(%w+):(%d+):([^}]*)}\",  function(time, opt, spellID, count)\n            return (\"%s %s (%s) %s\"):format(opt, aura_env.GSUB_Icon(spellID), count, time)\n    end):\n    gsub(\"{!?p:[^}]+}(.+){/p}\", \"%1\"):\n    gsub(\"{!?g%d+}(.+){/g}\", \"%1\"):\n    gsub(\"{!?c:[^}]+}(.+){/c}\", \"%1\"):\n    gsub(\"{D}(.-){/D}\", \"%1\"):\n    gsub(\"{H}(.-){/H}\", \"%1\"):\n    gsub(\"{T}(.-){/T}\", \"%1\"):\n    gsub(\"{(.-)}\", GSUB_Icons)\n    return formated \nend\n\naura_env.MyGroup = function()\n    local myGroup = 1\n    if IsInRaid() then\n        for i = 1, GetNumGroupMembers() do\n            local name, _, subgroup = GetRaidRosterInfo(i)\n            if name == WeakAuras.me then\n                myGroup = subgroup\n                break\n            end\n        end\n    end\n    return tostring(myGroup)\nend\n\nfunction aura_env.isFiltered(line, noteType)\n    local lineLower = line:lower()\n    -- nop out if ignore keyword\n    for k in pairs(aura_env.ignoreKeyword) do\n        if lineLower:match(k:lower()) then\n            return true\n        end\n    end\n    \n    -- nop out if there is no yes word & we show only lines with one (onlyOwn)\n    local keywordFound = false\n    for k in pairs(aura_env.keyword) do\n        if lineLower:match(k:lower()) then\n            keywordFound = true\n            break\n        end\n    end\n    \n    if not (\n        keywordFound\n        or (not aura_env.config.onlyOwnShared and noteType == \"shared\")\n        or (not aura_env.config.onlyOwnPersonal and noteType == \"personal\")\n    )\n    then\n        return true\n    end\n    return false\nend\n\n\n",
