["events"] = "NSAPI_ENCOUNTER_START CLEU:SPELL_CAST_START:SPELL_AURA_APPLIED NS_VORTEX_HIDE",
["custom"] = "function(s, e, ...)\n    if e == \"OPTIONS\" then\n        s[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 2,\n            expirationTime = GetTime() + 2,\n            count = 1,\n            text = \"Through Boss & |cFFEE4B2BBREAK|r\",\n            autoHide = true\n        }\n    elseif e == \"NSAPI_ENCOUNTER_START\" then\n        aura_env.count = 0\n        aura_env.casts = 0\n    elseif e == \"NS_VORTEX_HIDE\" and ... and s[\"\"] and aura_env.id == ... then\n        s[\"\"].show = false\n        s[\"\"].changed = true\n        return true\n    else \n        local timestamp, subevent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID = ... -- full CLEU\n        \n        if subevent == \"SPELL_AURA_APPLIED\" and spellID == 441788 and UnitIsUnit(\"player\", destName) then\n            local blue = WA_GetUnitDebuff(\"player\", 455849)\n            local text = \"\"\n            if blue then\n                text = aura_env.count == 2 and \"Through Boss\" or \"Left/Right\"\n            else\n                if aura_env.count == 2 then\n                    if aura_env.casts == 6 or aura_env.casts == 10 then\n                        text = \"Through Boss & |cFF7CFC00KEEP|r\"\n                    else\n                        text = \"Through Boss & |cFFEE4B2BBREAK|r\"\n                    end\n                elseif aura_env.casts == 5 or aura_env.casts == 9 then\n                    text = \"Right & |cFF7CFC00KEEP|r\"\n                else\n                    text = \"Left/Right\"\n                end\n            end\n            \n            s[\"\"] = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                duration = 2,\n                expirationTime = GetTime() + 2,\n                count = aura_env.count,\n                text = text,\n                autoHide = false,\n            }            \n            -- wanna keep the text on screen a bit longer than the cast is but timer should be gone at that point\n            local aura_env = aura_env\n            C_Timer.After(4, function()\n                    WeakAuras.ScanEvents(\"NS_VORTEX_HIDE\", aura_env.id)\n            end)\n            return true\n        elseif subevent == \"SPELL_CAST_START\" and spellID == 441626 then  -- cast always happens before debuff applies\n            aura_env.casts = aura_env.casts+1\n            aura_env.count = aura_env.count + 1            \n            if aura_env.count >= 3 then\n                aura_env.count = 1\n            end\n        end\n    end    \nend",
