["displayText"] = "%c",
["customText"] = "function()\n    if aura_env.duration and aura_env.duration > 0 then\n        local damage = aura_env.amount or 0\n        local damageString\n        damageString = string.format(\"%.2f\", (damage / 1000))..\"K\"\n        aura_env.amount = 0\n        return \"Breath Ended\\nDamage: |cFF00FF00\"..damageString..\"|r\\nDuration: |cFFFFFF00\"..string.format(\"%.2f\", aura_env.duration)..\"|r\"\n    end\n    return \"\"\nend",
