["custom"] = "function(event, ...)\n    if event == \"WA_DK_BREATH_OF_SINDRAGOSA_END\" then\n        aura_env.duration = select(1, ...)\n        return true\n    else\n        local type = select(2, ...)\n        if type == \"SPELL_DAMAGE\" then\n            local spellId, _, _, amount = select(12, ...)\n            if spellId == 155166 then\n                aura_env.amount = (aura_env.amount or 0) + amount\n            end\n        elseif type == \"SPELL_ABSORBED\" then\n            local spellId, _, _, _, _, _, _, _, _, _, amount = select(12, ...)\n            if spellId == 155166 then\n                aura_env.amount = (aura_env.amount or 0) + amount\n            end\n        end\n    end\n    return false\nend",
