{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["event"] = "GTFO",
["unit"] = "player",
["debuffType"] = "HELPFUL",
["custom"] = "function(event, ...)\n    local arg1, arg2 = ...\n    \n    --print(event, ...)\n    \n    if \"OPTIONS\" == event or \"LWA_OPTIONS\" == event or (\"LWA_INIT\" == event and arg1) then\n        aura_env.ThrottledInit()\n        \n    elseif \"LWA_INIT\" == event then\n        aura_env.Init()\n        \n    elseif \"PLAYER_ENTERING_WORLD\" == event and (arg1 or arg2) then\n        aura_env.ThrottledInit()\n        \n        C_Timer.After(1, function()\n                WeakAuras.ScanEvents(\"LWA_INIT\", true)\n        end)\n    elseif \"LWA_UPDATE_BAR\" == event and arg1 then\n        aura_env.UpdateBar(...)\n        \n    elseif \"LWA_UPDATE_RESOURCES\" == event then\n        aura_env.UpdateResources(arg1)\n    else\n        C_Timer.After(0.05, function()\n                WeakAuras.ScanEvents(\"LWA_UPDATE_RESOURCES\")\n        end)\n    end\n    \n    return true\nend",
["events"] = "OPTIONS,LWA_OPTIONS,LWA_INIT,LWA_UPDATE_RESOURCES,LWA_UPDATE_BAR,PLAYER_ENTERING_WORLD,PLAYER_SPECIALIZATION_CHANGED,UPDATE_SHAPESHIFT_FORM,PLAYER_TALENT_UPDATE,PLAYER_PVP_TALENT_UPDATE,PLAYER_LEVEL_UP,UNIT_PET:player,UNIT_ENTERED_VEHICLE:player,UNIT_EXITED_VEHICLE:player,UNIT_HEALTH:pet,CINEMATIC_STOP,STOP_MOVIE,CLIENT_SCENE_CLOSED,TRAIT_CONFIG_CREATED,TRAIT_CONFIG_UPDATED,TRAIT_TREE_CHANGED",
["custom_type"] = "event",
["names"] = {
},
["subeventPrefix"] = "SPELL",
["spellIds"] = {
},
["custom_hide"] = "custom",
},
["untrigger"] = {
},
},
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["event"] = "GTFO",
["unit"] = "player",
["debuffType"] = "HELPFUL",
["custom"] = "function(event, ...)\n    if not aura_env.parentFrame then\n        aura_env.parentFrame = WeakAuras.GetRegion(aura_env.parent)\n    end\n    \n    local frame = aura_env.parentFrame\n    \n    if frame then\n        local cfg = aura_env.config.alpha\n        local alpha = cfg.global\n        \n        if \"BARBER_SHOP_OPEN\" == event then\n            alpha = 0\n        else\n            local class = UnitClassBase(\"player\")\n            \n            if (IsMounted() and (not cfg.dragonriding_only or (HasBonusActionBar() and (11 == GetBonusBarIndex() or (\"EVOKER\" == class and 7 == GetBonusBarIndex()))))\n                or (not cfg.dragonriding_only and \"DRUID\" == class and (3 == GetShapeshiftForm() or 3 == GetShapeshiftFormID()))) then\n                \n                alpha = min(alpha, cfg.mounted)\n            else\n                if not UnitAffectingCombat(\"player\") then\n                    alpha = min(alpha, cfg.ooc)\n                end\n                \n                if UnitExists(\"target\") then\n                    local isEnemy = UnitCanAttack(\"player\", \"target\") or UnitIsEnemy(\"player\", \"target\")\n                    \n                    if (not isEnemy and cfg.ignore_friendly) or (isEnemy and cfg.ignore_enemy) then\n                        alpha = cfg.global\n                    end\n                end\n            end\n        end\n        \n        frame:SetAlpha(alpha / 100)\n        \n        return true\n    end\n    \n    return false\nend",
["events"] = "PLAYER_ENTERING_WORLD,PLAYER_REGEN_ENABLED,PLAYER_REGEN_DISABLED,PLAYER_TARGET_CHANGED,PLAYER_ALIVE,PLAYER_DEAD,PLAYER_UNGHOST,BARBER_SHOP_OPEN,BARBER_SHOP_CLOSE,OPTIONS,PLAYER_MOUNT_DISPLAY_CHANGED,UPDATE_BONUS_ACTIONBAR,UPDATE_SHAPESHIFT_FORM",
