["Binding Webs"] = {
["iconSource"] = -1,
["wagoID"] = "HCuWvS3wC",
["xOffset"] = 0,
["adjustedMax"] = "",
["customText"] = "function()\n    local u = aura_env.state.unitCaster\n    if aura_env.state and UnitExists(u) then\n        local partner = aura_env.state.unitCaster\n        if UnitIsUnit(\"player\", aura_env.state.unitCaster) then -- 50% chance that unitCaster is the player themselves, in that case we need to find the person in the raid that has the player as their unitcaster\n            for unit in WA_IterateGroupMembers() do\n                local p = select(7, WA_GetUnitDebuff(unit, 440001))\n                if p and UnitIsUnit(\"player\", p) then\n                    partner = unit\n                    break\n                end\n            end\n        end\n        local mydebuff = (WA_GetUnitDebuff(\"player\", 460359) and 1) or (WA_GetUnitDebuff(\"player\", 460281) and 2) or 0\n        local partner = (WA_GetUnitDebuff(partner, 460359) and 1) or (WA_GetUnitDebuff(partner, 460281) and 2) or 0\n        \n        if NSAPI then\n            return NSAPI:Shorten(u, 8), mydebuff == partner and \"|cFF00FF00Same\" or \"|cFFFF0000Opposite\"\n        else\n            return WA_ClassColorName(u), mydebuff == partner and \"|cFF00FF00Same\" or \"|cFFFF0000Opposite\"\n        end\n    end\nend",
