["names"] = {
},
["events"] = "NS_FOOT_TEXT NS_FOOT_HIDE",
["custom"] = "function(s, e, ...)\n    if e == \"OPTIONS\" then\n        local num = math.random(1, 8)\n        local pos = math.random(1, 4)\n        local text = (pos == 1 and \"NOW\") or (pos == 2 and \"2nd\") or (pos == 3 and \"3rd\") or (pos == 4 and \"4th\")\n        s[\"\"] = {\n            show = true,\n            number = num, -- mine number\n            text = text,\n            mark = \"{rt\"..num..\"}\",\n            pos = pos,\n            autoHide = true,\n            changed = true,\n        }\n    elseif e == \"NS_FOOT_TEXT\" then\n        local num, pos, duration = ...\n        local text = (pos == 1 and \"NOW\") or (pos == 2 and \"2nd\") or (pos == 3 and \"3rd\") or (pos == 4 and \"4th\")\n        if duration then\n            s[num] = {\n                show = true,\n                number = num, -- mine number\n                progressType = \"timed\",\n                duration = duration,\n                expirationTime = GetTime()+duration,\n                text = text,\n                mark = \"{rt\"..num..\"}\",\n                pos = pos,\n                autoHide = true,\n                changed = true,\n            }  \n            return true\n        elseif s[num] then\n            s[num].pos = pos\n            s[num].text = text\n            s[num].changed = true     \n            return true\n        end\n    elseif e == \"NS_FOOT_HIDE\" then\n        local num = ...\n        if s[num] then\n            s[num].show = false\n            s[num].changed = true\n            return true\n        end\n    end\nend\n\n\n\n\n\n",
