["init"] = {
["custom"] = "--categoryNumber can be used to differentiate between casts in the conditions for coloring etc\n--role can be (ALL/DAMAGER/HEALER/TANK/MELEE/RANGE) and only shows the bar to that role\n\n--[spellID] = {\"name\",category,\"soundFile\",\"role\", \"show target\" (true/false), \"important\" (true/false)},\naura_env.spellIDs = {\n    \n    --Boralus\n    \n    [257063] = {\"BOLT\",1,\"\",\"ALL\",true,false}, --Brackish Bolt\n    [272581] = {\"BOLT\",1,\"\",\"ALL\",true,false}, --Water Bolt\n    [454440] = {\"VOMIT\",1,\"\",\"ALL\",true,false}, --Stinky Vomit\n    [256639] = {\"BOMB\",2,\"\",\"ALL\",true,false}, --Fire Bomb\n    [257641] = {\"SLUG\",2,\"\",\"ALL\",true,false}, --Molten Slug\n    [272528] = {\"SHOT\",2,\"\",\"ALL\",true,false}, --Shoot\n    [272542] = {\"RICO\",2,\"\",\"ALL\",true,false}, --Ricochet\n    --[272546] = {\"BANANA\",2,\"\",\"ALL\",false,false}, --Banana Rampage\n    [256957] = {\"SHELL\",0,\"\",\"ALL\",false,true}, --Watertight Shell\n    [272571] = {\"CHOKE\",0,\"\",\"ALL\",true,true}, --Choking Waters\n    --[256709] = {\"BUSTER\",2,\"\",\"ALL\",true,false}, --Singing Steel (tank)\n    --[268230] = {\"BUSTER\",2,\"\",\"ALL\",true,false}, --Crimson Swipe (tank)\n    --[272588] = {\"BUSTER\",2,\"\",\"ALL\",true,false}, --Rotting Wounds (tank)\n    --[275835] = {\"BUSTER\",2,\"\",\"ALL\",true,false}, --Stinging Venom Coating (tank)\n    [275826] = {\"SHOUT\",0,\"\",\"ALL\",false,true}, --Bolstering Shout\n    \n    --Ara-Kara\n    \n    [438618] = {\"SPIT\",2,\"\",\"ALL\",true,false}, --Venomous Spit\n    [448248] = {\"VOLLEY\",0,\"\",\"ALL\",false,true}, --Revolting Volley\n    [433841] = {\"VOLLEY\",0,\"\",\"ALL\",false,true}, --Venom Volley\n    [448239] = {\"WEB\",0,\"\",\"ALL\",true,false}, --Web Wrap\n    [434802] = {\"FEAR\",0,\"\",\"ALL\",false,true}, --Horrifying Shrill\n    [434793] = {\"BARRAGE\",0,\"\",\"ALL\",false,true}, --Resonant Barrage\n    [434786] = {\"BOLT\",1,\"\",\"ALL\",true,false}, --Web Bolt\n    [432967]