ALL\",true,true}, --Enveloping Shadowflame\n    [451241] = {\"BUSTER\",2,\"\",\"ALL\",true,false}, --Shadowflame Slash\n    \n    --Necrotic Wake\n    \n    [334747] = {\"THROW\",2,\"\",\"ALL\",true,false}, --Throw Flesh\n    [321780] = {\"ANIMATE\",2,\"\",\"ALL\",false,false}, --Animate Dead\n    --[327393] = {\"GRIM\",2,\"\",\"ALL\",false,false}, --Grim Fate\n    [334748] = {\"DRAIN\",0,\"\",\"ALL\",true,true}, --Drain Fluids\n    [320462] = {\"BOLT\",1,\"\",\"ALL\",true,false}, --Necrotic Bolt\n    [333602] = {\"BOLT\",1,\"\",\"ALL\",true,false}, --Frostbolt\n    [328667] = {\"VOLLEY\",0,\"\",\"ALL\",false,true}, --Frostbolt Volley\n    [333629] = {\"SHOOT\",2,\"\",\"ALL\",true,false}, --Shoot\n    [328687] = {\"SHOOT\",2,\"\",\"ALL\",true,false}, --Shoot\n    [335143] = {\"MEND\",1,\"\",\"ALL\",false,true}, --Bonemend\n    [327130] = {\"REPAIR\",0,\"\",\"ALL\",false,true}, --Repair Flesh\n    [324293] = {\"FEAR\",0,\"\",\"ALL\",false,true}, --Rasping Scream\n    --[320571] = {\"POOL\",1,\"\",\"ALL\",false,false}, --Shadow Well\n    \n    --Stonevault\n    \n    [426283] = {\"ARC\",1,\"\",\"ALL\",true,false}, --Arcing Void\n    [426308] = {\"CURSE\",1,\"\",\"ALL\",true,false}, --Void Infection\n    [449455] = {\"FEAR\",0,\"\",\"ALL\",false,true}, --Howling Fear\n    [429545] = {\"GEAR\",0,\"\",\"ALL\",true,true}, --Censoring Gear\n    [445207] = {\"WAIL\",0,\"\",\"ALL\",false,true}, --Piercing Wail\n    [447141] = {\"LEAP\",2,\"\",\"ALL\",false,false}, --Pulverizing Pounce\n    --[427382] = {\"BUSTER\",2,\"\",\"ALL\",false,false}, --Concussive Smash (tank)\n    [429110] = {\"BOLT\",1,\"\",\"ALL\",true,false}, --Alloy Bolt\n    --[429422] = {\"BOLT\",1,\"\",\"ALL\",true,false}, --Stone Bolt (tank)\n    [429427] = {\"TOTEM\",2,\"\",\"ALL\",false,true}, --Earth Burst Totem\n    [429109] = {\"HEAL\",0,\"\",\"ALL\",false,true}, --Restoring Metals\n    \n    --City of Threads\n    \n    [443427] = {\"BOLT\",1,\"\",\"ALL\",true,false}, --Web Bolt\n    [434122] = {\"BOLT\",1,\"\",\"ALL\",true,false}, --Void Bolt\n    [440160] = {\"BOLT\",1,\"\",\"ALL\",true,false}, --Poison Bolt\n    [443430] = {\"BIND\",0,\"\",\"ALL\",true,true}, --Silk Binding\n    --[443397] = {\"BUSTER\",2,\"\",\"ALL\",true,false}, --Venom Strike (tank)\n    [443433] = {\"TWIST\",0,\"\",\"ALL\",true,true}, --Twist Thoughts\n    [448030] = {\"THROW\",2,\"\",\"ALL\",true,false}, --Knife Throw\n    [442536] = {\"BLAST\",1,\"\",\"ALL\",true,true}, --Grimweave Blast\n    [452162] = {\"HEAL\",0,\"\",\"ALL\",false,true}, --Mending Web\n    [446086] = {\"KNOCK\",1,\"\",\"ALL\",false,true}, --Void Wave\n    --[451238] = {\"BUSTER\",2,\"\",\"ALL\",true,false}, --Brutal Jab (tank)\n    [453840] = {\"ALARM\",0,\"\",\"ALL\",false,true}, --Awakening Calling\n    \n    \n}\n\n-- this is only for spells where the mobs cast it for roleplay purposes and they should only show if target is in party\naura_env.rpspellIDs = {\n    [431303] = true, --Night Bolt\n    [431333] = true, --Tormenting Beam\n    [431637] = true, --Umbral Rush\n    [326319] = true, --Spirit bolt\n}\n\n--[[\ndefault logic:\n- category 0 is for important interruptible casts\n- category 1 is for interruptible casts\n- category 2 is for ccable and not interruptible casts\n]]\n\naura_env.getCastInfo = function(unit)\n    local name, startC, endC, icon, notInterruptible, spellID, duration, expirationTime, _, castType\n    if UnitCastingInfo(unit) then\n        name, _, icon, startC, endC, _, _, notInterruptible, spellID = UnitCastingInfo(unit)\n        castType = \"cast\"\n    elseif UnitChannelInfo(unit) then\n        name, _, icon, startC, endC, _, notInterruptible, spellID = UnitChannelInfo(unit)\n        castType = \"channel\"\n    end\n    if startC and endC then\n        duration = (endC - startC) / 1000\n        expirationTime = endC / 1000\n    end\n    return name, duration, expirationTime, icon, notInterruptible, spellID, castType\nend",
