["spellIds"] = {
},
["custom_type"] = "stateupdate",
["check"] = "event",
["subeventPrefix"] = "SPELL",
["custom"] = "function(s, e, ...)\n    if e == \"NSAPI_ENCOUNTER_START\" then\n        aura_env.spells = {}\n    elseif e == \"NS_BANDIT_NAMEPLATE\" and ... then\n        aura_env.spells = ...\n        for i=1, 40 do\n            local u = \"nameplate\"..i\n            if UnitExists(u) then\n                for _, id in ipairs(aura_env.spells) do\n                    if WA_GetUnitBuff(u, id) then\n                        local G = UnitGUID(u)\n                        s[G] = {\n                            show = true,\n                            changed = true,\n                            progressType = \"static\",\n                            unit = u,\n                            autoHide = true,\n                        }\n                        break\n                    end\n                end\n            end\n        end\n        return true\n    elseif e == \"NAME_PLATE_UNIT_ADDED\" then\n        local u = ...\n        if UnitExists(u) then\n            for _, id in ipairs(aura_env.spells) do\n                if WA_GetUnitBuff(u, id) then\n                    local G = UnitGUID(u)                    \n                    s[G] = {\n                        show = true,\n                        changed = true,\n                        progressType = \"static\",\n                        unit = u,\n                        autoHide = true,\n                    }\n                    return true\n                end\n            end                  \n        end        \n    elseif e == \"NAME_PLATE_UNIT_REMOVED\"  then\n        local u = ...\n        local G = UnitGUID(u)\n        if s[G] then\n            s[G].show = false\n            s[G].changed = true\n            return true\n        end\n        \n    elseif e == \"UNIT_SPELLCAST_START\" and ... then\n        local u, cast, spellID = ... -- Unit event\n        if spellID == 461060 then\n            aura_env.spells = {}\n            for _, v in pairs(s) do\n                v.show = false\n                v.changed = true\n            end\n            return true\n        end\n    end\n    \n    \nend",
