},
["custom"] = "function(s, e , ...)\n    if e == \"ENCOUNTER_START\" then\n        aura_env.GUIDS = {}\n    elseif e == \"NAME_PLATE_UNIT_ADDED\" then\n        local u = ...\n        local G = UnitGUID(u)\n        if aura_env.GUIDS[G] then            \n            local state = {\n                unit = u,\n                progressType = \"static\",\n                autoHide = true,\n            }\n            s:Update(G, state)\n        end\n    elseif e == \"NAME_PLATE_UNIT_REMOVED\" then\n        local u = ...\n        local G = UnitGUID(u)\n        if s[G] then            \n            s:Remove(G)\n        end        \n    else\n        local timestamp, subevent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID = ... -- full CLEU\n        if subevent == \"SPELL_AURA_REMOVED\" and spellID == aura_env.debuff then\n            aura_env.GUIDS[destGUID] = true\n            for i=1, 40 do\n                local u = \"nameplate\"..i\n                if UnitExists(u) and UnitGUID(u) == destGUID then\n                    local state = {\n                        unit = u,\n                        progressType = \"static\",\n                        autoHide = true,\n                    }\n                    s:Update(destGUID, state)\n                end\n            end            \n        elseif subevent == \"SPELL_CAST_SUCCESS\" and spellID == aura_env.grip then\n            if aura_env.GUIDS[destGUID] then\n                aura_env.GUIDS[destGUID] = nil\n            end\n            if s[destGUID] then\n                s:Remove(destGUID)\n            end\n        end\n    end\nend",
["events"] = "CLEU:SPELL_CAST_SUCCESS:SPELL_AURA_REMOVED NAME_PLATE_UNIT_ADDED NAME_PLATE_UNIT_REMOVED ENCOUNTER_START",
