["Shadowgate Assign"] = {
["outline"] = "OUTLINE",
["limitWeakAuras"] = {
["hash"] = "4e8efc44e735360567789a00155f766659fc398a062f1e0aa8dc783b0677fd46",
},
["wagoID"] = "foNlg79Ol",
["xOffset"] = -150,
["displayText_format_p_time_dynamic_threshold"] = 0,
["yOffset"] = 50,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://wago.io/NSNerubarPalace/54",
["actions"] = {
["start"] = {
["sound"] = "Interface\\Addons\\NorthernSkyMedia\\Media\\Sounds\\Gate.ogg",
["do_sound"] = true,
},
["init"] = {
["custom"] = "aura_env.debug = false\naura_env.cast = aura_env.debug and 8690 or 460369\naura_env.debuff = aura_env.debug and 774 or 460218\naura_env.filter = aura_env.debug and \"HELPFUL\" or \"HARMFUL\"\n\n\naura_env.MRT = function()\n    aura_env.list = {\n        [1] = {},\n        [2] = {},\n    }\n    if C_AddOns.IsAddOnLoaded(\"MRT\") and VMRT.Note.Text1 then\n        local text = _G.VMRT.Note.Text1\n        local list = false\n        text = text:gsub(\"||r\", \"\") -- clean colorcode\n        text = text:gsub(\"||c%x%x%x%x%x%x%x%x\", \"\") -- clean colorcode\n        local current = 0\n        for line in text:gmatch('[^\\r\\n]+') do\n            line = strtrim(line) --trim whitespace\n            --check for start/end of the name list\n            if strlower(line) == \"nsgatestart\" then\n                list = true\n            elseif strlower(line) == \"nsgateend\" then                \n                list = false\n            end\n            \n            if list then \n                line = line:gsub(\"{.-}\", \"\") -- cleaning markers from line\n                for name in line:gmatch(\"%S+\") do -- finding all remaining strings\n                    if name == \"left\" then\n                        current = 1\n                    elseif name == \"right\" then\n                        current = 2\n                    end\n                    if NSAPI then\n                        name = NSAPI:GetChar(name)\n                    end\n                    if UnitInRaid(name) then\n                        table.insert(aura_env.list[current], \"raid\"..UnitInRaid(name))\n                    else -- checking for nickname if string didn't match player\n                        for unit in WA_IterateGroupMembers() do\n                            local uname = UnitName(unit)\n                            if uname:match(name) then\n                                table.insert(aura_env.list[current], \"raid\"..UnitInRaid(uname))  \n                                break\n                            end\n                        end\n                    end\n                end\n            end\n        end\n    end   \nend\n\n\n\n\n\n\n\n\n\n\n\n\n",
["do_custom"] = true,
},
["finish"] = {
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["customVariables"] = "{\n    casts = \"number\",\n}\n\n\n",
["event"] = "Health",
["unit"] = "player",
["subeventSuffix"] = "_CAST_START",
["subeventPrefix"] = "SPELL",
["custom"] = "function(s, e, ...)\n    if e == \"OPTIONS\" then        \n        s[UnitGUID(\"player\")] = {\n            show = true,\n            progressType = \"timed\",\n            duration = 10,\n            expirationTime = 10+GetTime(),\n            casts = math.random(1, 2),\n            num = math.random(1, 2),\n            text = \"Take Gate\",\n            autoHide = true,\n            changed = true,\n        }\n        return true\n    elseif e == \"NSAPI_ENCOUNTER_START\" then\n        aura_env.GUIDS = {}\n        aura_env.side = 1 -- assume start on left\n        aura_env.active = {}\n        aura_env.casts = {}\n        aura_env.MRT()        \n    elseif e == \"NS_ASSIGN_EVENT\" and ... and aura_env.id == ... then\n        local casts = select(2, ...)\n        local now = GetTime()\n        for i = 1, 2 do\n            local expires = aura_env.active[i]\n            local num = i\n            if expires and expires > now then\n                for _, v in ipairs(aura_env.list[num]) do\n                    if UnitExists(v) and not (UnitIsDead(v)) and not (WA_GetUnitAura(v, aura_env.debuff, aura_env.filter)) and not (WA_GetUnitBuff(v, 27827)) then\n                        WeakAuras.ScanEvents(\"NS_GATE_LIST\", v, num, expires)\n                        if UnitIsUnit(v, \"player\") then\n                            s[UnitGUID(\"player\")] = {\n                                show = true,\n                                progressType = \"timed\",\n                                duration = 10,\n                                expirationTime = expires,\n                                casts = casts,\n                                num = i,\n                                text = \"Take Gate\",\n                                autoHide = true,\n                                changed = true,\n                            }\n                        end\n                        break -- break after first valid assignment found\n                    end\n                end\n            end\n        end   \n        return true\n    elseif e == \"NS_GATE_STOP\" and ... then\n        local G = ...\n        if s[G] then\n            s[G].show = false\n            s[G].changed = true\n            return true\n        end\n    elseif e == \"NS_GATE_STOP_ALL\" and ... then\n        for _, v in pairs(s) do\n            v.show = false\n            v.changed = true\n        end\n        return true\n    else   \n        local timestamp, subevent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID = ... -- full CLEU\n        if subevent == \"SPELL_CAST_START\" and spellID == aura_env.cast then\n            local side = aura_env.side\n            local now = GetTime()\n            if aura_env.GUIDS[sourceGUID] then -- portal has already casted before so we know the side\n                side = aura_env.GUIDS[sourceGUID]\n                aura_env.casts[sourceGUID] = aura_env.casts[sourceGUID]+1\n                aura_env.active[side] = now+10\n                aura_env.side = side+1\n                if aura_env.side >= 3 then\n                    aura_env.side = 1\n                end\n                \n            else -- first cast of that gate, which means we don't know which one spawned first. Just assuming left first as it largely doesn't matter           \n                aura_env.GUIDS[sourceGUID] = side\n                aura_env.casts[sourceGUID] = 1\n                aura_env.active[aura_env.side] = now+10\n                aura_env.side = aura_env.side+1\n                if aura_env.side >= 3 then\n                    aura_env.side = 1\n                end\n                \n            end\n            WeakAuras.ScanEvents(\"NS_ASSIGN_EVENT\", aura_env.id, aura_env.casts[sourceGUID])\n        elseif subevent == \"SPELL_AURA_APPLIED\" and spellID == aura_env.debuff then\n            local unit = UnitInRaid(destName) and \"raid\"..UnitInRaid(destName) or \"\"\n            local gateside = aura_env.GUIDS[sourceGUID]\n            aura_env.active[gateside] = false\n            if (gateside == 1 and tIndexOf(aura_env.list[1], unit)) or (gateside == 2 and tIndexOf(aura_env.list[2], unit)) then -- unit and gate match\n                -- do nothing\n            else -- unit and gateside don't match, which means the initial assignment was probably wrong\n                local temp = aura_env.active[1]\n                aura_env.active[1] = aura_env.active[2]\n                aura_env.active[2] = temp\n                for k, v in pairs(aura_env.GUIDS) do -- swap around the stored side\n                    if v == 1 then\n                        aura_env.GUIDS[k] = 2\n                    else\n                        aura_env.GUIDS[k] = 1\n                    end\n                end\n                -- don't think I need to reassign anything because this can only happen on the first gates and those both have the same timer anyway.\n            end\n            WeakAuras.ScanEvents(\"NS_GATE_STOP\", destGUID)\n        elseif subevent == \"UNIT_DIED\" then\n            local id = select(6, strsplit(\"-\", destGUID))\n            if id == \"223150\" then\n                aura_env.side = 1\n                aura_env.active[1] = false\n                aura_env.active[2] = false\n                WeakAuras.ScanEvents(\"NS_GATE_STOP_ALL\", true)\n            end\n        end\n    end\nend\n\n\n\n\n\n\n",
